helpers.code:
selected =
  if assigns.multiple do
    assigns.opt.value in List.wrap(assigns.value)
  else
    assigns.opt.value == assigns.value
  end

assigns = assign(assigns, :selected, selected)

~H"""
<li
  id={"#{@id}-opt-#{@opt.__i__}"}
  role="option"
  data-part="item"
  data-value={@opt.value}
  data-disabled={@opt[:disabled] || false}
  data-selected={@selected}
  aria-selected={to_string(@selected)}
  aria-disabled={(@opt[:disabled] && "true") || nil}
  class={["chelekom-combobox__item", @item_class, @opt[:class]]}
>
  <span
    data-part="indicator"
    aria-hidden="true"
    class={["chelekom-combobox__indicator", @indicator_class]}
  >{render_slot(@item_indicator)}</span>
  {render_slot(@opt)}
</li>
"""

options
|> Enum.with_index()
|> Enum.chunk_by(fn {opt, _i} -> opt[:group] end)
|> Enum.map(fn [{first, _} | _] = chunk ->
  %{label: first[:group], options: Enum.map(chunk, fn {opt, i} -> Map.put(opt, :__i__, i) end)}
end)

~H"""
<div
  data-part="separator"
  role="separator"
  aria-orientation={if @orientation == "horizontal", do: "vertical", else: "horizontal"}
  data-orientation={@orientation}
  class={["chelekom-toolbar__separator", @item[:class]]}
>
</div>
"""

~H"""
<a
  data-part="link"
  href={@item[:href] || "#"}
  aria-label={@item[:label]}
  data-orientation={@orientation}
  tabindex={if @item == @first, do: "0", else: "-1"}
  class={["chelekom-toolbar__link", @item[:class]]}
>
  {render_slot(@item)}
</a>
"""

dis = assigns.disabled || assigns.item[:disabled]
assigns = assign(assigns, :dis, dis)

~H"""
<input
  type="text"
  data-part="input"
  placeholder={@item[:placeholder]}
  value={@item[:value]}
  aria-label={@item[:label]}
  aria-disabled={@dis && "true"}
  data-disabled={@dis}
  data-focusable
  data-orientation={@orientation}
  tabindex={if @item == @first, do: "0", else: "-1"}
  class={["chelekom-toolbar__input", @item[:class]]}
/>
"""

dis = assigns.disabled || assigns.item[:disabled]
assigns = assign(assigns, :dis, dis)

~H"""
<button
  type="button"
  data-part="button"
  aria-label={@item[:label]}
  aria-disabled={@dis && "true"}
  data-disabled={@dis}
  data-focusable
  data-orientation={@orientation}
  tabindex={if @item == @first, do: "0", else: "-1"}
  class={["chelekom-toolbar__button", @item[:class]]}
>
  {render_slot(@item)}
</button>
"""

items
|> Enum.chunk_by(& &1[:group])
|> Enum.map(fn [first | _] = chunk ->
  %{label: first[:group], class: first[:group_class], items: chunk}
end)

~H"""
<button
  id={@id}
  type="button"
  phx-hook="GlobalToggle"
  role="checkbox"
  aria-checked={(@indeterminate && "mixed") || to_string(@checked)}
  data-disabled={@disabled}
  data-parent={@parent}
  data-checked={@checked && !@indeterminate}
  data-unchecked={!@checked && !@indeterminate}
  data-indeterminate={@indeterminate}
  data-value={@value}
  data-part="item"
  class={["chelekom-checkbox_group__item", @item_class]}
>
  <input
    :if={@name}
    type="checkbox"
    data-part="input"
    name={@name}
    value={@value}
    checked={@checked && !@indeterminate}
    disabled={@disabled}
    tabindex="-1"
    aria-hidden="true"
    class="chelekom-checkbox_group__input chelekom-sr-only"
  />
  <span
    data-part="indicator"
    aria-hidden="true"
    data-checked={@checked && !@indeterminate}
    data-unchecked={!@checked && !@indeterminate}
    data-indeterminate={@indeterminate}
    class={["chelekom-checkbox_group__indicator", @indicator_class]}
  >
    {render_slot(@indicator_icon)}
  </span>
  {render_slot(@inner_block)}
</button>
"""

enabled = Enum.reject(items, &(&1[:disabled] || false))
checked = Enum.count(enabled, &(&1[:checked] || false))

cond do
  enabled == [] or checked == 0 -> {false, false}
  checked == length(enabled) -> {true, false}
  true -> {false, true}
end

node = assigns.node
children = Map.get(node, :children) || []
has_children = children != [] || Map.get(node, :has_children, false)

assigns =
  assigns
  |> assign(:children, children)
  |> assign(:has_children, has_children)
  |> assign(:value, node.value)
  |> assign(:expanded, MapSet.member?(assigns.expanded_set, node.value))
  |> assign(:selected, MapSet.member?(assigns.selected_set, node.value))
  |> assign(:checked, checked?(node, children, assigns.checked_set))
  |> assign(:indeterminate, indeterminate?(node, children, assigns.checked_set))
  |> assign(:disabled, Map.get(node, :disabled, false))
  |> assign(:selectable, Map.get(node, :selectable, true))

~H"""
<li
  role="treeitem"
  data-value={@value}
  data-level={@level}
  data-expanded={@has_children && to_string(@expanded)}
  data-has-children={@has_children && "true"}
  data-selected={@selected && "true"}
  data-checked={@with_checkboxes && to_string(@checked)}
  data-indeterminate={@indeterminate && "true"}
  data-disabled={@disabled && "true"}
  data-selectable={!@selectable && "false"}
  aria-disabled={@disabled && "true"}
  aria-level={@level}
  aria-setsize={@setsize}
  aria-posinset={@posinset}
  aria-expanded={@has_children && to_string(@expanded)}
  {aria_state(@with_checkboxes, @selectable, @selected, @checked, @indeterminate)}
  tabindex={if(@root_index == 0, do: "0", else: "-1")}
  style={"--label-offset: calc(var(--level-offset) * #{@level - 1});"}
  class={["chelekom-tree__node", @node_class]}
>
  <div
    data-part="label"
    data-selected={@selected && "true"}
    draggable={@draggable && !@with_drag_handle && "true"}
    class={["chelekom-tree__label", @label_class]}
  >
    <span
      :if={@draggable && @with_drag_handle}
      data-part="drag-handle"
      draggable="true"
      aria-label={@drag_handle_label}
      class={["chelekom-tree__drag-handle", @drag_handle_class]}
    >
      {render_slot(@drag_icon)}
    </span>

    <input
      :if={@with_checkboxes}
      type="checkbox"
      data-part="checkbox"
      name={@name}
      value={@name && @value}
      checked={@checked}
      disabled={@disabled}
      tabindex="-1"
      aria-hidden="true"
      class={["chelekom-tree__checkbox", @checkbox_class]}
    />

    <span
      :if={@with_expand_icon}
      data-part="expand-icon"
      data-has-children={@has_children && "true"}
      aria-hidden="true"
      class={["chelekom-tree__expand-icon", @expand_icon_class]}
    >
      <%= if @has_children do %>
        {render_slot(@expand_icon)}
      <% end %>
    </span>

    <span data-part="label-text" class={["chelekom-tree__label-text", @label_text_class]}>
      <%= if @node_slot != [] do %>
        {render_slot(@node_slot, %{
          node: @node,
          icon: Map.get(@node, :icon),
          level: @level,
          expanded: @expanded,
          selected: @selected,
          checked: @checked,
          indeterminate: @indeterminate,
          has_children: @has_children,
          is_root: @level == 1
        })}
      <% else %>
        {label_text(@node)}
      <% end %>
    </span>

    <span data-part="loader" class={["chelekom-tree__loader", @loader_class]}>
      {render_slot(@loader)}
    </span>
  </div>

  <ul
    :if={@has_children && (@keep_mounted || @expanded) && @children != []}
    role="group"
    data-part="subtree"
    data-level={@level}
    hidden={!@expanded}
    class={["chelekom-tree__subtree", @subtree_class]}
  >
    <.tree_node
      :for={{child, index} <- Enum.with_index(@children)}
      node={child}
      level={@level + 1}
      setsize={length(@children)}
      posinset={index + 1}
      expanded_set={@expanded_set}
      selected_set={@selected_set}
      checked_set={@checked_set}
      with_checkboxes={@with_checkboxes}
      with_expand_icon={@with_expand_icon}
      keep_mounted={@keep_mounted}
      draggable={@draggable}
      with_drag_handle={@with_drag_handle}
      drag_handle_label={@drag_handle_label}
      node_class={@node_class}
      label_class={@label_class}
      subtree_class={@subtree_class}
      checkbox_class={@checkbox_class}
      expand_icon_class={@expand_icon_class}
      drag_handle_class={@drag_handle_class}
      label_text_class={@label_text_class}
      loader_class={@loader_class}
      node_slot={@node_slot}
      expand_icon={@expand_icon}
      drag_icon={@drag_icon}
      loader={@loader}
      name={@name}
    />
  </ul>
</li>
"""

js_hooks.content:
// Slider — headless single- or multi-thumb slider engine (Base UI parity).
//
// Anatomy: a `[data-part="control"]` holds a `[data-part="track"]` containing a
// `[data-part="indicator"]` (the filled interval) and one `[data-part="thumb"]` (role=slider) per
// value. Pointer drag on the control + keyboard on a thumb: Arrow ±step (Up/Right increase),
// Shift+Arrow / PageUp/Down ±largeStep, Home/End → min/max. Range thumbs keep `minStepsBetweenValues`
// apart and obey `data-collision` (push | swap | none). Vertical via `data-orientation="vertical"`.
//
// Reflects Base UI data-attributes: `data-orientation` (all parts), `data-dragging` (root/control/
// thumb while dragging), `data-disabled`, thumb `data-index`. Each thumb is role=slider with
// `aria-valuemin/max/now`, `aria-valuetext` (Intl-formatted via `data-format`/`data-locale`) and
// `aria-orientation`. The value(s) mirror into hidden inputs (single → `name`, range → `name[]`) with
// a bubbling `input` (so `<.form phx-change>` fires); `data-on-change` (`{value}`) and `data-on-commit`
// (`{value}`) push to LiveView. The latest ratio is exposed as `--chelekom-slider` on the root.

const Slider = {
  mounted() {
    const el = this.el;
    this.control = el.querySelector('[data-part="control"]') || el.querySelector('[data-part="track"]') || el;
    this.track = el.querySelector('[data-part="track"]') || this.control;
    this.indicator = el.querySelector('[data-part="indicator"]');
    this.thumbs = Array.from(el.querySelectorAll('[data-part="thumb"]'));
    this.valueEl = el.querySelector('[data-part="value"]');

    const num = (a, d) => (el.getAttribute(a) != null ? parseFloat(el.getAttribute(a)) : d);
    this.min = num("data-min", 0);
    this.max = num("data-max", 100);
    this.step = num("data-step", 1) || 1;
    this.largeStep = num("data-large-step", 10) || 10;
    this.minSteps = num("data-min-steps", 0);
    this.vertical = el.getAttribute("data-orientation") === "vertical";
    this.disabled = el.hasAttribute("data-disabled");
    this.collision = el.getAttribute("data-collision") || "push";
    this.name = el.getAttribute("data-name");
    this.onChange = el.getAttribute("data-on-change");
    this.onCommit = el.getAttribute("data-on-commit");
    this.locale = el.getAttribute("data-locale") || undefined;
    try {
      this.format = el.getAttribute("data-format") ? JSON.parse(el.getAttribute("data-format")) : undefined;
    } catch {
      this.format = undefined;
    }

    this.values = this.thumbs.map((t) => parseFloat(t.getAttribute("data-value") ?? String(this.min)));
    this.setupThumbs();

    // Pressing the track jumps the nearest thumb to the pointer, then drags it.
    if (!this.disabled) this.control.addEventListener("pointerdown", (e) => this.onTrackPress(e));

    this.render();
  },

  // Configure each thumb (aria + roving) and bind its keyboard/drag listeners. Safe to re-run after a
  // server patch: a per-element guard flag stops surviving thumbs from being double-bound.
  setupThumbs() {
    this.thumbs = Array.from(this.el.querySelectorAll('[data-part="thumb"]'));
    this.thumbs.forEach((thumb, i) => {
      thumb.setAttribute("role", "slider");
      thumb.setAttribute("aria-valuemin", String(this.min));
      thumb.setAttribute("aria-valuemax", String(this.max));
      thumb.setAttribute("aria-orientation", this.vertical ? "vertical" : "horizontal");
      thumb.setAttribute("data-index", String(i));
      thumb.setAttribute("tabindex", this.disabled ? "-1" : "0");
      if (!this.disabled && !thumb._sliderBound) {
        thumb._sliderBound = true;
        thumb.addEventListener("keydown", (e) => this.onKey(e, i));
        thumb.addEventListener("keyup", () => this.commit());
        thumb.addEventListener("pointerdown", (e) => {
          e.stopPropagation();
          this.startDrag(e, i);
        });
      }
    });
  },

  // A server re-render (e.g. a form submit) re-patches the DOM and strips the hook's client-set inline
  // positioning. Re-read the server values and re-apply the layout, so the thumb/indicator don't
  // collapse into the corner until the next drag.
  updated() {
    this.indicator = this.el.querySelector('[data-part="indicator"]');
    this.valueEl = this.el.querySelector('[data-part="value"]');
    this.setupThumbs();
    this.values = this.thumbs.map((t) => parseFloat(t.getAttribute("data-value") ?? String(this.min)));
    this.render();
  },

  fmt(v) {
    try {
      return new Intl.NumberFormat(this.locale, this.format).format(v);
    } catch {
      return String(v);
    }
  },

  // ---- pointer --------------------------------------------------------------

  ratioFromPointer(e) {
    const r = this.control.getBoundingClientRect();
    const ratio = this.vertical
      ? (r.bottom - e.clientY) / r.height // bottom = min, top = max
      : (e.clientX - r.left) / r.width;
    return Math.min(1, Math.max(0, ratio));
  },

  nearestThumb(value) {
    let best = 0;
    let bestD = Infinity;
    this.values.forEach((v, i) => {
      const d = Math.abs(v - value);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    });
    return best;
  },

  onTrackPress(e) {
    if (this.disabled) return;
    const value = this.min + this.ratioFromPointer(e) * (this.max - this.min);
    const i = this.nearestThumb(value);
    this.thumbs[i].focus();
    this.set(i, value, "track-press");
    this.startDrag(e, i);
  },

  startDrag(e, i) {
    e.preventDefault();
    const thumb = this.thumbs[i];
    thumb.focus();
    this.setDragging(thumb, true);
    // Capture the pointer so the drag keeps tracking outside the element, and lock the cursor to
    // "grabbing" for the whole gesture — otherwise it flickers (grab ↔ default) as the moving thumb
    // slides out from under the physical pointer.
    try {
      thumb.setPointerCapture(e.pointerId);
    } catch {}
    const prevCursor = document.body.style.cursor;
    const prevSelect = document.body.style.userSelect;
    document.body.style.cursor = "grabbing";
    document.body.style.userSelect = "none";
    const move = (ev) => {
      const value = this.min + this.ratioFromPointer(ev) * (this.max - this.min);
      this.set(i, value, "drag");
    };
    const up = () => {
      document.removeEventListener("pointermove", move);
      document.removeEventListener("pointerup", up);
      this.setDragging(thumb, false);
      document.body.style.cursor = prevCursor;
      document.body.style.userSelect = prevSelect;
      try {
        thumb.releasePointerCapture(e.pointerId);
      } catch {}
      this.commit();
    };
    document.addEventListener("pointermove", move);
    document.addEventListener("pointerup", up);
  },

  setDragging(thumb, on) {
    [this.el, this.control, thumb].forEach((n) => n && n.toggleAttribute("data-dragging", on));
  },

  // ---- keyboard -------------------------------------------------------------

  onKey(e, i) {
    if (this.disabled) return;
    const inc = e.shiftKey ? this.largeStep : this.step;
    // Up/Right increase, Down/Left decrease (works for both orientations).
    const map = {
      ArrowRight: inc,
      ArrowUp: inc,
      ArrowLeft: -inc,
      ArrowDown: -inc,
      PageUp: this.largeStep,
      PageDown: -this.largeStep,
    };
    if (e.key in map) {
      e.preventDefault();
      this.set(i, this.values[i] + map[e.key], "keyboard");
    } else if (e.key === "Home") {
      e.preventDefault();
      this.set(i, this.min, "keyboard");
    } else if (e.key === "End") {
      e.preventDefault();
      this.set(i, this.max, "keyboard");
    }
  },

  // ---- value mutation (step / clamp / collision) ----------------------------

  snap(raw) {
    const v = this.min + Math.round((raw - this.min) / this.step) * this.step;
    return Math.min(this.max, Math.max(this.min, parseFloat(v.toFixed(6))));
  },

  set(i, raw, reason) {
    const gap = this.minSteps * this.step;
    let v = this.snap(raw);
    const n = this.values.length;

    if (n === 1) {
      this.values[0] = v;
    } else if (this.collision === "none") {
      const lo = i > 0 ? this.values[i - 1] + gap : this.min;
      const hi = i < n - 1 ? this.values[i + 1] - gap : this.max;
      this.values[i] = Math.min(hi, Math.max(lo, v));
    } else if (this.collision === "swap") {
      this.values[i] = v;
      // re-sort and follow the dragged value's new index
      const order = this.values.map((val, idx) => ({ val, idx })).sort((a, b) => a.val - b.val);
      this.values = order.map((o) => o.val);
      this._activeIndex = order.findIndex((o) => o.idx === i);
    } else {
      // push (default): move neighbors out of the way, cascading, clamped to min/max.
      this.values[i] = v;
      for (let j = i + 1; j < n; j++) {
        if (this.values[j] < this.values[j - 1] + gap) this.values[j] = Math.min(this.max, this.values[j - 1] + gap);
      }
      for (let j = i - 1; j >= 0; j--) {
        if (this.values[j] > this.values[j + 1] - gap) this.values[j] = Math.max(this.min, this.values[j + 1] - gap);
      }
      // if pushing hit a wall, clamp the dragged thumb back
      const lo = i > 0 ? this.values[i - 1] + gap : this.min;
      const hi = i < n - 1 ? this.values[i + 1] - gap : this.max;
      this.values[i] = Math.min(hi, Math.max(lo, this.values[i]));
    }

    this.render();
    if (this.onChange) this.pushEventTo(this.el, this.onChange, { value: n === 1 ? this.values[0] : this.values.slice() });
  },

  commit() {
    // Notify any enclosing <.form phx-change> at interaction-end (not per drag-pixel): the hidden
    // inputs are set programmatically every render, but we only dispatch the event on commit.
    const anyInput = this.el.querySelector('[data-part="input"]');
    if (anyInput) anyInput.dispatchEvent(new Event("input", { bubbles: true }));
    if (this.onCommit) this.pushEventTo(this.el, this.onCommit, { value: this.values.length === 1 ? this.values[0] : this.values.slice() });
  },

  // ---- render ---------------------------------------------------------------

  ratio(v) {
    return (v - this.min) / (this.max - this.min || 1);
  },

  render() {
    // The engine owns LAYOUT (mirrors Base UI's SliderThumb/SliderIndicator); the consumer's CSS owns
    // only APPEARANCE. Thumb: anchor the value edge (bottom for vertical, left for horizontal), center
    // the cross axis at 50%, and translate by half so the thumb's centre sits on the track.
    this.thumbs.forEach((thumb, i) => {
      const pct = this.ratio(this.values[i]) * 100;
      thumb.style.position = "absolute";
      if (this.vertical) {
        thumb.style.bottom = `${pct}%`;
        thumb.style.left = "50%";
        thumb.style.top = "";
        thumb.style.translate = "-50% 50%";
      } else {
        thumb.style.left = `${pct}%`;
        thumb.style.top = "50%";
        thumb.style.bottom = "";
        thumb.style.translate = "-50% -50%";
      }
      thumb.setAttribute("aria-valuenow", String(this.values[i]));
      thumb.setAttribute("aria-valuetext", this.fmt(this.values[i]));
      const input = thumb.querySelector('[data-part="input"]');
      if (input && input.value !== String(this.values[i])) input.value = String(this.values[i]);
    });

    if (this.indicator && this.values.length) {
      // The filled bar spans `first`%→`last`%; the cross axis inherits the track size (so it's exactly
      // as wide/tall as the track and needs no centering). Vertical is absolute from the bottom;
      // horizontal is relative (Base UI's SliderIndicator).
      const first = (this.values.length > 1 ? this.ratio(this.values[0]) : 0) * 100;
      const last = this.ratio(this.values[this.values.length - 1]) * 100;
      const size = last - first;
      if (this.vertical) {
        this.indicator.style.position = "absolute";
        this.indicator.style.width = "inherit";
        this.indicator.style.height = `${size}%`;
        this.indicator.style.bottom = `${first}%`;
        this.indicator.style.left = "";
        this.indicator.style.top = "";
      } else {
        this.indicator.style.position = "relative";
        this.indicator.style.height = "inherit";
        this.indicator.style.width = `${size}%`;
        this.indicator.style.left = `${first}%`;
        this.indicator.style.bottom = "";
        this.indicator.style.top = "";
      }
    }

    if (this.valueEl) this.valueEl.textContent = this.values.map((v) => this.fmt(v)).join(" – ");

    this.el.style.setProperty("--chelekom-slider", String(this.ratio(this.values[this.values.length - 1])));
  },
};

export default Slider;

// Popover — headless popover engine (Base UI parity).
//
// A `[data-part="trigger"]` button toggles an anchored `[data-part="popup"]` (role=dialog)
// panel of arbitrary content, positioned by side/align/offset with edge-flip + viewport
// clamp (repositioned on scroll/resize). Optional hover-open. `modal`:
//   • false (default) — page stays interactive; outside click / Escape dismiss; focus moves
//     into the popup and returns to the trigger.
//   • "trap-focus"    — focus trapped; page scrollable; outside pointers live.
//   • true            — focus trapped, background scroll locked, a backdrop dims the page.
// initial_focus / final_focus override what's focused on open / close. Motion + color are
// 100% CSS — the hook only toggles data-* state and positions.

const FOCUSABLE =
  'a[href],button:not([disabled]),textarea:not([disabled]),input:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])';
const PAD = 8;

let scrollLocks = 0;
let savedOverflow = "";
let savedPadRight = "";
function lockScrollGlobal() {
  if (scrollLocks === 0) {
    const body = document.body;
    const sbw = window.innerWidth - document.documentElement.clientWidth;
    savedOverflow = body.style.overflow;
    savedPadRight = body.style.paddingRight;
    body.style.overflow = "hidden";
    if (sbw > 0) body.style.paddingRight = `${(parseFloat(getComputedStyle(body).paddingRight) || 0) + sbw}px`;
  }
  scrollLocks += 1;
}
function unlockScrollGlobal() {
  scrollLocks = Math.max(0, scrollLocks - 1);
  if (scrollLocks === 0) {
    document.body.style.overflow = savedOverflow;
    document.body.style.paddingRight = savedPadRight;
  }
}

const Popover = {
  mounted() {
    this.trigger = this.el.querySelector('[data-part="trigger"]');
    this.popup = this.el.querySelector('[data-part="popup"]');
    this.backdrop = this.el.querySelector('[data-part="backdrop"]');

    this.side = this.el.getAttribute("data-side") || "bottom";
    this.align = this.el.getAttribute("data-align") || "center";
    this.sideOffset = parseFloat(this.el.getAttribute("data-side-offset")) || 0;
    this.alignOffset = parseFloat(this.el.getAttribute("data-align-offset")) || 0;
    this.modal = this.el.getAttribute("data-modal") || "false"; // false | true | trap-focus
    this.trapFocus = this.modal !== "false";
    this.openOnHover = this.el.getAttribute("data-open-on-hover") === "true";
    this.delay = parseFloat(this.el.getAttribute("data-delay"));
    this.closeDelay = parseFloat(this.el.getAttribute("data-close-delay"));
    if (Number.isNaN(this.delay)) this.delay = 300;
    if (Number.isNaN(this.closeDelay)) this.closeDelay = 0;
    this.closeOnEscape = this.el.getAttribute("data-close-on-escape") !== "false";
    this.closeOnOutside = this.el.getAttribute("data-close-on-outside") !== "false";
    this.disabled = this.el.getAttribute("data-disabled") === "true";
    this.initialFocusSel = this.el.getAttribute("data-initial-focus");
    this.finalFocusSel = this.el.getAttribute("data-final-focus");
    this.onOpenChange = this.el.getAttribute("data-on-open-change");
    this.onOpenChangeTarget = this.el.getAttribute("data-on-open-change-target");

    this.active = false;
    this.boundKeydown = (e) => this.handleKeydown(e);
    this.boundOutside = (e) => this.handleOutside(e);
    this.boundReposition = () => this.reposition();

    if (this.trigger && this.popup && this.popup.id) {
      this.trigger.setAttribute("aria-haspopup", "dialog");
      this.trigger.setAttribute("aria-controls", this.popup.id);
      this.trigger.setAttribute("aria-expanded", "false");
      this.trigger.addEventListener("click", () => {
        if (this.disabled || this.trigger.hasAttribute("data-disabled")) return;
        this.active ? this.close() : this.open();
      });
      if (this.openOnHover) {
        this.trigger.addEventListener("pointerenter", () => this.scheduleHoverOpen());
        this.trigger.addEventListener("pointerleave", () => this.scheduleHoverClose());
      }
    }

    if (this.openOnHover && this.popup) {
      this.popup.addEventListener("pointerenter", () => this.cancelHoverClose());
      this.popup.addEventListener("pointerleave", () => this.scheduleHoverClose());
    }
    if (this.backdrop) this.backdrop.addEventListener("click", () => this.closeOnOutside && this.close());
    this.el.querySelectorAll("[data-close]").forEach((b) => b.addEventListener("click", () => this.close()));

    if (this.el.hasAttribute("data-open")) this.open();
  },

  updated() {
    const wantsOpen = this.el.hasAttribute("data-open");
    if (wantsOpen && !this.active) this.open(true);
    else if (!wantsOpen && this.active) this.close(true);
  },

  destroyed() {
    this.teardown();
    if (this.hoverTimer) clearTimeout(this.hoverTimer);
  },

  // ---- open / close ------------------------------------------------------
  open(serverDriven = false) {
    if (this.active) return;
    this.active = true;
    this.opener = document.activeElement;
    this.positionPopup();
    this.popup.hidden = false;
    this.popup.toggleAttribute("data-open", true);
    this.popup.removeAttribute("data-closed");
    this.popup.setAttribute("data-starting-style", "");
    requestAnimationFrame(() =>
      requestAnimationFrame(() => this.popup && this.popup.removeAttribute("data-starting-style")),
    );
    this.el.toggleAttribute("data-open", true);
    this.el.toggleAttribute("data-closed", false);
    if (this.trigger) {
      this.trigger.setAttribute("aria-expanded", "true");
      this.trigger.toggleAttribute("data-popup-open", true);
      this.trigger.toggleAttribute("data-pressed", true);
    }
    if (this.modal === "true") {
      lockScrollGlobal();
      this._locked = true;
    }
    document.addEventListener("keydown", this.boundKeydown, true);
    window.addEventListener("scroll", this.boundReposition, true);
    window.addEventListener("resize", this.boundReposition);
    this.allowOutside = false;
    setTimeout(() => {
      this.allowOutside = true;
      document.addEventListener("pointerdown", this.boundOutside, true);
    }, 60);
    const target = this.initialFocusEl() || this.focusables()[0] || this.popup;
    if (target && target.focus) requestAnimationFrame(() => target.focus({ preventScroll: true }));
    if (!serverDriven) this.emitOpenChange(true);
  },

  close(serverDriven = false) {
    if (!this.active) return;
    this.active = false;
    this.popup.toggleAttribute("data-open", false);
    this.popup.setAttribute("data-closed", "");
    this.popup.hidden = true;
    this.el.toggleAttribute("data-open", false);
    this.el.toggleAttribute("data-closed", true);
    if (this.trigger) {
      this.trigger.setAttribute("aria-expanded", "false");
      this.trigger.toggleAttribute("data-popup-open", false);
      this.trigger.toggleAttribute("data-pressed", false);
    }
    this.teardown();
    const target = this.finalFocusEl() || this.trigger || this.opener;
    if (target && target.focus) target.focus({ preventScroll: true });
    if (!serverDriven) this.emitOpenChange(false);
  },

  teardown() {
    document.removeEventListener("keydown", this.boundKeydown, true);
    document.removeEventListener("pointerdown", this.boundOutside, true);
    window.removeEventListener("scroll", this.boundReposition, true);
    window.removeEventListener("resize", this.boundReposition);
    if (this._locked) {
      unlockScrollGlobal();
      this._locked = false;
    }
  },

  reposition() {
    if (this.active) this.positionPopup();
  },

  emitOpenChange(open) {
    if (!this.onOpenChange) return;
    if (this.onOpenChangeTarget) this.pushEventTo(this.onOpenChangeTarget, this.onOpenChange, { open });
    else this.pushEventTo(this.el, this.onOpenChange, { open });
  },

  // ---- anchored positioning (fixed; flip on the main axis + clamp) --------
  positionPopup() {
    const popup = this.popup;
    popup.style.position = "fixed";
    popup.style.left = "0px";
    popup.style.top = "0px";
    popup.style.visibility = "hidden";
    popup.hidden = false;
    popup.removeAttribute("data-closed");
    const a = this.trigger.getBoundingClientRect();
    const p = popup.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const off = this.sideOffset;
    let side = this.side;

    if (side === "bottom" && a.bottom + off + p.height > vh - PAD && a.top - off - p.height > PAD) side = "top";
    else if (side === "top" && a.top - off - p.height < PAD && a.bottom + off + p.height < vh - PAD) side = "bottom";
    else if (side === "right" && a.right + off + p.width > vw - PAD && a.left - off - p.width > PAD) side = "left";
    else if (side === "left" && a.left - off - p.width < PAD && a.right + off + p.width < vw - PAD) side = "right";

    let left;
    let top;
    if (side === "bottom" || side === "top") {
      top = side === "bottom" ? a.bottom + off : a.top - p.height - off;
      if (this.align === "start") left = a.left + this.alignOffset;
      else if (this.align === "end") left = a.right - p.width - this.alignOffset;
      else left = a.left + (a.width - p.width) / 2 + this.alignOffset;
    } else {
      left = side === "right" ? a.right + off : a.left - p.width - off;
      if (this.align === "start") top = a.top + this.alignOffset;
      else if (this.align === "end") top = a.bottom - p.height - this.alignOffset;
      else top = a.top + (a.height - p.height) / 2 + this.alignOffset;
    }

    left = Math.min(Math.max(left, PAD), Math.max(PAD, vw - p.width - PAD));
    top = Math.min(Math.max(top, PAD), Math.max(PAD, vh - p.height - PAD));
    popup.style.left = `${left}px`;
    popup.style.top = `${top}px`;
    popup.setAttribute("data-side", side);
    popup.setAttribute("data-align", this.align);
    // Pin the arrow to the popup edge, centered on the trigger (Base UI's Arrow does this inside the
    // component, so the demo's arrow class stays verbatim — no stylesheet needed).
    const arrow = popup.querySelector('[data-part="arrow"]');
    if (arrow) {
      const center = `${-arrow.offsetWidth / 2}px`;
      const vertical = side === "left" || side === "right";
      arrow.setAttribute("data-side", side);
      arrow.style.position = "absolute";
      arrow.style.left = vertical ? "" : "50%";
      arrow.style.marginLeft = vertical ? "" : center;
      arrow.style.top = vertical ? "50%" : "";
      arrow.style.marginTop = vertical ? center : "";
    }
    popup.style.visibility = "";
  },

  // ---- hover open/close ---------------------------------------------------
  scheduleHoverOpen() {
    this.cancelHoverClose();
    if (this.active) return;
    this.hoverTimer = setTimeout(() => this.open(), this.delay);
  },
  scheduleHoverClose() {
    if (this.hoverTimer) clearTimeout(this.hoverTimer);
    this.hoverTimer = setTimeout(() => this.close(), this.closeDelay);
  },
  cancelHoverClose() {
    if (this.hoverTimer) clearTimeout(this.hoverTimer);
    this.hoverTimer = null;
  },

  // ---- focus + dismiss ---------------------------------------------------
  focusables() {
    if (!this.popup) return [];
    return Array.from(this.popup.querySelectorAll(FOCUSABLE)).filter((el) => el.offsetParent !== null);
  },
  initialFocusEl() {
    if (!this.initialFocusSel || this.initialFocusSel === "false") {
      return this.initialFocusSel === "false" ? this.popup : null;
    }
    try {
      return this.popup.querySelector(this.initialFocusSel) || document.querySelector(this.initialFocusSel);
    } catch (_) {
      return null;
    }
  },
  finalFocusEl() {
    if (!this.finalFocusSel) return null;
    try {
      return document.querySelector(this.finalFocusSel);
    } catch (_) {
      return null;
    }
  },

  handleOutside(e) {
    if (!this.allowOutside || !this.closeOnOutside) return;
    if (this.popup.contains(e.target)) return;
    if (this.trigger && this.trigger.contains(e.target)) return;
    this.close();
  },

  handleKeydown(e) {
    if (!this.active) return;
    if (e.key === "Escape" && this.closeOnEscape) {
      e.preventDefault();
      this.close();
      return;
    }
    if (e.key !== "Tab" || !this.trapFocus) return;
    const items = this.focusables();
    if (items.length === 0) {
      e.preventDefault();
      return;
    }
    const first = items[0];
    const last = items[items.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus({ preventScroll: true });
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus({ preventScroll: true });
    }
  },
};

export default Popover;

// Tabs — a value-driven tablist with an animated indicator (Base UI parity) + LiveView push.
//
// One hook on the root owns: roving tabindex over `[data-part="tab"]` (arrow keys along
// `data-orientation` + Home/End), activating a tab (by its `data-value`) on click — and on focus when
// `data-activate-on-focus`. Activating shows the matching `[data-part="panel"]` (others get `hidden` +
// `data-hidden`), sets `aria-selected`/`data-active`, computes `data-activation-direction`
// (left/right/up/down vs the previous tab), and measures the active tab to publish the indicator CSS
// vars `--active-tab-left/right/top/bottom/width/height` (on the indicator + list) so a
// `[data-part="indicator"]` can slide/resize under it.
//
// Server push: when `data-on-change` is set, the resolved value is pushed to LiveView (`{value}`) on a
// user change. The root's `data-value` is the controlled value — on a server re-render `updated()`
// re-syncs the active tab + indicator WITHOUT pushing (no loop).

const Tabs = {
  mounted() {
    const el = this.el;
    this.tablist = el.querySelector('[data-part="tablist"]');
    this.indicator = el.querySelector('[data-part="indicator"]');
    this.orientation = el.getAttribute("data-orientation") || "horizontal";
    this.vertical = this.orientation === "vertical";
    this.activateOnFocus = el.hasAttribute("data-activate-on-focus");
    this.onChange = el.getAttribute("data-on-change");
    this.onChangeTarget = el.getAttribute("data-on-change-target"); // optional: target a LiveComponent

    this.tabs = Array.from(el.querySelectorAll('[data-part="tab"]'));
    this.panels = Array.from(el.querySelectorAll('[data-part="panel"]'));

    this.tabs.forEach((tab) => {
      if (tab._tabsBound) return;
      tab._tabsBound = true;
      tab.addEventListener("click", () => this.select(tab.getAttribute("data-value"), { user: true }));
      tab.addEventListener("keydown", (e) => this.onKey(e, tab));
      tab.addEventListener("focus", () => {
        if (this.activateOnFocus && !tab.hasAttribute("data-disabled")) {
          this.select(tab.getAttribute("data-value"), { user: true });
        }
      });
    });

    // resync the indicator when the list resizes (font load, wrap, etc.)
    this.ro = new ResizeObserver(() => this.moveIndicator());
    if (this.tablist) this.ro.observe(this.tablist);
    this.boundResize = () => this.moveIndicator();
    window.addEventListener("resize", this.boundResize);

    this.value = el.getAttribute("data-value") || this.firstEnabledValue();
    this.select(this.value, { user: false, instant: true });
  },

  updated() {
    // controlled: the server may have changed data-value — re-sync without pushing
    const v = this.el.getAttribute("data-value");
    if (v != null && v !== this.value) this.select(v, { user: false });
    else this.moveIndicator();
  },

  destroyed() {
    this.ro?.disconnect();
    window.removeEventListener("resize", this.boundResize);
  },

  enabledTabs() {
    return this.tabs.filter((t) => !t.hasAttribute("data-disabled"));
  },

  firstEnabledValue() {
    const t = this.enabledTabs()[0] || this.tabs[0];
    return t && t.getAttribute("data-value");
  },

  panelFor(value) {
    return this.panels.find((p) => p.getAttribute("data-value") === value);
  },

  // ---- selection ------------------------------------------------------------

  select(value, { user = false, instant = false } = {}) {
    const tab = this.tabs.find((t) => t.getAttribute("data-value") === value);
    if (!tab || tab.hasAttribute("data-disabled")) return;

    // activation direction vs the previous active tab
    let dir = null;
    if (this.value != null && this.value !== value) {
      const prev = this.tabs.find((t) => t.getAttribute("data-value") === this.value);
      if (prev) {
        const p = prev.getBoundingClientRect();
        const n = tab.getBoundingClientRect();
        if (this.vertical) dir = n.top === p.top ? null : n.top > p.top ? "down" : "up";
        else dir = n.left === p.left ? null : n.left > p.left ? "right" : "left";
      }
    }

    this.value = value;

    this.tabs.forEach((t) => {
      const on = t === tab;
      t.setAttribute("aria-selected", String(on));
      t.toggleAttribute("data-active", on);
      t.setAttribute("tabindex", on ? "0" : "-1");
    });
    this.panels.forEach((p) => {
      const on = p.getAttribute("data-value") === value;
      p.toggleAttribute("hidden", !on);
      p.toggleAttribute("data-hidden", !on);
    });

    // activation direction on root/list/tabs/panels/indicator (for slide animations)
    [this.el, this.tablist, this.indicator, tab, this.panelFor(value)].forEach((n) => {
      if (!n) return;
      if (dir) n.setAttribute("data-activation-direction", dir);
      else n.removeAttribute("data-activation-direction");
    });

    this.moveIndicator(instant);

    if (user && this.onChange) {
      if (this.onChangeTarget) this.pushEventTo(this.onChangeTarget, this.onChange, { value });
      else this.pushEventTo(this.el, this.onChange, { value });
    }
  },

  // measure the active tab and publish the indicator CSS vars on the indicator + list
  moveIndicator(instant) {
    if (!this.tablist) return;
    const tab = this.tabs.find((t) => t.getAttribute("data-value") === this.value);
    if (!tab) return;
    const lr = this.tablist.getBoundingClientRect();
    const tr = tab.getBoundingClientRect();
    const vars = {
      "--active-tab-left": `${tr.left - lr.left}px`,
      "--active-tab-right": `${lr.right - tr.right}px`,
      "--active-tab-top": `${tr.top - lr.top}px`,
      "--active-tab-bottom": `${lr.bottom - tr.bottom}px`,
      "--active-tab-width": `${tr.width}px`,
      "--active-tab-height": `${tr.height}px`,
    };
    [this.tablist, this.indicator].forEach((n) => {
      if (!n) return;
      for (const k in vars) n.style.setProperty(k, vars[k]);
    });
    if (instant && this.indicator) {
      // suppress the slide on the very first placement
      const t = this.indicator.style.transition;
      this.indicator.style.transition = "none";
      void this.indicator.offsetWidth;
      requestAnimationFrame(() => (this.indicator.style.transition = t));
    }
  },

  // ---- keyboard (roving) ----------------------------------------------------

  onKey(e, tab) {
    const next = this.vertical ? "ArrowDown" : "ArrowRight";
    const prev = this.vertical ? "ArrowUp" : "ArrowLeft";
    const tabs = this.enabledTabs();
    const idx = tabs.indexOf(tab);
    let target = null;
    if (e.key === next) target = tabs[(idx + 1) % tabs.length];
    else if (e.key === prev) target = tabs[(idx - 1 + tabs.length) % tabs.length];
    else if (e.key === "Home") target = tabs[0];
    else if (e.key === "End") target = tabs[tabs.length - 1];
    else if ((e.key === "Enter" || e.key === " ") && !this.activateOnFocus) {
      e.preventDefault();
      this.select(tab.getAttribute("data-value"), { user: true });
      return;
    } else return;
    e.preventDefault();
    if (target) {
      target.focus(); // focus → activates when activate_on_focus
      if (!this.activateOnFocus) this.roll(target);
    }
  },

  roll(tab) {
    this.tabs.forEach((t) => t.setAttribute("tabindex", t === tab ? "0" : "-1"));
  },
};

export default Tabs;

// Radio — headless single radio (Base UI parity).
//
// Wraps a native `<input type="radio">` and exposes Base UI's styling surface as live data-attributes
// on the root (the `<label>`) and the `[data-part="indicator"]`: `data-checked` / `data-unchecked`
// (mutually exclusive), kept in sync with the input's `checked` state — including when a SIBLING radio
// in the same `name` group steals the selection (the browser unchecks siblings without firing their
// `change`, so each radio also watches the document for same-name changes). `data-disabled` /
// `data-readonly` / `data-required` are rendered server-side. `readonly` is emulated by cancelling the
// click (native radios ignore the `readonly` attribute).
//
// No-JS fallback: the server already renders the correct initial `data-checked`/`data-unchecked`, so
// SSR and controlled (`<.form>`-driven) usage look right before/without the hook.

const Radio = {
  mounted() {
    this.input = this.el.querySelector('[data-part="input"]');
    this.indicator = this.el.querySelector('[data-part="indicator"]');
    if (!this.input) return;

    this.sync();

    this.onClick = (e) => {
      if (this.el.hasAttribute("data-readonly") || this.el.hasAttribute("data-disabled")) e.preventDefault();
    };
    this.onChange = () => this.sync();
    // A sibling becoming checked unchecks this one WITHOUT firing its `change`, so re-sync on any
    // same-name radio change anywhere in the document.
    this.onDocChange = (e) => {
      const t = e.target;
      if (t && t !== this.input && t.type === "radio" && this.input.name && t.name === this.input.name) {
        this.sync();
      }
    };

    this.input.addEventListener("click", this.onClick);
    this.input.addEventListener("change", this.onChange);
    this.input.ownerDocument.addEventListener("change", this.onDocChange, true);
  },

  destroyed() {
    if (this.onDocChange) this.input.ownerDocument.removeEventListener("change", this.onDocChange, true);
  },

  sync() {
    const on = this.input.checked;
    this.el.toggleAttribute("data-checked", on);
    this.el.toggleAttribute("data-unchecked", !on);
    if (this.indicator) {
      this.indicator.toggleAttribute("data-checked", on);
      this.indicator.toggleAttribute("data-unchecked", !on);
    }
  },
};

export default Radio;

// Splitter — two-panel resizable layout (Mantine Splitter parity).
//
// Drag the `[data-part="resizer"]` (or use the keyboard) to change the split. The position is written
// to the `--chelekom-splitter-pos` CSS variable on the root (a percentage), which your CSS uses to
// size the first panel. The resizer is a `role="separator"` with `aria-valuenow`; Arrow keys move it
// (Shift = ×10), Home/End jump to min/max. `data-dragging` is set on the root while dragging.

const Splitter = {
  mounted() {
    const root = this.el;
    const resizer = root.querySelector('[data-part="resizer"]');
    if (!resizer) return;

    resizer.style.touchAction = "none";
    const horizontal = root.getAttribute("data-orientation") !== "vertical";
    const min = Number(root.getAttribute("data-min")) || 0;
    const max = Number(root.getAttribute("data-max") || 100);
    const disabled = () => root.hasAttribute("data-disabled");

    const clamp = (n) => Math.min(max, Math.max(min, n));

    const setPos = (pct) => {
      pct = clamp(pct);
      this._pos = pct;
      root.style.setProperty("--chelekom-splitter-pos", pct + "%");
      resizer.setAttribute("aria-valuenow", String(Math.round(pct)));
      const on = root.getAttribute("data-on-change");
      if (on) this.pushEventTo(root, on, { value: Math.round(pct) });
    };

    const fromPointer = (e) => {
      const r = root.getBoundingClientRect();
      const pct = horizontal
        ? ((e.clientX - r.left) / r.width) * 100
        : ((e.clientY - r.top) / r.height) * 100;
      setPos(pct);
    };

    const onMove = (e) => {
      fromPointer(e);
      e.preventDefault();
    };
    const onUp = () => {
      root.removeAttribute("data-dragging");
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    };

    this._down = (e) => {
      if (disabled()) return;
      root.setAttribute("data-dragging", "");
      try {
        resizer.setPointerCapture(e.pointerId);
      } catch (_e) {}
      window.addEventListener("pointermove", onMove);
      window.addEventListener("pointerup", onUp);
      e.preventDefault();
    };

    this._key = (e) => {
      if (disabled()) return;
      const now = Number(resizer.getAttribute("aria-valuenow")) || 50;
      const step = e.shiftKey ? 10 : 1;
      const dec = horizontal ? ["ArrowLeft", "ArrowUp"] : ["ArrowUp", "ArrowLeft"];
      const inc = horizontal ? ["ArrowRight", "ArrowDown"] : ["ArrowDown", "ArrowRight"];
      if (dec.includes(e.key)) {
        setPos(now - step);
        e.preventDefault();
      } else if (inc.includes(e.key)) {
        setPos(now + step);
        e.preventDefault();
      } else if (e.key === "Home") {
        setPos(min);
        e.preventDefault();
      } else if (e.key === "End") {
        setPos(max);
        e.preventDefault();
      }
    };

    resizer.addEventListener("pointerdown", this._down);
    resizer.addEventListener("keydown", this._key);
    this._resizer = resizer;
  },

  // A server patch (e.g. the on_change echo re-rendering the component) resets the root's
  // inline style to the server-rendered default — re-apply the client's position.
  updated() {
    if (this._pos == null) return;
    this.el.style.setProperty("--chelekom-splitter-pos", this._pos + "%");
    if (this._resizer) this._resizer.setAttribute("aria-valuenow", String(Math.round(this._pos)));
  },

  destroyed() {
    if (this._resizer) {
      this._resizer.removeEventListener("pointerdown", this._down);
      this._resizer.removeEventListener("keydown", this._key);
    }
  },
};

export default Splitter;

// FocusTrap — headless dialog / alert-dialog behavior engine (Base UI parity).
//
// Client-driven by default: a `[data-part="trigger"]` opens the dialog, focus is trapped
// inside `[data-part="popup"]`, and Escape / backdrop / `[data-close]` close it, restoring
// focus to the opener. The server can also drive open/close by toggling `data-open` — see
// updated(). Supports Base UI's `modal` modes, scroll-lock, initial/final focus, nested
// dialogs, and an enter animation hook.
//
// Options (read from data-* on the root):
//   data-modal               "true" (default) | "false" | "trap-focus"
//   data-close-on-escape     "false" disables Escape
//   data-close-on-outside    "false" disables outside-press dismissal
//   data-on-open-change[-target]   LiveView event ({open}) + optional pushEventTo target
