      const off = intended === "right" ? Math.min(0, dx) : Math.max(0, dx);
      mx = along + damp(off);
      this.popup.style.setProperty("--drawer-swipe-movement-x", `${mx}px`);
    } else if (this.hasSnap) {
      // snap drawers: drag adjusts the offset (rubber-band past full-open)
      const next = this.activeOffset + dy;
      my = next >= 0 ? dy : -Math.sqrt(-next) - this.activeOffset;
      this.popup.style.setProperty("--drawer-swipe-movement-y", `${my}px`);
    } else {
      const along = intended === "down" ? Math.max(0, dy) : Math.min(0, dy);
      const off = intended === "down" ? Math.min(0, dy) : Math.max(0, dy);
      my = along + damp(off);
      this.popup.style.setProperty("--drawer-swipe-movement-y", `${my}px`);
    }
    if (!this.dirSet && (Math.abs(dx) > 2 || Math.abs(dy) > 2)) {
      this.popup.setAttribute("data-swipe-direction", intended);
      this.dirSet = true;
    }
    const size = this.horizontal ? this.sizeW : this.sizeH;
    const disp = this.projection(mx, my, intended);
    const progress = Math.max(0, Math.min(disp / (size || 1), 1));
    if (this.backdrop) this.backdrop.style.setProperty("--drawer-swipe-progress", String(progress));
    indent.progress(this.provider, progress);
    this.lastSample = { x: e.clientX, y: e.clientY, t: performance.now() };
  },

  projection(mx, my, dir) {
    if (dir === "right") return mx;
    if (dir === "left") return -mx;
    if (dir === "down") return my;
    return -my; // up
  },

  endSwipe(e) {
    if (!this.swiping) return;
    this.swiping = false;
    try {
      this.popup.releasePointerCapture(e.pointerId);
    } catch (_) {}
    this._captured = null;
    const now = performance.now();
    const dx = e.clientX - this.startX;
    const dy = e.clientY - this.startY;
    const dt = Math.max(now - this.startTime, 50);
    const intended = this.dismissDir;
    const size = this.horizontal ? this.sizeW : this.sizeH;

    this.popup.removeAttribute("data-swiping");
    this.popup.removeAttribute("data-swipe-direction");
    this.dirSet = false;
    if (this.backdrop) this.backdrop.removeAttribute("data-swiping");

    if (this.hasSnap) return this.endSnapDrag(dy, dt);

    const along = this.projection(this.horizontal ? dx : 0, this.horizontal ? 0 : dy, intended);
    const velocity = along / dt; // px per ms in the dismiss direction
    const dismiss = velocity >= 0.5 || along > size * 0.5;

    if (dismiss) {
      const strength = this.releaseStrength(size, along, velocity);
      this.popup.style.setProperty("--drawer-swipe-strength", String(strength));
      this.popup.setAttribute("data-swipe-dismiss", "");
      this.popup.setAttribute("data-ending-style", "");
      this.popup.style.transition = "";
      this.popup.style.removeProperty("--drawer-swipe-movement-x");
      this.popup.style.removeProperty("--drawer-swipe-movement-y");
      this.close();
      setTimeout(() => {
        if (this.popup) {
          this.popup.removeAttribute("data-swipe-dismiss");
          this.popup.removeAttribute("data-ending-style");
          this.popup.style.removeProperty("--drawer-swipe-strength");
        }
      }, 450);
    } else {
      this.snapBack();
    }
  },

  releaseStrength(size, along, velocity) {
    if (velocity <= 0.2) return 1;
    const remaining = Math.max(0, size - along);
    const t = Math.max(80, Math.min(remaining / Math.max(velocity, 0.2), 360));
    return Math.max(0.1, Math.min(0.1 + ((t - 80) / 280) * 0.9, 1));
  },

  snapBack() {
    this.popup.style.transition = "";
    this.popup.style.setProperty("--drawer-swipe-movement-x", "0px");
    this.popup.style.setProperty("--drawer-swipe-movement-y", "0px");
    if (this.backdrop) this.backdrop.style.setProperty("--drawer-swipe-progress", "1");
    indent.progress(this.provider, 1);
    requestAnimationFrame(() => {
      this.popup.style.removeProperty("--drawer-swipe-movement-x");
      this.popup.style.removeProperty("--drawer-swipe-movement-y");
    });
  },

  endSnapDrag(dy, dt) {
    this.popup.style.transition = "";
    this.popup.style.removeProperty("--drawer-swipe-movement-y");
    const popupH = this.popup.offsetHeight;
    const velocity = dy / dt; // +down
    const dragTarget = Math.max(0, Math.min(this.activeOffset + dy, popupH));
    let target = dragTarget;
    if (!this.sequential && Math.abs(velocity) >= 0.5) {
      target = Math.max(0, Math.min(dragTarget + Math.max(-4, Math.min(velocity, 4)) * 300, popupH));
    }
    // close if dragged/flicked down past the deepest snap
    const deepest = this.snaps[this.snaps.length - 1];
    if (velocity >= 0.5 && dy > 0 && Math.abs(target - popupH) < Math.abs(target - deepest.offset)) {
      return this.close();
    }
    let nearest = this.snaps[0];
    let best = Infinity;
    for (const s of this.snaps) {
      const d = Math.abs(s.offset - target);
      if (d < best) {
        best = d;
        nearest = s;
      }
    }
    if (Math.abs(target - popupH) < best) return this.close();
    this.applySnap(nearest, true);
  },

  // ---- swipe-area (open from edge) ----------------------------------------
  bindSwipeArea() {
    if (this.swipeArea.getAttribute("data-disabled") === "true") return;
    const openDir = this.swipeArea.getAttribute("data-swipe-direction") || OPP[this.dismissDir];
    this.swipeArea.style.touchAction = this.horizontal ? "pan-y" : "pan-x";
    this.swipeArea.addEventListener("pointerdown", (e) => {
      if (e.button !== 0 || this.el.hasAttribute("data-open")) return;
      this.areaSwiping = true;
      this.areaStartX = e.clientX;
      this.areaStartY = e.clientY;
      this.areaOpened = false;
      this.suppressOutside = true;
      try {
        this.swipeArea.setPointerCapture(e.pointerId);
      } catch (_) {}
      this.swipeArea.setAttribute("data-swiping", "");
      this.swipeArea.setAttribute("data-swipe-direction", openDir);
    });
    this.swipeArea.addEventListener("pointermove", (e) => {
      if (!this.areaSwiping) return;
      const dx = e.clientX - this.areaStartX;
      const dy = e.clientY - this.areaStartY;
      const disp = this.projection(dx, dy, openDir);
      if (disp < 1) return;
      if (!this.areaOpened) {
        this.open();
        this.areaOpened = true;
        this.popup.style.transition = "none";
        this.popup.setAttribute("data-swiping", "");
        if (this.backdrop) this.backdrop.setAttribute("data-swiping", "");
      }
      const closedOffset = this.horizontal ? this.popup.offsetWidth : this.popup.offsetHeight;
      const damped = disp <= closedOffset ? disp : closedOffset + Math.sqrt(disp - closedOffset);
      const sign = openDir === "left" || openDir === "up" ? -1 : 1;
      const movement = (closedOffset - damped) * sign;
      const prop = this.horizontal ? "--drawer-swipe-movement-x" : "--drawer-swipe-movement-y";
      this.popup.style.setProperty(prop, `${movement}px`);
      const openProgress = Math.max(0, Math.min(disp / (closedOffset || 1), 1));
      if (this.backdrop) this.backdrop.style.setProperty("--drawer-swipe-progress", String(openProgress));
    });
    const release = (e) => {
      if (!this.areaSwiping) return;
      this.areaSwiping = false;
      try {
        this.swipeArea.releasePointerCapture(e.pointerId);
      } catch (_) {}
      this.swipeArea.removeAttribute("data-swiping");
      this.popup.style.transition = "";
      this.popup.removeAttribute("data-swiping");
      if (this.backdrop) this.backdrop.removeAttribute("data-swiping");
      const dx = e.clientX - this.areaStartX;
      const dy = e.clientY - this.areaStartY;
      const disp = this.projection(dx, dy, openDir);
      const closedOffset = this.horizontal ? this.popup.offsetWidth : this.popup.offsetHeight;
      const prop = this.horizontal ? "--drawer-swipe-movement-x" : "--drawer-swipe-movement-y";
      this.popup.style.removeProperty(prop);
      if (this.areaOpened && disp < closedOffset * 0.5) this.close();
      setTimeout(() => (this.suppressOutside = false), 0);
    };
    this.swipeArea.addEventListener("pointerup", release);
    this.swipeArea.addEventListener("pointercancel", release);
  },
};

export default Drawer;

// ContextMenu — headless context-menu engine (Base UI parity).
//
// Opens a `[data-part="popup"]` menu at the cursor on right-click (contextmenu) or touch
// long-press, positioned `fixed` and clamped to the viewport. Full menu semantics: roving
// highlight + typeahead, Enter/Space activation, checkbox/radio item state, nested submenus
// (hover + ArrowRight / ArrowLeft), Escape + outside-press dismissal, focus restore. Motion
// and color are 100% CSS — the hook only toggles data-* state and positions popups.
//
// Parts (data-part): trigger, popup, submenu, submenu-trigger, submenu-popup, item,
// checkbox-item, radio-group, radio-item, link-item, separator. Highlightable rows:
// item | checkbox-item | radio-item | link-item | submenu-trigger.

const HIGHLIGHTABLE =
  '[data-part="item"],[data-part="checkbox-item"],[data-part="radio-item"],[data-part="link-item"],[data-part="submenu-trigger"]';
const LONG_PRESS = 500;
const MENU = '[data-part="popup"],[data-part="submenu-popup"]';

const ContextMenu = {
  mounted() {
    this.trigger = this.el.querySelector('[data-part="trigger"]');
    this.popup = this.el.querySelector('[data-part="popup"]');
    this.disabled = this.el.getAttribute("data-disabled") === "true";
    this.onOpenChange = this.el.getAttribute("data-on-open-change");
    this.onOpenChangeTarget = this.el.getAttribute("data-on-open-change-target");

    this.stack = []; // open menu elements, root popup first
    this.typeahead = "";
    this.typeaheadAt = 0;
    this.submenuTimers = new Map();

    this.boundKeydown = (e) => this.handleKeydown(e);
    this.boundOutside = (e) => this.handleOutside(e);
    this.boundDocCtx = (e) => this.suppressNativeMenu(e);

    if (this.popup && this.popup.id && this.trigger) {
      this.trigger.setAttribute("aria-haspopup", "menu");
      this.trigger.setAttribute("aria-controls", this.popup.id);
      this.trigger.setAttribute("aria-expanded", "false");
    }
    if (this.trigger) {
      this.trigger.style.webkitTouchCallout = "none";
      this.trigger.addEventListener("contextmenu", (e) => this.onContextMenu(e));
      this.trigger.addEventListener("touchstart", (e) => this.onTouchStart(e), { passive: true });
      this.trigger.addEventListener("touchmove", (e) => this.onTouchMove(e), { passive: true });
      this.trigger.addEventListener("touchend", () => this.cancelLongPress());
      this.trigger.addEventListener("touchcancel", () => this.cancelLongPress());
    }

    // Wire interactive rows (event delegation on the whole root covers nested popups too).
    this.el.addEventListener("click", (e) => this.onRowClick(e));
    this.el.addEventListener("pointermove", (e) => this.onRowHover(e));

    document.addEventListener("contextmenu", this.boundDocCtx, true);
  },

  destroyed() {
    document.removeEventListener("contextmenu", this.boundDocCtx, true);
    this.teardownOpenListeners();
    this.cancelLongPress();
  },

  // ---- opening -----------------------------------------------------------
  onContextMenu(e) {
    if (this.disabled) return;
    e.preventDefault();
    e.stopPropagation();
    this.openAt(e.clientX, e.clientY);
  },

  suppressNativeMenu(e) {
    // Kill the browser's native menu on a second right-click over our trigger/menu.
    if (this.disabled) return;
    if (
      (this.trigger && this.trigger.contains(e.target)) ||
      this.stack.some((m) => m.contains(e.target))
    ) {
      e.preventDefault();
    }
  },

  onTouchStart(e) {
    if (this.disabled || e.touches.length !== 1) return;
    const t = e.touches[0];
    this.touchPoint = { x: t.clientX, y: t.clientY };
    this.longPressTimer = setTimeout(() => {
      this.openAt(this.touchPoint.x, this.touchPoint.y);
    }, LONG_PRESS);
  },

  onTouchMove(e) {
    if (!this.longPressTimer || !this.touchPoint) return;
    const t = e.touches[0];
    if (Math.abs(t.clientX - this.touchPoint.x) > 10 || Math.abs(t.clientY - this.touchPoint.y) > 10) {
      this.cancelLongPress();
    }
  },

  cancelLongPress() {
    if (this.longPressTimer) clearTimeout(this.longPressTimer);
    this.longPressTimer = null;
    this.touchPoint = null;
  },

  openAt(x, y) {
    const wasOpen = this.stack.length > 0;
    if (wasOpen) this.closeAll(false);
    this.opener = document.activeElement;
    this.placeMenu(this.popup, x, y, null);
    this.openMenu(this.popup);
    if (this.trigger) {
      this.trigger.setAttribute("aria-expanded", "true");
      this.trigger.toggleAttribute("data-popup-open", true);
    }
    if (!wasOpen) {
      document.addEventListener("keydown", this.boundKeydown, true);
      // Grace period: ignore the opening gesture's trailing pointer events.
      this.allowOutside = false;
      setTimeout(() => {
        this.allowOutside = true;
        document.addEventListener("pointerdown", this.boundOutside, true);
      }, 60);
      this.emitOpenChange(true);
    }
    requestAnimationFrame(() => this.popup.focus({ preventScroll: true }));
  },

  // Position a fixed menu at (x,y), clamped to the viewport (flip near edges).
  placeMenu(menu, x, y, anchorRect) {
    menu.style.position = "fixed";
    menu.style.left = "0px";
    menu.style.top = "0px";
    menu.style.visibility = "hidden";
    menu.hidden = false;
    menu.removeAttribute("data-closed");
    const r = menu.getBoundingClientRect();
    const pad = 8;
    let left = x;
    let top = y;
    if (anchorRect) {
      left = anchorRect.right; // submenu opens to the right of its trigger
      top = anchorRect.top;
      if (left + r.width > window.innerWidth - pad) left = anchorRect.left - r.width;
    } else {
      if (left + r.width > window.innerWidth - pad) left = Math.max(pad, x - r.width);
      if (top + r.height > window.innerHeight - pad) top = Math.max(pad, y - r.height);
    }
    left = Math.min(Math.max(left, pad), window.innerWidth - r.width - pad);
    top = Math.min(Math.max(top, pad), window.innerHeight - r.height - pad);
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
    menu.style.visibility = "";
  },

  openMenu(menu) {
    menu.hidden = false;
    menu.toggleAttribute("data-open", true);
    menu.removeAttribute("data-closed");
    menu.setAttribute("data-starting-style", "");
    requestAnimationFrame(() =>
      requestAnimationFrame(() => menu && menu.removeAttribute("data-starting-style")),
    );
    if (this.stack.indexOf(menu) === -1) this.stack.push(menu);
    this.setHighlight(menu, null);
  },

  closeMenu(menu) {
    menu.toggleAttribute("data-open", false);
    menu.setAttribute("data-closed", "");
    menu.hidden = true;
    const i = this.stack.indexOf(menu);
    if (i >= 0) this.stack.splice(i, 1);
    // collapse the submenu-trigger that owns this submenu
    const sub = menu.closest('[data-part="submenu"]');
    if (sub) {
      const t = sub.querySelector('[data-part="submenu-trigger"]');
      if (t) {
        t.setAttribute("aria-expanded", "false");
        t.toggleAttribute("data-popup-open", false);
      }
    }
  },

  closeAll(restoreFocus = true) {
    [...this.stack].reverse().forEach((m) => this.closeMenu(m));
    this.stack = [];
    if (this.trigger) {
      this.trigger.setAttribute("aria-expanded", "false");
      this.trigger.toggleAttribute("data-popup-open", false);
    }
    this.teardownOpenListeners();
    this.emitOpenChange(false);
    if (restoreFocus && this.opener && this.opener.focus) this.opener.focus({ preventScroll: true });
  },

  teardownOpenListeners() {
    document.removeEventListener("keydown", this.boundKeydown, true);
    document.removeEventListener("pointerdown", this.boundOutside, true);
    this.submenuTimers.forEach((t) => clearTimeout(t));
    this.submenuTimers.clear();
  },

  emitOpenChange(open) {
    if (!this.onOpenChange) return;
    if (this.onOpenChangeTarget) this.pushEventTo(this.onOpenChangeTarget, this.onOpenChange, { open });
    else this.pushEventTo(this.el, this.onOpenChange, { open });
  },

  handleOutside(e) {
    if (!this.allowOutside) return;
    if (this.stack.some((m) => m.contains(e.target))) return;
    if (this.trigger && this.trigger.contains(e.target)) return;
    this.closeAll();
  },

  // ---- rows: hover / click -----------------------------------------------
  itemsOf(menu) {
    return Array.from(menu.querySelectorAll(HIGHLIGHTABLE)).filter(
      (el) => el.closest(MENU) === menu && !el.hasAttribute("data-disabled"),
    );
  },

  activeMenu() {
    return this.stack[this.stack.length - 1] || null;
  },

  setHighlight(menu, el) {
    this.itemsOf(menu).forEach((it) => {
      const on = it === el;
      it.toggleAttribute("data-highlighted", on);
      it.tabIndex = on ? 0 : -1;
    });
    if (el && el.focus) el.focus({ preventScroll: true });
  },

  onRowHover(e) {
    const row = e.target.closest(HIGHLIGHTABLE);
    if (!row) return;
    const menu = row.closest(MENU);
    if (!menu || this.stack.indexOf(menu) === -1) return;
    if (row.hasAttribute("data-disabled")) return;
    if (this.activeMenu() === menu) this.setHighlight(menu, row);
    // submenu open-on-hover (with a small delay); close sibling submenus
    if (row.getAttribute("data-part") === "submenu-trigger") {
      this.scheduleSubmenuOpen(row);
    } else {
      this.closeSiblingSubmenus(menu, null);
    }
  },

  scheduleSubmenuOpen(trigger) {
    const sub = trigger.closest('[data-part="submenu"]');
    const popup = sub && sub.querySelector('[data-part="submenu-popup"]');
    if (!popup || this.stack.indexOf(popup) !== -1) return;
    const parentMenu = trigger.closest(MENU);
    this.closeSiblingSubmenus(parentMenu, sub);
    const key = trigger;
    if (this.submenuTimers.has(key)) return;
    const t = setTimeout(() => {
      this.submenuTimers.delete(key);
      this.openSubmenu(trigger);
    }, 100);
    this.submenuTimers.set(key, t);
  },

  closeSiblingSubmenus(parentMenu, keepSub) {
    parentMenu.querySelectorAll('[data-part="submenu"]').forEach((s) => {
      if (s === keepSub) return;
      if (s.closest(MENU) !== parentMenu) return;
      const p = s.querySelector('[data-part="submenu-popup"]');
      if (p && this.stack.indexOf(p) !== -1) this.closeMenu(p);
    });
  },

  openSubmenu(trigger) {
    const sub = trigger.closest('[data-part="submenu"]');
    const popup = sub && sub.querySelector('[data-part="submenu-popup"]');
    if (!popup || this.stack.indexOf(popup) !== -1) return;
    this.placeMenu(popup, 0, 0, trigger.getBoundingClientRect());
    this.openMenu(popup);
    trigger.setAttribute("aria-expanded", "true");
    trigger.toggleAttribute("data-popup-open", true);
    return popup;
  },

  onRowClick(e) {
    const row = e.target.closest(HIGHLIGHTABLE);
    if (!row || row.hasAttribute("data-disabled")) return;
    const part = row.getAttribute("data-part");
    if (part === "submenu-trigger") {
      e.preventDefault();
      const sub = row.closest('[data-part="submenu"]');
      const p = sub && sub.querySelector('[data-part="submenu-popup"]');
      if (p && this.stack.indexOf(p) !== -1) this.closeMenu(p);
      else this.activateSubmenu(row, true);
      return;
    }
    if (part === "checkbox-item") {
      this.toggleCheckbox(row);
      return; // stays open
    }
    if (part === "radio-item") {
      this.selectRadio(row);
      return; // stays open
    }
    // item / link-item: let the consumer's phx-click / navigation run, then close.
    if (row.getAttribute("data-keep-open") !== "true") {
      setTimeout(() => this.closeAll(), 0);
    }
  },

  activateSubmenu(trigger, focusFirst) {
    const popup = this.openSubmenu(trigger);
    if (popup && focusFirst) {
      const first = this.itemsOf(popup)[0];
      if (first) this.setHighlight(popup, first);
      else popup.focus({ preventScroll: true });
    }
  },

  toggleCheckbox(item) {
    const checked = !item.hasAttribute("data-checked");
    item.toggleAttribute("data-checked", checked);
    item.toggleAttribute("data-unchecked", !checked);
    item.setAttribute("aria-checked", String(checked));
    const ind = item.querySelector('[data-part="checkbox-item-indicator"]');
    if (ind) {
      ind.toggleAttribute("data-checked", checked);
      ind.toggleAttribute("data-unchecked", !checked);
    }
    this.emitItemEvent(item, { checked });
  },

  selectRadio(item) {
    const name = item.getAttribute("data-radio-group");
    const menu = item.closest(MENU);
    let radios;
    if (name && menu) {
      radios = menu.querySelectorAll(
        `[data-part="radio-item"][data-radio-group="${name}"]`,
      );
    } else {
      const group = item.closest('[data-part="radio-group"]');
      if (!group) return;
      radios = group.querySelectorAll('[data-part="radio-item"]');
    }
    radios.forEach((r) => {
      const on = r === item;
      r.toggleAttribute("data-checked", on);
      r.toggleAttribute("data-unchecked", !on);
      r.setAttribute("aria-checked", String(on));
      const ind = r.querySelector('[data-part="radio-item-indicator"]');
      if (ind) {
        ind.toggleAttribute("data-checked", on);
        ind.toggleAttribute("data-unchecked", !on);
      }
    });
    this.emitItemEvent(item, { value: item.getAttribute("data-value") });
  },

  emitItemEvent(item, payload) {
    const ev = item.getAttribute("data-on-change");
    if (!ev) return;
    const target = item.getAttribute("data-on-change-target");
    if (target) this.pushEventTo(target, ev, payload);
    else this.pushEventTo(this.el, ev, payload);
  },

  // ---- keyboard ----------------------------------------------------------
  handleKeydown(e) {
    if (this.stack.length === 0) return;
    const menu = this.activeMenu();
    const items = this.itemsOf(menu);
    const current = items.find((it) => it.hasAttribute("data-highlighted"));
    const idx = current ? items.indexOf(current) : -1;

    switch (e.key) {
      case "Escape":
        e.preventDefault();
        if (this.stack.length > 1) {
          this.closeMenu(menu);
          const owner = menu.closest('[data-part="submenu"]')?.querySelector('[data-part="submenu-trigger"]');
          if (owner) this.setHighlight(this.activeMenu(), owner);
        } else {
          this.closeAll();
        }
        return;
      case "ArrowDown":
        e.preventDefault();
        this.setHighlight(menu, items[(idx + 1) % items.length] || items[0]);
        return;
      case "ArrowUp":
        e.preventDefault();
        this.setHighlight(menu, items[(idx - 1 + items.length) % items.length] || items[items.length - 1]);
        return;
      case "Home":
        e.preventDefault();
        this.setHighlight(menu, items[0]);
        return;
      case "End":
        e.preventDefault();
        this.setHighlight(menu, items[items.length - 1]);
        return;
      case "ArrowRight":
        if (current && current.getAttribute("data-part") === "submenu-trigger") {
          e.preventDefault();
          this.activateSubmenu(current, true);
        }
        return;
      case "ArrowLeft":
        if (this.stack.length > 1) {
          e.preventDefault();
          this.closeMenu(menu);
          const owner = menu.closest('[data-part="submenu"]')?.querySelector('[data-part="submenu-trigger"]');
          if (owner) this.setHighlight(this.activeMenu(), owner);
        }
        return;
      case "Enter":
      case " ":
        if (current) {
          e.preventDefault();
          current.click();
        }
        return;
      case "Tab":
        e.preventDefault();
        this.closeAll();
        return;
      default:
        if (e.key.length === 1 && !e.metaKey && !e.ctrlKey && !e.altKey) {
          this.onType(menu, items, e.key);
        }
    }
  },

  onType(menu, items, ch) {
    this.typeahead = (performance.now() - this.typeaheadAt > 700 ? "" : this.typeahead) + ch.toLowerCase();
    this.typeaheadAt = performance.now();
    const match = items.find((it) =>
      (it.getAttribute("data-label") || it.textContent || "").trim().toLowerCase().startsWith(this.typeahead),
    );
    if (match) this.setHighlight(menu, match);
  },
};

export default ContextMenu;

// Disclosure — headless accordion / disclosure engine (WAI-ARIA APG).
// Static ARIA/ids/tabindex are rendered by the component; this only drives the dynamic behavior.
// Root data-attrs: data-multiple, data-collapsible, data-orientation, data-disabled, data-loop,
// data-hidden-until-found, data-on-value-change. Per item: data-value, data-disabled, data-on-open-change.

const Disclosure = {
  mounted() {
    this.onClick = (e) => this.handleClick(e);
    this.onKeydown = (e) => this.handleKeydown(e);
    this.onBeforematch = (e) => this.handleBeforematch(e);
    this.el.addEventListener("click", this.onClick);
    this.el.addEventListener("keydown", this.onKeydown);
    this.el.addEventListener("beforematch", this.onBeforematch);
    this.setup();
  },

  updated() {
    this.setup();
  },

  destroyed() {
    this.el.removeEventListener("click", this.onClick);
    this.el.removeEventListener("keydown", this.onKeydown);
    this.el.removeEventListener("beforematch", this.onBeforematch);
  },

  setup() {
    this.multiple = this.el.getAttribute("data-multiple") === "true";
    this.collapsible = this.el.getAttribute("data-collapsible") !== "false";
    this.rootDisabled = this.el.hasAttribute("data-disabled");
    this.horizontal = this.el.getAttribute("data-orientation") === "horizontal";
    this.loop = this.el.getAttribute("data-loop") !== "false";
    this.untilFound = this.el.hasAttribute("data-hidden-until-found");
    this.onValueChange = this.el.getAttribute("data-on-value-change");
    this.rtl = getComputedStyle(this.el).direction === "rtl";
    this.reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    this.pairs = Array.from(this.el.querySelectorAll('[data-part="trigger"]')).map((trigger) => {
      const id = trigger.getAttribute("aria-controls");
      const panel = id ? this.el.querySelector(`#${CSS.escape(id)}`) : null;
      const item = trigger.closest('[data-part="item"]');
      if (panel) {
        const open = panel.hasAttribute("data-open");
        trigger.setAttribute("aria-expanded", String(open));
        trigger.toggleAttribute("data-panel-open", open);
        if (open) {
          panel.removeAttribute("hidden");
          this.measure(panel);
        }
      }
      return { trigger, panel, item, value: item && item.getAttribute("data-value") };
    });

    this.rove();
  },

  disabled(trigger) {
    return this.rootDisabled || trigger.hasAttribute("data-disabled");
  },

  triggers(enabledOnly) {
    const all = this.pairs.map((p) => p.trigger);
    return enabledOnly ? all.filter((t) => !this.disabled(t)) : all;
  },

  // Roving tabindex: the focused (or first enabled) trigger is the only tab stop.
  rove(focused) {
    const enabled = this.triggers(true);
    const stop =
      (focused && !this.disabled(focused) && focused) || enabled[0] || this.pairs[0]?.trigger;
    this.pairs.forEach(({ trigger }) => (trigger.tabIndex = trigger === stop ? 0 : -1));
  },

  handleClick(e) {
    const t = e.target.closest('[data-part="trigger"]');
    if (t && this.el.contains(t)) this.toggle(t);
  },

  handleBeforematch(e) {
    const panel = e.target.closest('[data-part="panel"]');
    const pair = panel && this.pairs.find((p) => p.panel === panel);
    if (pair) this.toggle(pair.trigger, true);
  },

  // Enter/Space stay on the native button; we own arrow + Home/End focus movement.
  handleKeydown(e) {
    const t = e.target.closest('[data-part="trigger"]');
    if (!t || !this.el.contains(t)) return;

    const nextKey = this.horizontal ? (this.rtl ? "ArrowLeft" : "ArrowRight") : "ArrowDown";
    const prevKey = this.horizontal ? (this.rtl ? "ArrowRight" : "ArrowLeft") : "ArrowUp";
    const all = this.triggers();
    const enabled = this.triggers(true);
    const pos = all.indexOf(t);
    if (pos < 0 || !enabled.length) return;

    let target;
    if (e.key === nextKey) target = this.step(all, pos, 1);
    else if (e.key === prevKey) target = this.step(all, pos, -1);
    else if (e.key === "Home") target = enabled[0];
    else if (e.key === "End") target = enabled[enabled.length - 1];
    else return;

    e.preventDefault();
    e.stopPropagation();
    if (target) {
      this.rove(target);
      target.focus();
    }
  },

  // Next/previous enabled trigger from pos (skips disabled, including a disabled focused one).
  step(all, pos, dir) {
    const n = all.length;
    for (let s = 1; s <= n; s++) {
      let i = pos + dir * s;
      if (this.loop) i = ((i % n) + n) % n;
      else if (i < 0 || i >= n) return null;
      if (!this.disabled(all[i])) return all[i];
    }
    return null;
  },

  toggle(trigger, force) {
    const pair = this.pairs.find((p) => p.trigger === trigger);
    if (!pair || !pair.panel || this.disabled(trigger)) return;

    const isOpen = pair.panel.hasAttribute("data-open");
    const open = force === true ? true : !isOpen;
    if (open === isOpen || (!open && !this.collapsible)) return;

    if (open && !this.multiple) {
      this.pairs.forEach((p) => {
        if (p.panel && p !== pair && p.panel.hasAttribute("data-open")) this.setOpen(p, false);
      });
    }
    this.setOpen(pair, open);
    this.emit(pair, open);
  },

  setOpen(pair, open) {
    const { trigger, panel, item } = pair;
    trigger.setAttribute("aria-expanded", String(open));
    trigger.toggleAttribute("data-panel-open", open);
    if (item) item.toggleAttribute("data-open", open);
    panel.toggleAttribute("data-open", open);
    panel.toggleAttribute("data-closed", !open);
    open ? this.expand(panel) : this.collapse(panel);
  },

  // Measured natural size, exposed for the consumer's height/width transition. Measure at
  // `auto` so a flex panel (whose content collapses to 0 while the box is pinned to height:0
  // during the enter transition) still reports its real content size.
  measure(panel) {
    const prevH = panel.style.height;
    const prevW = panel.style.width;
    panel.style.height = "auto";
    panel.style.width = "auto";
    panel.style.setProperty("--accordion-panel-height", `${panel.scrollHeight}px`);
    panel.style.setProperty("--accordion-panel-width", `${panel.scrollWidth}px`);
    panel.style.height = prevH;
    panel.style.width = prevW;
  },

  // Reveal, pin the collapsed starting style and commit it as the baseline (so the transition always
  // runs from 0 — scrollHeight still reports the content size while collapsed), then release it.
  expand(panel) {
    panel.removeAttribute("hidden");
    if (this.reducedMotion) return this.measure(panel);
    panel.setAttribute("data-starting-style", "");
    void panel.offsetHeight;
    this.measure(panel);
    requestAnimationFrame(() => panel.removeAttribute("data-starting-style"));
  },

  // Pin the open size as the transition's start, apply the closed style, then hide once the
  // animation finishes. Chrome registers the exit transition a frame late, so wait a frame
  // before watching it (https://github.com/mui/base-ui/issues/3099).
  collapse(panel) {
    const hide = () => {
      if (panel.hasAttribute("data-open")) return; // reopened mid-transition
      panel.removeAttribute("data-ending-style");
      panel.setAttribute("hidden", this.untilFound ? "until-found" : "");
    };
    if (this.reducedMotion || !panel.getAnimations) return hide();
    this.measure(panel); // pin the open size as the transition's "from"
    void panel.offsetHeight; // commit it
    requestAnimationFrame(() => {
      // apply the closing style in a FRESH frame so the height transitions from the committed size
      panel.setAttribute("data-ending-style", "");
      requestAnimationFrame(() =>
        Promise.allSettled(panel.getAnimations().map((a) => a.finished)).then(hide)
      );
    });
  },

  emit(pair, open) {
    const itemEvent = pair.item && pair.item.getAttribute("data-on-open-change");
    if (itemEvent) this.pushEventTo(this.el, itemEvent, { value: pair.value, open });
    if (this.onValueChange) {
      const value = this.pairs
        .filter((p) => p.panel && p.panel.hasAttribute("data-open"))
        .map((p) => p.value)
        .filter((v) => v != null);
      this.pushEventTo(this.el, this.onValueChange, { value });
    }
  },
};

export default Disclosure;

// ColorPicker — saturation/value area + hue slider (Mantine ColorPicker parity).
//
// Anatomy: a 2D `[data-part="area"]` (drag to set saturation on X and value/brightness on Y, the
// `[data-part="area-thumb"]` follows), a native range `[data-part="hue"]` (0–360), a
// `[data-part="preview"]` swatch and a hidden `[data-part="input"]` that carries the hex value for
// forms. Emits `data-on-change` with `{value: "#rrggbb"}` and mirrors the value into the input's
// `input` event so `<.form phx-change>` fires.

function hsvToRgb(h, s, v) {
  s /= 100;
  v /= 100;
  const c = v * s;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = v - c;
  let r = 0,
    g = 0,
    b = 0;
  if (h < 60) [r, g, b] = [c, x, 0];
  else if (h < 120) [r, g, b] = [x, c, 0];
  else if (h < 180) [r, g, b] = [0, c, x];
  else if (h < 240) [r, g, b] = [0, x, c];
  else if (h < 300) [r, g, b] = [x, 0, c];
  else [r, g, b] = [c, 0, x];
  return [Math.round((r + m) * 255), Math.round((g + m) * 255), Math.round((b + m) * 255)];
}

function toHex(r, g, b) {
  return "#" + [r, g, b].map((n) => n.toString(16).padStart(2, "0")).join("");
}

function hexToHsv(hex) {
  hex = (hex || "").replace("#", "");
  if (hex.length === 3)
    hex = hex
      .split("")
      .map((c) => c + c)
      .join("");
  if (hex.length !== 6) return { h: 217, s: 76, v: 96 };
  const r = parseInt(hex.slice(0, 2), 16) / 255;
  const g = parseInt(hex.slice(2, 4), 16) / 255;
  const b = parseInt(hex.slice(4, 6), 16) / 255;
  const max = Math.max(r, g, b),
    min = Math.min(r, g, b),
    d = max - min;
  let h = 0;
  if (d) {
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60;
    if (h < 0) h += 360;
  }
  return { h, s: max ? (d / max) * 100 : 0, v: max * 100 };
}

const ColorPicker = {
  mounted() {
    const root = this.el;
    this.area = root.querySelector('[data-part="area"]');
    this.areaThumb = root.querySelector('[data-part="area-thumb"]');
    this.hueInput = root.querySelector('[data-part="hue"]');
    this.preview = root.querySelector('[data-part="preview"]');
    this.input = root.querySelector('[data-part="input"]');
    this.text = root.querySelector('[data-part="text"]');
    if (!this.area || !this.hueInput) return;

    const init = hexToHsv(root.getAttribute("data-value") || "#3b82f6");
    this.h = init.h;
    this.s = init.s;
    this.v = init.v;
    this.hueInput.value = String(Math.round(this.h));

    const clamp = (n) => Math.min(100, Math.max(0, n));

    this.fromArea = (e) => {
      const r = this.area.getBoundingClientRect();
      this.s = clamp(((e.clientX - r.left) / r.width) * 100);
      this.v = clamp(100 - ((e.clientY - r.top) / r.height) * 100);
      this.commit();
    };

    const onMove = (e) => {
      this.fromArea(e);
      e.preventDefault();
    };
    const onUp = () => {
      root.removeAttribute("data-dragging");
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    };
    this._areaDown = (e) => {
      root.setAttribute("data-dragging", "");
      this.fromArea(e);
      window.addEventListener("pointermove", onMove);
      window.addEventListener("pointerup", onUp);
      e.preventDefault();
    };
    this._hueInput = () => {
      this.h = Number(this.hueInput.value);
      this.commit();
    };
    // Optional editable hex field ([data-part="text"]): parse a valid hex and adopt it.
    this._textInput = () => {
      const val = this.text.value.trim();
      if (!/^#?([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(val)) return;
      const hsv = hexToHsv(val);
      this.h = hsv.h;
      this.s = hsv.s;
      this.v = hsv.v;
      this.hueInput.value = String(Math.round(this.h));
      this.commit();
    };

    this.area.addEventListener("pointerdown", this._areaDown);
    this.hueInput.addEventListener("input", this._hueInput);
    if (this.text) this.text.addEventListener("input", this._textInput);
    this.render();
  },

  updated() {
    // LiveView just patched this subtree, stripping the inline styles the engine set. Adopt the
    // value if the server changed it externally, then re-apply everything.
    const serverHex = this.el.getAttribute("data-value");
    const [r, g, b] = hsvToRgb(this.h, this.s, this.v);
    if (serverHex && serverHex.toLowerCase() !== toHex(r, g, b).toLowerCase()) {
      const hsv = hexToHsv(serverHex);
      this.h = hsv.h;
      this.s = hsv.s;
      this.v = hsv.v;
      if (this.hueInput) this.hueInput.value = String(Math.round(this.h));
    }
    this.render();
  },

  render() {
    this.area.style.background = `linear-gradient(to top, #000, rgba(0,0,0,0)), linear-gradient(to right, #fff, hsl(${this.h}, 100%, 50%))`;
    if (this.areaThumb) {
      this.areaThumb.style.position = "absolute";
      this.areaThumb.style.left = this.s + "%";
      this.areaThumb.style.top = 100 - this.v + "%";
      this.areaThumb.style.translate = "-50% -50%";
    }
    const [r, g, b] = hsvToRgb(this.h, this.s, this.v);
    const hex = toHex(r, g, b);
    if (this.preview) this.preview.style.background = hex;
    if (this.input && this.input.value !== hex) {
      this.input.value = hex;
      this.input.dispatchEvent(new Event("input", { bubbles: true }));
    }
    if (
      this.text &&
      document.activeElement !== this.text &&
      this.text.value.toLowerCase() !== hex.toLowerCase()
    ) {
      this.text.value = hex;
    }
    this.el.setAttribute("data-value", hex);
    return hex;
  },

  // Apply visuals AND notify the server. Called only from user interaction (not from updated()), so
  // there is no render→push→updated→render loop.
  commit() {
    const hex = this.render();
    const on = this.el.getAttribute("data-on-change");
    if (on) this.pushEventTo(this.el, on, { value: hex });
  },

  destroyed() {
    if (this.area) this.area.removeEventListener("pointerdown", this._areaDown);
    if (this.hueInput) this.hueInput.removeEventListener("input", this._hueInput);
    if (this.text) this.text.removeEventListener("input", this._textInput);
  },
};

export default ColorPicker;

// HeadlessCombobox — headless combobox / autocomplete engine.
//
// A text `[data-part="input"]` filters an `[data-part="popup"]` listbox of `[data-part="item"]`
// options as you type (non-matching options get `data-hidden`). ArrowDown opens + moves a roving
// highlight (`data-highlighted` + `aria-activedescendant`) over the NAVIGABLE options (skipping
// `data-hidden` and `data-disabled`); Enter/click selects (a selected item gets `data-selected` +
// `aria-selected`), Escape closes. ARIA: input `role="combobox"` + `aria-expanded` + `aria-controls`;
// list `role="listbox"`; options `role="option"`.
//
// Opt-in extras (each is gated by an attribute/part, so components that don't use them no-op):
//   root `data-multiple`       → multi-select: clicking toggles selection, renders chips, keeps open
//   root `data-creatable`      → show `[data-part="create"]` for the typed query (pushes data-on-create)
//   root `data-autohighlight`  → highlight the first match while typing
//   root `data-filter="contains|starts_with"` → match mode (default contains)
//   root `data-on-change="ev"` → push selected value(s) to LiveView on every change
//   `[data-part="trigger"]`    → button that opens/closes the popup
//   `[data-part="clear"]`      → clears the query/selection (hidden when empty)
//   `[data-part="empty"]`      → shown when nothing matches
//   `[data-part="status"]`     → aria-live result count
//   `[data-part="group"]`      → hidden when all its items are filtered out
//   `[data-part="chips"]` + `<template data-part="chip-template">` → multi-select chips (with `[data-chip-label]`
//                                and a `[data-part="chip-remove"]` button); each chip carries data-chip-value
//
// Distinct from the styled `Combobox` hook (combobox.js); this backs the headless `combobox`
// and `autocomplete` components.

const HeadlessCombobox = {
  mounted() {
    this.input = this.el.querySelector('[data-part="input"]');
    this.popup = this.el.querySelector('[data-part="popup"]');
    this.hidden = this.el.querySelector('[data-part="value"]');
    this.empty = this.el.querySelector('[data-part="empty"]');
    this.status = this.el.querySelector('[data-part="status"]');
    this.clearBtn = this.el.querySelector('[data-part="clear"]');
    this.trigger = this.el.querySelector('[data-part="trigger"]');
    this.chips = this.el.querySelector('[data-part="chips"]');
    this.chipTpl = this.el.querySelector('template[data-part="chip-template"]');
    this.createBtn = this.el.querySelector('[data-part="create"]');
    this.multiple = this.el.hasAttribute("data-multiple");
    this.creatable = this.el.hasAttribute("data-creatable");
    this.name = this.el.getAttribute("data-name");
    this.autoHighlight = this.el.hasAttribute("data-autohighlight");
    this.filterMode = this.el.getAttribute("data-filter") || "contains";
    this.inline = this.el.hasAttribute("data-inline");
    this.items = () => Array.from(this.el.querySelectorAll('[data-part="item"]'));

    if (this.popup && this.popup.id) {
      this.input.setAttribute("role", "combobox");
      this.input.setAttribute("aria-controls", this.popup.id);
      this.input.setAttribute("aria-expanded", "false");
      this.input.setAttribute("aria-autocomplete", "list");
    }

    this.input.addEventListener("input", () => {
      this.filter();
      this.open();
    });
    this.input.addEventListener("focus", () => this.open());
    this.input.addEventListener("keydown", (e) => this.onKey(e));
    this.boundOutside = (e) => {
      if (!this.el.contains(e.target)) this.close();
    };

    this.items().forEach((it) => it.addEventListener("click", () => this.select(it)));
    if (this.clearBtn) this.clearBtn.addEventListener("click", () => this.clear());
    if (this.trigger) this.trigger.addEventListener("click", () => this.toggle());
    if (this.createBtn) this.createBtn.addEventListener("click", () => this.create());
    if (this.chips) {
      this.chips.addEventListener("click", (e) => {
        const rm = e.target.closest('[data-part="chip-remove"]');
        const chip = rm && rm.closest('[data-part="chip"]');
        if (chip) this.deselectValue(chip.getAttribute("data-chip-value"));
      });
    }

    this.sync();
  },

  destroyed() {
    document.removeEventListener("click", this.boundOutside, true);
  },

  valueOf(item) {
    return item.getAttribute("data-value") || item.textContent.trim();
  },

  // The display string shown in the input/chip — distinct from the value (form data) and from the
  // option's rich dropdown content. Falls back to value, never to the full (possibly rich) text.
  labelOf(item) {
    return item.getAttribute("data-label") || item.getAttribute("data-value") || item.textContent.trim();
  },

  // Filterable (not hidden) vs navigable (not hidden AND not disabled).
  visible() {
    return this.items().filter((i) => !i.hasAttribute("data-hidden"));
  },

  navigable() {
    return this.items().filter(
      (i) => !i.hasAttribute("data-hidden") && !i.hasAttribute("data-disabled"),
    );
  },

  highlighted() {
    return this.items().find((i) => i.hasAttribute("data-highlighted")) || null;
  },

  match(text, q) {
    return this.filterMode === "starts_with" ? text.startsWith(q) : text.includes(q);
  },

  filter() {
    const q = this.input.value.trim().toLowerCase();
    this.items().forEach((it) => {
      const hit = this.match(it.textContent.toLowerCase(), q);
      it.toggleAttribute("data-hidden", q !== "" && !hit);
    });
    this.el.querySelectorAll('[data-part="group"]').forEach((g) => {
      const any = Array.from(g.querySelectorAll('[data-part="item"]')).some(
        (i) => !i.hasAttribute("data-hidden"),
      );
      g.toggleAttribute("data-hidden", !any);
    });

    const nav = this.navigable();
    const hl = this.highlighted();
    if (this.autoHighlight && q !== "") this.highlight(nav[0] || null);
    else if (hl && !nav.includes(hl)) this.highlight(null);

    this.sync();
  },

  // Reflect result count into the empty / status / clear / create parts.
  sync() {
    const total = this.items().length;
    const n = this.visible().length;
    const q = this.input.value.trim();
    if (this.empty) this.empty.toggleAttribute("data-hidden", !(total > 0 && n === 0));
    if (this.status) {
      this.status.textContent =
        n === 0 ? "No results" : `${n} result${n === 1 ? "" : "s"} available`;
    }
    if (this.clearBtn) {
      const hasSelection = this.items().some((i) => i.getAttribute("aria-selected") === "true");
      this.clearBtn.toggleAttribute("data-hidden", q === "" && !hasSelection);
    }
    if (this.createBtn) {
      const exact = this.items().some((i) => i.textContent.trim().toLowerCase() === q.toLowerCase());
      this.createBtn.toggleAttribute("data-hidden", !(this.creatable && q !== "" && !exact));
      this.createBtn.querySelectorAll("[data-create-label]").forEach((el) => (el.textContent = q));
    }
  },

  clear() {
    this.input.value = "";
    if (this.hidden) this.hidden.value = "";
    this.items().forEach((i) => {
      i.setAttribute("aria-selected", "false");
      i.removeAttribute("data-selected");
    });
    if (this.chips) this.chips.querySelectorAll('[data-part="chip"]').forEach((c) => c.remove());
    this.filter();
    this.emit();
    this.input.focus();
    this.open();
  },

  open() {
    if (this.input.disabled || !this.popup || this.popup.hasAttribute("data-open")) return;
    this.popup.toggleAttribute("data-open", true);
    this.popup.toggleAttribute("data-closed", false);
    this.input.setAttribute("aria-expanded", "true");
    if (this.autoHighlight) this.highlight(this.navigable()[0] || null);
    document.addEventListener("click", this.boundOutside, true);
  },

  close() {
    if (!this.popup || this.inline) return;
    this.popup.toggleAttribute("data-open", false);
    this.popup.toggleAttribute("data-closed", true);
    this.input.setAttribute("aria-expanded", "false");
    this.highlight(null);
    document.removeEventListener("click", this.boundOutside, true);
  },

  toggle() {
    if (this.popup && this.popup.hasAttribute("data-open")) this.close();
    else {
      this.open();
      this.input.focus();
    }
  },

  onKey(e) {
    const nav = this.navigable();
    const cur = nav.findIndex((i) => i.hasAttribute("data-highlighted"));

    if (e.key === "ArrowDown") {
      e.preventDefault();
      this.open();
      this.highlight(nav[Math.min(nav.length - 1, cur + 1)] || nav[0]);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      this.open();
      this.highlight(nav[Math.max(0, cur - 1)] || nav[nav.length - 1]);
    } else if (e.key === "Enter") {
      if (cur >= 0) {
        e.preventDefault();
        this.select(nav[cur]);
      } else if (this.creatable && this.createBtn && !this.createBtn.hasAttribute("data-hidden")) {
        e.preventDefault();
        this.create();
      }
    } else if (e.key === "Escape") {
      this.close();
    }
  },

  highlight(item) {
    this.items().forEach((i) => i.toggleAttribute("data-highlighted", i === item));
    if (item && item.id) this.input.setAttribute("aria-activedescendant", item.id);
    else this.input.removeAttribute("aria-activedescendant");
  },

  select(item) {
    if (!item || item.hasAttribute("data-disabled")) return;
    const value = this.valueOf(item);
    const label = this.labelOf(item);

    if (this.multiple) {
      const selected = item.getAttribute("aria-selected") === "true";
      item.setAttribute("aria-selected", String(!selected));
      item.toggleAttribute("data-selected", !selected);
      if (selected) this.removeChip(value);
      else this.addChip(value, label);
      this.input.value = "";
      this.filter();
      this.input.focus();
    } else {
      this.input.value = label;
      if (this.hidden) this.hidden.value = value;
      this.items().forEach((i) => {
        const on = i === item;
        i.setAttribute("aria-selected", String(on));
        i.toggleAttribute("data-selected", on);
      });
      this.close();
    }
    this.emit();
    this.sync();
  },

  addChip(value, label) {
    if (!this.chips || !this.chipTpl) return;
    if (this.chips.querySelector(`[data-chip-value="${CSS.escape(value)}"]`)) return;
    const frag = this.chipTpl.content.cloneNode(true);
    const chip = frag.querySelector('[data-part="chip"]');
    if (!chip) return;
    chip.setAttribute("data-chip-value", value);
    chip.querySelectorAll("[data-chip-label]").forEach((el) => (el.textContent = label));
    // Wire the chip's hidden input so an interactively-added selection actually submits (name[]).
    const input = chip.querySelector("[data-chip-input]");
    if (input && this.name) {
      input.setAttribute("name", `${this.name}[]`);
      input.value = value;
    }
    this.chips.appendChild(frag);
  },

  removeChip(value) {
    const chip = this.chips && this.chips.querySelector(`[data-chip-value="${CSS.escape(value)}"]`);
    if (chip) chip.remove();
  },

  deselectValue(value) {
    const item = this.items().find((i) => this.valueOf(i) === value);
    if (item) {
      item.setAttribute("aria-selected", "false");
      item.removeAttribute("data-selected");
    }
    this.removeChip(value);
    this.emit();
    this.sync();
    this.input.focus();
  },

  create() {
    const q = this.input.value.trim();
    if (!q) return;
    const ev = this.el.getAttribute("data-on-create");
    if (ev) this.pushEventTo(this.el, ev, { value: q });
    this.input.value = "";
    this.filter();
  },

  // Push selected value(s) to LiveView: an array in multiple mode, a single value (or null) otherwise.
  emit() {
    // Notify any enclosing <.form phx-change> — programmatic value/chip changes don't fire events.
    // (single → the named hidden value input; multiple → the text input bubbles to the form, which
    // then serializes the chips' name[] inputs). The hook listens for "input" not "change", so safe.
    const formTarget = this.hidden || this.input;
    if (formTarget) formTarget.dispatchEvent(new Event("change", { bubbles: true }));

    const ev = this.el.getAttribute("data-on-change");
    if (!ev) return;
    if (this.multiple) {
      const value = this.items()
        .filter((i) => i.getAttribute("aria-selected") === "true")
        .map((i) => this.valueOf(i));
      this.pushEventTo(this.el, ev, { value });
    } else {
      const sel = this.items().find((i) => i.getAttribute("aria-selected") === "true");
      this.pushEventTo(this.el, ev, { value: sel ? this.valueOf(sel) : null });
    }
  },
};

export default HeadlessCombobox;

// Tooltip — headless tooltip engine (Base UI parity).
//
// A `[data-part="trigger"]` reveals a `role="tooltip"` `[data-part="popup"]` on hover or
// focus, anchored to it by side/align/offset (edge-flip + viewport clamp). Non-modal, never
// steals focus. Options: `hoverable` (can the mouse move into the popup), `disabled`,
// `track_cursor_axis` (popup follows the cursor on x / y / both), and a shared delay `group`
// so once one tooltip in the group is open, the others open instantly. Motion + color = CSS.

const PAD = 8;

// Shared delay groups (Base UI's TooltipProvider): a group stays "warm" while any tooltip
// in it is open and for `timeout` ms after the last closes — warm tooltips open instantly.
const groups = new Map();
function grp(id) {
  if (!groups.has(id)) groups.set(id, { open: 0, warm: false, timer: null });
  return groups.get(id);
}
function groupOnOpen(id) {
  if (!id) return;
  const g = grp(id);
  g.open += 1;
  g.warm = true;
  if (g.timer) {
    clearTimeout(g.timer);
    g.timer = null;
  }
}
function groupOnClose(id, timeout) {
  if (!id) return;
  const g = grp(id);
  g.open = Math.max(0, g.open - 1);
  if (g.open === 0 && !g.timer) {
    g.timer = setTimeout(() => {
      g.warm = false;
      g.timer = null;
    }, timeout);
  }
}
function groupWarm(id) {
  const g = id && groups.get(id);
  return !!(g && g.warm);
}

const Tooltip = {
  mounted() {
    this.trigger = this.el.querySelector('[data-part="trigger"]');
    this.popup = this.el.querySelector('[data-part="popup"]');

    this.side = this.el.getAttribute("data-side") || "top";
    this.align = this.el.getAttribute("data-align") || "center";
    this.sideOffset = parseFloat(this.el.getAttribute("data-side-offset")) || 0;
    this.alignOffset = parseFloat(this.el.getAttribute("data-align-offset")) || 0;
    this.delay = parseFloat(this.el.getAttribute("data-delay"));
    this.closeDelay = parseFloat(this.el.getAttribute("data-close-delay"));
    if (Number.isNaN(this.delay)) this.delay = 600;
    if (Number.isNaN(this.closeDelay)) this.closeDelay = 0;
    this.groupTimeout = parseFloat(this.el.getAttribute("data-group-timeout")) || 400;
    this.hoverable = this.el.getAttribute("data-hoverable") !== "false";
    this.disabled = this.el.getAttribute("data-disabled") === "true";
    this.trackAxis = this.el.getAttribute("data-track-cursor-axis") || "none";
    this.closeOnEscape = this.el.getAttribute("data-close-on-escape") !== "false";
    this.group = this.el.getAttribute("data-group");
    this.onOpenChange = this.el.getAttribute("data-on-open-change");
    this.onOpenChangeTarget = this.el.getAttribute("data-on-open-change-target");

    this.active = false;
    this.boundKeydown = (e) => this.handleKeydown(e);
    this.boundReposition = () => this.reposition();

    if (this.trigger) {
      this.trigger.addEventListener("pointerenter", () => this.scheduleOpen());
      this.trigger.addEventListener("pointerleave", () => this.scheduleClose());
      this.trigger.addEventListener("focusin", () => this.open());
      this.trigger.addEventListener("focusout", (e) => this.onFocusOut(e));
      if (this.trackAxis !== "none") {
        this.trigger.addEventListener("pointermove", (e) => this.onPointerMove(e));
      }
    }
    if (this.popup && this.hoverable) {
      this.popup.addEventListener("pointerenter", () => this.cancelClose());
      this.popup.addEventListener("pointerleave", () => this.scheduleClose());
    }

    if (this.el.hasAttribute("data-open")) this.open(true);
  },

  updated() {
    this.disabled = this.el.getAttribute("data-disabled") === "true";
    const wantsOpen = this.el.hasAttribute("data-open");
    if (wantsOpen && !this.active) this.open(true);
    else if (!wantsOpen && this.active) this.close(true);
  },

  destroyed() {
    this.teardown();
    if (this.openTimer) clearTimeout(this.openTimer);
    if (this.closeTimer) clearTimeout(this.closeTimer);
    if (this.active) groupOnClose(this.group, this.groupTimeout);
  },

  // ---- scheduling --------------------------------------------------------
  scheduleOpen() {
    if (this.disabled) return;
    this.cancelClose();
    if (this.active) return;
    const wait = groupWarm(this.group) ? 0 : this.delay;
    this.openTimer = setTimeout(() => this.open(), wait);
  },
  scheduleClose() {
    if (this.openTimer) clearTimeout(this.openTimer);
    this.closeTimer = setTimeout(() => this.close(), this.closeDelay);
  },
  cancelClose() {
    if (this.closeTimer) clearTimeout(this.closeTimer);
    this.closeTimer = null;
  },
  onFocusOut(e) {
    const to = e.relatedTarget;
    if (to && (this.trigger.contains(to) || (this.popup && this.popup.contains(to)))) return;
    this.close();
  },
  onPointerMove(e) {
    this.cursor = { x: e.clientX, y: e.clientY };
    if (this.active && this.trackAxis !== "none") this.positionPopup();
  },

  // ---- open / close ------------------------------------------------------
  open(serverDriven = false) {
    if (this.openTimer) clearTimeout(this.openTimer);
    this.cancelClose();
    if (this.active || this.disabled) return;
    this.active = true;
    groupOnOpen(this.group);
    this.positionPopup();
    this.popup.hidden = false;
    this.popup.toggleAttribute("data-open", true);
    this.popup.removeAttribute("data-closed");
    this.popup.setAttribute("data-starting-style", "");
    requestAnimationFrame(() =>
      requestAnimationFrame(() => this.popup && this.popup.removeAttribute("data-starting-style")),
    );
    this.el.toggleAttribute("data-open", true);
    this.el.toggleAttribute("data-closed", false);
    if (this.trigger) this.trigger.toggleAttribute("data-popup-open", true);
    document.addEventListener("keydown", this.boundKeydown, true);
    window.addEventListener("scroll", this.boundReposition, true);
    window.addEventListener("resize", this.boundReposition);
    if (!serverDriven) this.emitOpenChange(true);
  },

  close(serverDriven = false) {
    if (this.closeTimer) clearTimeout(this.closeTimer);
    if (!this.active) return;
    this.active = false;
    groupOnClose(this.group, this.groupTimeout);
    this.popup.toggleAttribute("data-open", false);
    this.popup.setAttribute("data-closed", "");
    this.popup.hidden = true;
    this.el.toggleAttribute("data-open", false);
    this.el.toggleAttribute("data-closed", true);
    if (this.trigger) this.trigger.toggleAttribute("data-popup-open", false);
    this.teardown();
    if (!serverDriven) this.emitOpenChange(false);
  },

  teardown() {
    document.removeEventListener("keydown", this.boundKeydown, true);
    window.removeEventListener("scroll", this.boundReposition, true);
    window.removeEventListener("resize", this.boundReposition);
  },

  reposition() {
    if (this.active) this.positionPopup();
  },

  emitOpenChange(open) {
    if (!this.onOpenChange) return;
    if (this.onOpenChangeTarget) this.pushEventTo(this.onOpenChangeTarget, this.onOpenChange, { open });
    else this.pushEventTo(this.el, this.onOpenChange, { open });
  },

  handleKeydown(e) {
    if (this.active && e.key === "Escape" && this.closeOnEscape) this.close();
  },

  // ---- anchored positioning (fixed; flip on the main axis + clamp) --------
  positionPopup() {
    const popup = this.popup;
    popup.style.position = "fixed";
    popup.style.left = "0px";
    popup.style.top = "0px";
    popup.style.visibility = "hidden";
    popup.hidden = false;
    popup.removeAttribute("data-closed");

    const t = this.trigger.getBoundingClientRect();
    const a = { left: t.left, right: t.right, top: t.top, bottom: t.bottom, width: t.width, height: t.height };
    if (this.trackAxis !== "none" && this.cursor) {
      if (this.trackAxis === "x" || this.trackAxis === "both") {
        a.left = a.right = this.cursor.x;
        a.width = 0;
      }
      if (this.trackAxis === "y" || this.trackAxis === "both") {
        a.top = a.bottom = this.cursor.y;
        a.height = 0;
      }
    }

    const p = popup.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const off = this.sideOffset;
    let side = this.side;

    if (side === "bottom" && a.bottom + off + p.height > vh - PAD && a.top - off - p.height > PAD) side = "top";
    else if (side === "top" && a.top - off - p.height < PAD && a.bottom + off + p.height < vh - PAD) side = "bottom";
    else if (side === "right" && a.right + off + p.width > vw - PAD && a.left - off - p.width > PAD) side = "left";
    else if (side === "left" && a.left - off - p.width < PAD && a.right + off + p.width < vw - PAD) side = "right";

    let left;
    let top;
    if (side === "bottom" || side === "top") {
      top = side === "bottom" ? a.bottom + off : a.top - p.height - off;
      if (this.align === "start") left = a.left + this.alignOffset;
      else if (this.align === "end") left = a.right - p.width - this.alignOffset;
      else left = a.left + (a.width - p.width) / 2 + this.alignOffset;
    } else {
      left = side === "right" ? a.right + off : a.left - p.width - off;
      if (this.align === "start") top = a.top + this.alignOffset;
      else if (this.align === "end") top = a.bottom - p.height - this.alignOffset;
      else top = a.top + (a.height - p.height) / 2 + this.alignOffset;
    }

    left = Math.min(Math.max(left, PAD), Math.max(PAD, vw - p.width - PAD));
    top = Math.min(Math.max(top, PAD), Math.max(PAD, vh - p.height - PAD));
    popup.style.left = `${left}px`;
    popup.style.top = `${top}px`;
    popup.setAttribute("data-side", side);
    popup.setAttribute("data-align", this.align);
    // Pin the arrow to the popup edge, centered on the trigger (Base UI's Arrow does this inside the
    // component, so the demo's arrow class stays verbatim — no stylesheet needed).
    const arrow = popup.querySelector('[data-part="arrow"]');
    if (arrow) {
      const center = `${-arrow.offsetWidth / 2}px`;
      const vertical = side === "left" || side === "right";
      arrow.setAttribute("data-side", side);
      arrow.style.position = "absolute";
      arrow.style.left = vertical ? "" : "50%";
      arrow.style.marginLeft = vertical ? "" : center;
      arrow.style.top = vertical ? "50%" : "";
      arrow.style.marginTop = vertical ? center : "";
    }
    popup.style.visibility = "";
  },
};

export default Tooltip;

// Toolbar — a roving-focus bar of heterogeneous controls (Base UI / WAI-ARIA APG parity).
//
// One hook on the root `role="toolbar"` rovs focus over its items — `[data-part="button"]`,
// `[data-part="link"]` and `[data-part="input"]`, in DOM order (including those inside a
// `[data-part="group"]`) — with arrow keys along `data-orientation`, Home/End, and looping when
// `data-loop`. With `data-focusable-when-disabled` (default), DISABLED items STAY in the roving order
// (focusable but inert) so they're discoverable; clicks on disabled items are blocked. A focused
// `[data-part="input"]` keeps its own arrow-key cursor movement and only hands navigation back to the
// toolbar at the text boundaries. `data-disabled` on the root disables the whole toolbar.

const Toolbar = {
  mounted() {
    const el = this.el;
    this.vertical = el.getAttribute("data-orientation") === "vertical";
    this.loop = el.hasAttribute("data-loop");
    this.disabled = el.hasAttribute("data-disabled");
    this.focusableWhenDisabled = el.hasAttribute("data-focusable-when-disabled");

    this.boundKey = (e) => this.onKey(e);
    el.addEventListener("keydown", this.boundKey);
    // block activation of disabled items (they stay focusable, but inert)
    this.boundClick = (e) => {
      const it = e.target.closest('[data-part="button"],[data-part="link"],[data-part="input"]');
      if (it && (this.disabled || it.hasAttribute("data-disabled"))) {
        e.preventDefault();
        e.stopPropagation();
      }
    };
    el.addEventListener("click", this.boundClick, true);
    // when an item is focused (e.g. by click), make it the tabbable one
    this.boundFocus = (e) => {
      const idx = this.items().indexOf(e.target);
      if (idx >= 0) this.roll(idx);
    };
    el.addEventListener("focusin", this.boundFocus);

    this.roll(this.firstIndex());
  },

  destroyed() {
    this.el.removeEventListener("keydown", this.boundKey);
    this.el.removeEventListener("click", this.boundClick, true);
    this.el.removeEventListener("focusin", this.boundFocus);
  },

  // focusable controls in DOM order; disabled stay in the order when focusableWhenDisabled
  items() {
    return Array.from(
      this.el.querySelectorAll('[data-part="button"],[data-part="link"],[data-part="input"]'),
    ).filter((i) => this.focusableWhenDisabled || !i.hasAttribute("data-disabled"));
  },

  firstIndex() {
    const items = this.items();
    const i = items.findIndex((it) => !it.hasAttribute("data-disabled"));
    return i >= 0 ? i : 0;
  },

  roll(idx) {
    this.items().forEach((it, i) => it.setAttribute("tabindex", i === idx ? "0" : "-1"));
  },

  focusItem(idx) {
    const it = this.items()[idx];
    if (!it) return;
    this.roll(idx);
    it.focus();
  },

  onKey(e) {
    if (this.disabled) return;
    const target = e.target.closest('[data-part="button"],[data-part="link"],[data-part="input"]');
    const items = this.items();
    const cur = items.indexOf(target);
    if (cur < 0) return;

    const next = this.vertical ? "ArrowDown" : "ArrowRight";
    const prev = this.vertical ? "ArrowUp" : "ArrowLeft";

    // a text input keeps its own cursor movement; only navigate at the boundaries
    if (target.matches('[data-part="input"]') && (e.key === next || e.key === prev)) {
      const atStart = target.selectionStart === 0 && target.selectionEnd === 0;
      const atEnd = target.selectionStart === target.value.length && target.selectionEnd === target.value.length;
      if (e.key === prev && !atStart) return;
      if (e.key === next && !atEnd) return;
    }

    let idx = null;
    if (e.key === next) idx = this.loop ? (cur + 1) % items.length : Math.min(items.length - 1, cur + 1);
    else if (e.key === prev) idx = this.loop ? (cur - 1 + items.length) % items.length : Math.max(0, cur - 1);
    else if (e.key === "Home") idx = 0;
    else if (e.key === "End") idx = items.length - 1;
    else return;

    e.preventDefault();
    this.focusItem(idx);
  },
};

export default Toolbar;

// Field — headless interaction-state engine for the form-field wrapper.
//
// Tracks the wrapped control (the first input/textarea/select inside `[data-part="control"]`)
// and reflects its interaction state on the field ROOT as data-* attributes for CSS, mirroring
// Base UI Field:
//   data-focused → the control is focused
//   data-touched → the control has been blurred at least once (sticky)
//   data-dirty   → the control's value differs from its initial value
//   data-filled  → the control's value is non-empty
//
// Validity is server-driven: `data-invalid` / `data-disabled` are rendered by the component
// (from `errors` / `disabled`), never touched here. Listeners are delegated on the root
// (focusin/focusout/input bubble) so they survive LiveView re-renders of the control.

const Field = {
  mounted() {
    this.initial = this.value();
    this.sync(); // reflect data-filled for pre-filled values on mount

    this.onFocusIn = () => this.el.toggleAttribute("data-focused", true);
    this.onFocusOut = (e) => {
      // Ignore focus moving between elements inside the same field.
      if (e.relatedTarget && this.el.contains(e.relatedTarget)) return;
      this.el.removeAttribute("data-focused");
      this.el.toggleAttribute("data-touched", true);
    };
    this.onInput = () => this.sync();

    this.el.addEventListener("focusin", this.onFocusIn);
    this.el.addEventListener("focusout", this.onFocusOut);
    this.el.addEventListener("input", this.onInput);
    this.el.addEventListener("change", this.onInput);
  },

  destroyed() {
    this.el.removeEventListener("focusin", this.onFocusIn);
    this.el.removeEventListener("focusout", this.onFocusOut);
    this.el.removeEventListener("input", this.onInput);
    this.el.removeEventListener("change", this.onInput);
  },

  control() {
    return this.el.querySelector(
      '[data-part="control"] input, [data-part="control"] textarea, [data-part="control"] select'
    );
  },

  // Normalized current value of the control ("" when empty/absent).
  value() {
    const c = this.control();
    if (!c) return "";
    if (c.type === "checkbox" || c.type === "radio") return c.checked ? "on" : "";
    return c.value == null ? "" : c.value;
  },

  sync() {
    const v = this.value();
    this.el.toggleAttribute("data-dirty", v !== this.initial);
    this.el.toggleAttribute("data-filled", v !== "");
  },
};

export default Field;

// Chart — headless charting engine (Apache ECharts). One hook, `Chart`, drives every engine; this
// file is the ECharts build. The generator installs exactly one engine file as `chart.js`.
//
// The hook lives on [data-part="surface"], NOT on the component root. The surface is
// `phx-update="ignore"` because ECharts owns that subtree (a <canvas> it draws into), and LiveView
// merges ONLY `data-*` on an ignored element — `class`/`style`/`aria-*` freeze at first render.
// Keeping the boundary inner lets the root stay a normal, server-styled element while `data-*` on
// the surface remains the one live channel from the server.
//
// Element contract:
//   [data-part="root"]     — component root, carries the consumer's class and box dimensions
//   [data-part="surface"]  — carries the hook + phx-update="ignore"; id is `<root id>-surface`;
//                            the engine draws here and all configuration is read from ITS data-*
//
//   data-* on the surface  | meaning
//   -----------------------|---------------------------------------------------------------------
//   data-root-id           | id of the root; the id `chelekom:chart` filters on for live updates
//   data-option            | the whole engine option, JSON-encoded
//   data-theme             | "light"/"dark" to force a palette; empty follows the page
//   data-group             | echarts.connect group — synced tooltip/zoom across charts
//   data-on-click          | LiveView event pushed with a small payload when a datum is clicked
//
// Server -> client: `push_event("chelekom:chart", %{id: <root id>, option: ...})`. A single global
// event name with an id filter in the payload, matching otp.js/editor.js — a per-instance name
// cannot be produced by a LiveComponent that does not know the DOM id. Add `merge: false` to replace
// instead of merge; `resize: true` to force a resize.

import * as echarts from "echarts";
// Developer-owned, created once by the generator and never regenerated. See its header.
import userConfig from "./chart_extensions.js";

const FADE = "chelekom:fade";

// Built-in fallback palette, used only when the CSS custom properties --chart-1..8 are absent and
// the developer set none in chart_extensions.js. Legible on both light and dark backgrounds.
const DEFAULT_PALETTE = [
  "#3b82f6",
  "#22c55e",
  "#f59e0b",
  "#ef4444",
  "#8b5cf6",
  "#14b8a6",
  "#ec4899",
  "#64748b",
];

// ---- pure helpers -------------------------------------------------------------------------------

function cssVar(el, name) {
  return getComputedStyle(el).getPropertyValue(name).trim();
}

// The series palette: --chart-1..8 when present, else the developer palette, else the built-in one.
export function resolvePalette(el) {
  const fromVars = [];
  for (let i = 1; i <= 8; i++) {
    const v = cssVar(el, `--chart-${i}`);
    if (v) fromVars.push(v);
  }
  if (fromVars.length) return fromVars;
  if (Array.isArray(userConfig?.palette) && userConfig.palette.length) return userConfig.palette;
  return DEFAULT_PALETTE;
}

// Axis / grid / label colors, CSS-var first with neutral fallbacks.
function resolveTokens(el) {
  return {
    axis: cssVar(el, "--chart-axis") || "rgba(148,163,184,0.6)",
    grid: cssVar(el, "--chart-grid") || "rgba(148,163,184,0.2)",
    text: cssVar(el, "--chart-text") || cssVar(el, "--color-base-text") || "#64748b",
  };
}

// A JSON option string may be malformed if the server built it wrong; treat that as an empty chart
// rather than throwing, so one bad chart cannot break the whole page.
export function safeParse(raw) {
  if (raw == null || raw === "") return {};
  try {
    return JSON.parse(raw);
  } catch (_e) {
    return {};
  }
}

// "chelekom:currency:USD" etc. -> a real function. A function cannot cross the LiveView wire, so the
// server sends a string and we swap the function in here. Extend via chart_extensions.js. Returns
// null for anything that is not a known formatter sentinel (e.g. "chelekom:fade", handled elsewhere).
export function intlFormatter(token) {
  const [ns, kind, arg] = token.split(":");
  if (ns !== "chelekom") return null;

  const custom = userConfig?.formatters?.[kind];
  if (typeof custom === "function") return (v) => custom(v, arg);

  switch (kind) {
    case "number":
      return (v) => new Intl.NumberFormat().format(v);
    case "compact":
      return (v) => new Intl.NumberFormat(undefined, { notation: "compact" }).format(v);
    case "percent":
      return (v) =>
        new Intl.NumberFormat(undefined, { style: "percent", maximumFractionDigits: 1 }).format(v);
    case "currency":
      return (v) =>
        new Intl.NumberFormat(undefined, { style: "currency", currency: arg || "USD" }).format(v);
    default:
      return null;
  }
}

// Walk the option and replace formatter sentinels with real functions. "chelekom:fade" is left as a
// string for applyFade, which needs the series color. Everything else is returned untouched.
function resolveSentinels(node) {
  if (Array.isArray(node)) return node.map(resolveSentinels);
  if (node && typeof node === "object") {
    const out = {};
    for (const [k, v] of Object.entries(node)) out[k] = resolveSentinels(v);
    return out;
  }
  if (typeof node === "string" && node.startsWith("chelekom:") && node !== FADE) {
    const fn = intlFormatter(node);
    if (fn) return fn;
  }
  return node;
}

function withAlpha(color, alpha) {
  const m6 = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(color);
  const m3 = /^#([0-9a-f])([0-9a-f])([0-9a-f])$/i.exec(color);
  let r, g, b;
  if (m6) {
    [r, g, b] = [m6[1], m6[2], m6[3]].map((h) => parseInt(h, 16));
  } else if (m3) {
    [r, g, b] = [m3[1], m3[2], m3[3]].map((h) => parseInt(h + h, 16));
  } else {
    return color;
  }
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

// Replace `areaStyle.color === "chelekom:fade"` with a top-to-transparent gradient of the series'
// own color, so filled line/area charts fade the right hue with no color hard-coded server-side.
function applyFade(option, palette) {
  if (!option.series) return;
  const list = Array.isArray(option.series) ? option.series : [option.series];
  list.forEach((s, i) => {
    if (s && s.areaStyle && s.areaStyle.color === FADE) {
      const base =
        s.itemStyle?.color ||
        s.lineStyle?.color ||
        s.color ||
        palette[i % palette.length];
      s.areaStyle.color = new echarts.graphic.LinearGradient(0, 0, 0, 1, [
        { offset: 0, color: withAlpha(base, 0.35) },
        { offset: 1, color: withAlpha(base, 0) },
      ]);
    }
  });
}

// Decorate any axis (object or array) with themed defaults the user's own settings win over.
function decorateAxes(axis, tokens) {
  if (!axis) return axis;
  const base = (a) => ({
    axisLine: { lineStyle: { color: tokens.axis }, ...(a?.axisLine || {}) },
    axisTick: { lineStyle: { color: tokens.axis }, ...(a?.axisTick || {}) },
    axisLabel: { color: tokens.text, ...(a?.axisLabel || {}) },
    splitLine: {
      lineStyle: { color: tokens.grid },
      ...(a?.splitLine || {}),
      show: a?.splitLine?.show ?? false,
    },
    ...a,
  });
  return Array.isArray(axis) ? axis.map(base) : base(axis);
}

// Inject palette + text/axis/grid colors as DEFAULTS; anything the option already sets is kept.
function applyTheme(option, palette, tokens) {
  if (!option.color) option.color = palette;
  option.backgroundColor = option.backgroundColor || "transparent";
  option.textStyle = { color: tokens.text, ...(option.textStyle || {}) };
  if (option.xAxis) option.xAxis = decorateAxes(option.xAxis, tokens);
  if (option.yAxis) option.yAxis = decorateAxes(option.yAxis, tokens);
  if (option.legend) {
    const legends = Array.isArray(option.legend) ? option.legend : [option.legend];
    legends.forEach((l) => (l.textStyle = { color: tokens.text, ...(l.textStyle || {}) }));
  }
  // The surface clips overflow (so the chart never forces a page scrollbar), which would also clip a
  // tooltip near an edge — confine it to the box unless the option says otherwise.
  if (option.tooltip && option.tooltip.confine === undefined) option.tooltip.confine = true;
  return option;
}

function clickPayload(params) {
  return {
    name: params.name,
    value: params.value,
    seriesName: params.seriesName,
    seriesIndex: params.seriesIndex,
    dataIndex: params.dataIndex,
    componentType: params.componentType,
  };
}

// ---- hook ---------------------------------------------------------------------------------------

const Chart = {
  mounted() {
    const el = this.el;
    this.rootId = el.getAttribute("data-root-id");
    this.root = document.getElementById(this.rootId) || el.parentElement;
    this.onClick = el.getAttribute("data-on-click");
    this.group = el.getAttribute("data-group") || null;
    this.domOption = el.getAttribute("data-option");
    this.raw = this.domOption;

    this.chart = echarts.init(el, null, { renderer: "canvas" });
    this.chart.setOption(this.prepare(this.raw));

    if (this.group) {
      this.chart.group = this.group;
      echarts.connect(this.group);
    }

    if (this.onClick) {
      this.chart.on("click", (params) => {
        this.pushEventTo(this.el, this.onClick, clickPayload(params));
      });
    }

    // A chart inside a hidden tab mounts at 0×0; ResizeObserver repaints it the moment it is shown,
    // and also handles ordinary window/layout resizes without a window listener.
    this.ro = new ResizeObserver(() => this.chart && this.chart.resize());
    this.ro.observe(el);

    // Re-theme on a light/dark toggle when the palette is not forced: the CSS vars change, so we
    // re-read them and re-apply. Guarded to avoid a render->patch loop (setOption never pushes).
    if (!el.getAttribute("data-theme")) {
      this.themeObserver = new MutationObserver(() => this.retheme());
      this.themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["data-theme", "class"],
      });
      this.mql = window.matchMedia("(prefers-color-scheme: dark)");
      this._onScheme = () => this.retheme();
      this.mql.addEventListener("change", this._onScheme);
    }

    this.ref = this.handleEvent("chelekom:chart", (payload) => {
      if (!payload || (payload.id && payload.id !== this.rootId)) return;
      if (payload.option != null) {
        this.raw = payload.option;
        this.chart.setOption(this.prepare(this.raw), { notMerge: payload.merge === false });
      }
      if (payload.resize) this.chart.resize();
    });
  },

  // Only data-* survive on an ignored element, so a server re-assign of `option` lands on
  // data-option. Re-apply only when it actually changed, so unrelated patches do not thrash.
  updated() {
    if (!this.chart) return;
    const next = this.el.getAttribute("data-option");
    if (next !== this.domOption) {
      this.domOption = next;
      this.raw = next;
      this.chart.setOption(this.prepare(this.raw));
    }
  },

  destroyed() {
    if (this.ro) this.ro.disconnect();
    if (this.themeObserver) this.themeObserver.disconnect();
    if (this.mql && this._onScheme) this.mql.removeEventListener("change", this._onScheme);
    if (this.ref) this.removeHandleEvent(this.ref);
    // The single biggest leak: without dispose the ECharts instance, its canvas and listeners
    // outlive every LiveView navigation.
    if (this.chart) this.chart.dispose();
    this.chart = null;
  },

  // Parse (if a string), resolve sentinels, then inject the current theme. Palette/tokens are read
  // fresh each time so a theme toggle recolors correctly. Accepts a JSON string or an object.
  prepare(raw) {
    const palette = resolvePalette(this.el);
    const tokens = resolveTokens(this.el);
    const parsed = typeof raw === "string" ? safeParse(raw) : raw || {};
    const option = resolveSentinels(parsed);
    applyTheme(option, palette, tokens);
    applyFade(option, palette);
    return option;
  },

  retheme() {
    if (this.chart) this.chart.setOption(this.prepare(this.raw), { notMerge: true });
  },
};

export default Chart;

// Editor — headless rich-text editor engine (TipTap 3 / ProseMirror).
//
// The hook lives on `[data-part="surface"]`, NOT on the component root. The surface is
// `phx-update="ignore"` because TipTap owns that subtree, and LiveView merges ONLY `data-*` on an
// ignored element — `class`, `style` and `aria-*` freeze at first render. Keeping the boundary
// inner lets the root stay a normal, server-styled element while `data-*` on the surface remains
// the one live channel from the server.
//
// Element contract:
//   [data-part="root"]     — component root, carries the consumer's class and the state attrs the
//                            engine writes: data-empty, data-focused
//   [data-part="surface"]  — carries the hook + phx-update="ignore"; id is `<root id>-surface`;
//                            all configuration is read from ITS data-* (see table below)
//   [data-part="value"]    — hidden <textarea> mirror carrying `name`; what the form submits.
//                            Never give it phx-change: LiveView's form recovery skips elements
//                            that have one, and the document would be lost on reconnect.
//   [data-editor-command]  — optional toolbar buttons anywhere in the root; the engine binds them
//                            by delegation (so they survive morphdom) and marks the active ones
//                            with data-active.
//
//   data-* on the surface   | meaning
//   ------------------------|--------------------------------------------------------------
//   data-root-id            | id of the root; also the id `chelekom:editor` filters on
//   data-value-id           | id of the hidden mirror
//   data-format             | "json" (default, XSS-safe) or "html"
//   data-value              | initial document
//   data-placeholder        | empty-state text, rendered by CSS from data-empty on the root
//   data-editable           | "true"/"false" — live-togglable, since data-* crosses the boundary
//   data-debounce           | ms to wait before committing to the mirror (default 300)
//   data-on-change          | LiveView event pushed with {value} after each commit
//   data-on-focus/-blur     | optional LiveView events, pushed with {value}
//
// Server -> client: `push_event("chelekom:editor", %{id: <root id>, value: ...})`. A single global
// event name with an id filter in the payload, matching otp.js — a per-instance name cannot be
// produced by a LiveComponent that does not know the DOM id.

import { Editor as TipTapEditor } from "@tiptap/core";
import StarterKit from "@tiptap/starter-kit";
// Developer-owned, created once by the generator and never regenerated. See its header.
import userConfig from "./editor_extensions.js";

// Commands a toolbar button may request via [data-editor-command]. Each maps to a TipTap chain.
const COMMANDS = {
  bold: (c) => c.toggleBold(),
  italic: (c) => c.toggleItalic(),
  strike: (c) => c.toggleStrike(),
  code: (c) => c.toggleCode(),
  paragraph: (c) => c.setParagraph(),
  h1: (c) => c.toggleHeading({ level: 1 }),
  h2: (c) => c.toggleHeading({ level: 2 }),
  h3: (c) => c.toggleHeading({ level: 3 }),
  bullet_list: (c) => c.toggleBulletList(),
  ordered_list: (c) => c.toggleOrderedList(),
  blockquote: (c) => c.toggleBlockquote(),
  code_block: (c) => c.toggleCodeBlock(),
  horizontal_rule: (c) => c.setHorizontalRule(),
  undo: (c) => c.undo(),
  redo: (c) => c.redo(),
};

// What `isActive` should be asked for a given command, when it is a toggle.
const ACTIVE_CHECKS = {
  bold: ["bold"],
  italic: ["italic"],
  strike: ["strike"],
  code: ["code"],
  paragraph: ["paragraph"],
  h1: ["heading", { level: 1 }],
  h2: ["heading", { level: 2 }],
  h3: ["heading", { level: 3 }],
  bullet_list: ["bulletList"],
  ordered_list: ["orderedList"],
  blockquote: ["blockquote"],
  code_block: ["codeBlock"],
};

// ---- pure helpers -------------------------------------------------------------------------

// JSON documents arrive as a string on a data-* attribute. Anything unparseable is treated as
// "no document" rather than throwing, so one bad row can never break the whole page.
export function parseInitial(raw, format) {
  if (raw == null || raw === "") return format === "json" ? null : "";
  if (format !== "json") return raw;

  try {
    return JSON.parse(raw);
  } catch (_e) {
    return null;
  }
}

export function serialize(editor, format) {
  if (!editor) return "";
  return format === "json" ? JSON.stringify(editor.getJSON()) : editor.getHTML();
}

function toggle(el, attr, on) {
  if (!el) return;
  if (on) el.setAttribute(attr, "");
  else el.removeAttribute(attr);
}

// ---- hook ---------------------------------------------------------------------------------

const Editor = {
  mounted() {
    const el = this.el;

    this.rootId = el.getAttribute("data-root-id");
    this.root = document.getElementById(this.rootId) || el.parentElement;
    this.hidden = document.getElementById(el.getAttribute("data-value-id"));
    this.format = el.getAttribute("data-format") === "html" ? "html" : "json";
    this.debounceMs = parseInt(el.getAttribute("data-debounce"), 10) || 300;
    this.onChange = el.getAttribute("data-on-change");
    this.onFocus = el.getAttribute("data-on-focus");
    this.onBlur = el.getAttribute("data-on-blur");
    this.timer = null;
    this.remote = false;

    const config = userConfig || {};

    this.editor = new TipTapEditor({
      element: el,
      extensions: [StarterKit.configure(config.starterKit || {}), ...(config.extensions || [])],
      content: parseInitial(el.getAttribute("data-value"), this.format),
      editable: el.getAttribute("data-editable") !== "false",
      onUpdate: () => this.schedule(),
      onSelectionUpdate: () => this.render(),
      onFocus: () => {
        this.render();
        this.push(this.onFocus);
      },
      onBlur: () => {
        this.render();
        this.commit();
        this.push(this.onBlur);
      },
    });

    // Toolbar clicks are delegated from the root, not bound per button: the toolbar lives outside
    // the ignored subtree, so morphdom may replace those nodes on any patch and per-node
    // listeners would silently stop working.
    this._onToolbar = (event) => {
      const button = event.target.closest("[data-editor-command]");
      if (!button || !this.root.contains(button) || !this.editor) return;
      const run = COMMANDS[button.getAttribute("data-editor-command")];
      if (!run) return;
      event.preventDefault();
      run(this.editor.chain().focus()).run();
    };

    // Pressing a toolbar button must not blur the editor first, or the command applies to a lost
    // selection.
    this._onToolbarDown = (event) => {
      if (event.target.closest("[data-editor-command]")) event.preventDefault();
    };

    this.root.addEventListener("click", this._onToolbar);
    this.root.addEventListener("mousedown", this._onToolbarDown);

    // The editable node is stretched by CSS, but the surface can still carry padding of its own.
    // A click there is a click on a non-editable box, so place the caret explicitly instead of
    // making the user aim at the text.
    this._onSurfaceDown = (event) => {
      if (!this.editor || event.target.closest(".ProseMirror")) return;
      this.editor.commands.focus("end");
    };

    el.addEventListener("mousedown", this._onSurfaceDown);

    // `attr()` can only read from the element the pseudo-element is on, and the placeholder CSS
    // lives on `.ProseMirror` (the stretched child), so mirror it there.
    const view = el.querySelector(".ProseMirror");
    const placeholder = el.getAttribute("data-placeholder");
    if (view && placeholder) view.setAttribute("data-placeholder", placeholder);

    this.setRef = this.handleEvent("chelekom:editor", (payload) => {
      if (!payload || (payload.id && payload.id !== this.rootId)) return;
      this.applyRemote(payload.value ?? "");
    });

    this.render();
  },

  // Only data-* survive on an ignored element, so this is where live config lands. Never destroy
  // and rebuild the editor here — that would lose the cursor and the undo history.
  updated() {
    if (!this.editor) return;

    const editable = this.el.getAttribute("data-editable") !== "false";
    if (this.editor.isEditable !== editable) this.editor.setEditable(editable);

    // A patch may have stripped the state attrs the engine owns; repaint them.
    this.render();
  },

  destroyed() {
    if (this.timer) clearTimeout(this.timer);
    if (this.setRef) this.removeHandleEvent(this.setRef);
    if (this.root) {
      this.root.removeEventListener("click", this._onToolbar);
      this.root.removeEventListener("mousedown", this._onToolbarDown);
    }
    this.el.removeEventListener("mousedown", this._onSurfaceDown);
    // The single biggest leak: without this the ProseMirror view, its plugins and its DOM
    // listeners outlive every LiveView navigation.
    if (this.editor) this.editor.destroy();
    this.editor = null;
  },

  // Presentation only — never pushes, so it is safe to call from updated() without risking a
  // render -> push -> patch -> render loop.
  render() {
    if (!this.editor) return;

    toggle(this.root, "data-empty", this.editor.isEmpty);
    toggle(this.root, "data-focused", this.editor.isFocused);

    for (const button of this.root.querySelectorAll("[data-editor-command]")) {
      const check = ACTIVE_CHECKS[button.getAttribute("data-editor-command")];
      if (check) toggle(button, "data-active", this.editor.isActive(...check));
    }
  },

  // The only place that writes the mirror and pushes.
  commit() {
    if (!this.editor || !this.hidden) return;

    const next = serialize(this.editor, this.format);
    if (this.hidden.value === next) return;

    this.hidden.value = next;
    // Bubbling, and a plain Event on a form-associated element: this is what makes an enclosing
    // <.form phx-change> fire for a value set programmatically.
    this.hidden.dispatchEvent(new Event("input", { bubbles: true }));
    this.push(this.onChange, next);
  },

  schedule() {
    this.render();
    // Server-applied content must not echo straight back as a user edit.
    if (this.remote) return;
    if (this.timer) clearTimeout(this.timer);
    this.timer = setTimeout(() => this.commit(), this.debounceMs);
  },

  applyRemote(value) {
    if (!this.editor) return;
    this.remote = true;

    try {
      this.editor.commands.setContent(parseInitial(value, this.format), false);
      if (this.hidden) this.hidden.value = serialize(this.editor, this.format);
      this.render();
    } finally {
      this.remote = false;
    }
  },

  push(event, value) {
    if (!event) return;
    this.pushEventTo(this.el, event, { value: value ?? serialize(this.editor, this.format) });
  },
};

export default Editor;

// AngleSlider — a circular control for picking an angle 0–360° (Mantine AngleSlider parity).
//
// 0° points up and increases clockwise. Pointer drag (and arrow keys) set the angle; the thumb layer
// is rotated to place the handle on the circle and a `--angle` custom property is exposed for an
// optional conic-gradient fill. The value is mirrored into `[data-part="input"]` for form submission
// and, if `data-on-change` names an event, pushed to the server on release / key change.
//
// Element contract:
//   root                     — carries the hook; data-value, data-step, data-disabled, data-on-change
//   [data-part="thumb-layer"]— absolutely fills the root; rotated by the angle
//   [data-part="input"]      — optional hidden input to submit the value
//   [data-part="value"]      — optional element whose text becomes "<deg>°"

const norm = (deg) => ((deg % 360) + 360) % 360;

const AngleSlider = {
  mounted() {
    this.step = parseFloat(this.el.getAttribute("data-step")) || 1;
    this.on = this.el.getAttribute("data-on-change");
    this.layer = this.el.querySelector('[data-part="thumb-layer"]');
    this.input = this.el.querySelector('[data-part="input"]');
    this.valueEl = this.el.querySelector('[data-part="value"]');

    this._value = this.readValue();
    this.render();

    this._onDown = (e) => {
      if (this.isDisabled()) return;
      e.preventDefault();
      this.el.focus();
      this.dragging = true;
      this.el.setAttribute("data-dragging", "");
      this.moveTo(e);
      window.addEventListener("pointermove", this._onMove);
      window.addEventListener("pointerup", this._onUp);
    };
    this._onMove = (e) => {
      if (this.dragging) this.moveTo(e);
    };
    this._onUp = () => {
      this.dragging = false;
      this.el.removeAttribute("data-dragging");
      window.removeEventListener("pointermove", this._onMove);
      window.removeEventListener("pointerup", this._onUp);
      this.commit();
    };
    this._onKey = (e) => this.onKey(e);

    this.el.addEventListener("pointerdown", this._onDown);
    this.el.addEventListener("keydown", this._onKey);
  },

  isDisabled() {
    return this.el.hasAttribute("data-disabled");
  },

  readValue() {
    const v = parseFloat(this.el.getAttribute("data-value"));
    return isNaN(v) ? 0 : norm(v);
  },

  snap(deg) {
    const s = Math.round(norm(deg) / this.step) * this.step;
    return norm(s);
  },

  moveTo(e) {
    const rect = this.el.getBoundingClientRect();
    const dx = e.clientX - (rect.left + rect.width / 2);
    const dy = e.clientY - (rect.top + rect.height / 2);
    // atan2(dx, -dy): 0° at top, positive clockwise.
    this._value = this.snap(Math.atan2(dx, -dy) * (180 / Math.PI));
    this.render();
  },

  onKey(e) {
    if (this.isDisabled()) return;
    let d = 0;
    switch (e.key) {
      case "ArrowRight":
      case "ArrowUp":
        d = this.step;
        break;
      case "ArrowLeft":
      case "ArrowDown":
        d = -this.step;
        break;
      case "Home":
        e.preventDefault();
        this._value = 0;
        this.render();
        this.commit();
        return;
      case "End":
        e.preventDefault();
        this._value = norm(360 - this.step);
        this.render();
        this.commit();
        return;
      default:
        return;
    }
    e.preventDefault();
    this._value = norm(this._value + d);
    this.render();
    this.commit();
  },

  render() {
    const deg = this._value;
    if (this.layer) this.layer.style.transform = `rotate(${deg}deg)`;
    this.el.style.setProperty("--angle", `${deg}deg`);
    this.el.setAttribute("data-value", String(deg));
    this.el.setAttribute("aria-valuenow", String(Math.round(deg)));
    this.el.setAttribute("aria-valuetext", `${Math.round(deg)} degrees`);
    if (this.input) this.input.value = String(deg);
    if (this.valueEl) this.valueEl.textContent = `${Math.round(deg)}°`;
  },

  commit() {
    if (this.input) this.input.dispatchEvent(new Event("input", { bubbles: true }));
    if (this.on) this.pushEventTo(this.el, this.on, { value: Math.round(this._value) });
  },

  updated() {
    if (this.dragging) return;
    this._value = this.readValue();
    this.render();
  },

  destroyed() {
    this.el.removeEventListener("pointerdown", this._onDown);
    this.el.removeEventListener("keydown", this._onKey);
    window.removeEventListener("pointermove", this._onMove);
    window.removeEventListener("pointerup", this._onUp);
  },
};

export default AngleSlider;

// MaskInput — format-as-you-type input masking (Mantine MaskInput parity).
//
// `data-mask` is a pattern where `9` = digit, `a` = letter, `*` = alphanumeric, and every other
// character is a literal that is inserted automatically (e.g. `(999) 999-9999`, `99/99/9999`). On
// each input the value is re-masked; literals never block typing, and a separator is auto-inserted
// as soon as the group before it completes. The masked value is what submits with the form. The
// masking runs in the element's own `input` listener, so LiveView's delegated phx-change handler
// always reads the already-masked value.

function applyMask(value, mask) {
  const fillable = (value || "").replace(/[^a-zA-Z0-9]/g, "");
  if (!fillable) return "";

  const chars = value.split("");
  let out = "";
  let vi = 0;

  const nextMatch = (test) => {
    while (vi < chars.length) {
      const c = chars[vi++];
      if (test(c)) return c;
    }
    return null;
  };

  for (const m of mask) {
    if (m === "9" || m === "a" || m === "*") {
      const test =
        m === "9"
          ? (c) => /\d/.test(c)
          : m === "a"
            ? (c) => /[a-zA-Z]/.test(c)
            : (c) => /[a-zA-Z0-9]/.test(c);
      const ch = nextMatch(test);
      if (ch === null) break;
      out += ch;
    } else {
      out += m;
    }
  }

  return out;
}

const MaskInput = {
  mounted() {
    this.mask = this.el.getAttribute("data-mask") || "";
    this._onInput = () => {
      const masked = applyMask(this.el.value, this.mask);
      if (this.el.value !== masked) {
        this.el.value = masked;
        const pos = masked.length;
        try {
          this.el.setSelectionRange(pos, pos);
        } catch (_e) {}
      }
    };
    this.el.addEventListener("input", this._onInput);
    if (this.el.value) this._onInput();
  },

  updated() {
    this.mask = this.el.getAttribute("data-mask") || this.mask;
    if (this.el.value) this.el.value = applyMask(this.el.value, this.mask);
  },

  destroyed() {
    this.el.removeEventListener("input", this._onInput);
  },
};

export default MaskInput;

// Menubar — a coordinated bar of menus (Base UI / WAI-ARIA APG menubar parity).
//
// One hook on the root `role="menubar"` owns: roving tabindex over the top-level `[data-part="trigger"]`
// buttons (arrow keys along `data-orientation`, Home/End, looping when `data-loop`), opening/closing the
// per-menu `[data-part="popup"]`, and — the defining menubar behaviour — switching the open menu when
// the pointer enters (or the arrow keys reach) a different trigger while a menu is already open.
//
// Inside an open menu: Arrow Up/Down move between `[role="menuitem"]`/`[data-part="item"]`, Home/End jump,
// Escape closes back to the trigger, and the cross-axis arrow opens the menu / left-right hops to the
// adjacent menu. Activating an item closes the menu. Reflects Base UI state: root `data-has-submenu-open`
// + `data-modal` + `data-orientation`; the active trigger gets `data-popup-open` + `data-pressed`; the
// popup `data-open`/`data-closed` (positioning + hide are the consumer's CSS, like the styled menubar).

const Menubar = {
  mounted() {
    const el = this.el;
    this.vertical = el.getAttribute("data-orientation") === "vertical";
    this.loop = el.hasAttribute("data-loop");
    this.disabled = el.hasAttribute("data-disabled");

    this.menus = Array.from(el.querySelectorAll('[data-part="menu"]')).map((menu) => ({
      menu,
      trigger: menu.querySelector('[data-part="trigger"]'),
      popup: menu.querySelector('[data-part="popup"]'),
    }));
    this.openIndex = -1;

    this.boundOutside = (e) => {
      if (!el.contains(e.target)) this.closeAll();
    };

    this.menus.forEach((m, i) => {
      if (!m.trigger) return;
      m.trigger.addEventListener("click", (e) => {
        e.stopPropagation();
        this.onTriggerClick(i);
      });
      m.trigger.addEventListener("pointerenter", () => this.onTriggerEnter(i));
      m.trigger.addEventListener("keydown", (e) => this.onTriggerKey(e, i));
      if (m.popup) {
        m.popup.addEventListener("keydown", (e) => this.onPopupKey(e, i));
        // pointer over an item highlights it (shares the keyboard highlight state)
        m.popup.addEventListener("pointermove", (e) => {
          const it = e.target.closest('[role="menuitem"],[data-part="item"]');
          if (it && !it.hasAttribute("data-disabled") && !it.hasAttribute("disabled")) this.setHighlighted(i, it);
        });
        // activating any item closes the menu (the item's own phx-click still fires)
        m.popup.addEventListener("click", (e) => {
          if (e.target.closest('[role="menuitem"],[data-part="item"]')) this.close(i, false);
        });
      }
    });

    this.roll(this.firstEnabled());
  },

  destroyed() {
    document.removeEventListener("click", this.boundOutside, true);
  },

  // ---- helpers --------------------------------------------------------------

  enabled(i) {
    return this.menus[i].trigger && !this.menus[i].trigger.hasAttribute("data-disabled");
  },

  enabledTriggers() {
    return this.menus.map((_, i) => i).filter((i) => this.enabled(i));
  },

  firstEnabled() {
    return this.enabledTriggers()[0] ?? 0;
  },

  roll(focusIndex) {
    this.menus.forEach((m, i) => {
      if (m.trigger) m.trigger.setAttribute("tabindex", i === focusIndex ? "0" : "-1");
    });
  },

  items(i) {
    return Array.from(this.menus[i].popup.querySelectorAll('[role="menuitem"],[data-part="item"]')).filter(
      (it) => !it.hasAttribute("data-disabled") && !it.hasAttribute("disabled"),
    );
  },

  focusFirstItem(i) {
    const it = this.items(i)[0];
    if (it) requestAnimationFrame(() => this.focusInItem(i, it));
  },

  // focus an item + mark it the highlighted one (data-highlighted), clearing its siblings
  focusInItem(i, item) {
    if (!item) return;
    item.focus();
    this.setHighlighted(i, item);
  },

  setHighlighted(i, target) {
    this.menus[i].popup
      .querySelectorAll('[role="menuitem"],[data-part="item"]')
      .forEach((it) => it.toggleAttribute("data-highlighted", it === target));
  },

  // ---- open / close ---------------------------------------------------------

  onTriggerClick(i) {
    if (this.disabled || !this.enabled(i)) return;
    if (this.openIndex === i) this.close(i, true);
    else this.open(i);
  },

  onTriggerEnter(i) {
    // menubar mode: with a menu already open, hovering another trigger switches to it
    if (this.openIndex !== -1 && this.openIndex !== i && this.enabled(i)) this.open(i);
  },

  open(i) {
    if (this.disabled || !this.enabled(i)) return;
    if (this.openIndex !== -1 && this.openIndex !== i) this.close(this.openIndex, false);

    const m = this.menus[i];
    m.popup.toggleAttribute("data-open", true);
    m.popup.toggleAttribute("data-closed", false);
    m.trigger.setAttribute("aria-expanded", "true");
    m.trigger.toggleAttribute("data-popup-open", true);
    m.trigger.toggleAttribute("data-pressed", true);

    this.openIndex = i;
    this.el.toggleAttribute("data-has-submenu-open", true);
    this.roll(i);
    m.trigger.focus();
    document.addEventListener("click", this.boundOutside, true);
  },

  close(i, focusTrigger) {
    const m = this.menus[i];
    if (!m) return;
    m.popup.toggleAttribute("data-open", false);
    m.popup.toggleAttribute("data-closed", true);
    m.popup
      .querySelectorAll("[data-highlighted]")
      .forEach((it) => it.removeAttribute("data-highlighted"));
    m.trigger.setAttribute("aria-expanded", "false");
    m.trigger.removeAttribute("data-popup-open");
    m.trigger.removeAttribute("data-pressed");

    if (this.openIndex === i) {
      this.openIndex = -1;
      this.el.removeAttribute("data-has-submenu-open");
      document.removeEventListener("click", this.boundOutside, true);
    }
    if (focusTrigger) m.trigger.focus();
  },

  closeAll() {
    if (this.openIndex !== -1) this.close(this.openIndex, false);
  },

  // ---- keyboard -------------------------------------------------------------

  onTriggerKey(e, i) {
    const next = this.vertical ? "ArrowDown" : "ArrowRight";
    const prev = this.vertical ? "ArrowUp" : "ArrowLeft";
    const openKey = this.vertical ? "ArrowRight" : "ArrowDown";

    if (e.key === next) {
      e.preventDefault();
      this.step(i, +1);
    } else if (e.key === prev) {
      e.preventDefault();
      this.step(i, -1);
    } else if (e.key === "Home") {
      e.preventDefault();
      this.focusTrigger(this.enabledTriggers()[0]);
    } else if (e.key === "End") {
      e.preventDefault();
      const t = this.enabledTriggers();
      this.focusTrigger(t[t.length - 1]);
    } else if (e.key === openKey || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      this.open(i);
      this.focusFirstItem(i);
    } else if (e.key === "Escape") {
      this.closeAll();
    }
  },

  // move focus to the adjacent trigger; if a menu is open, switch the open menu too
  step(from, dir) {
    const triggers = this.enabledTriggers();
    const pos = triggers.indexOf(from);
    let np = pos + dir;
    np = this.loop
      ? (np + triggers.length) % triggers.length
      : Math.max(0, Math.min(triggers.length - 1, np));
    const ni = triggers[np];
    if (ni === from) return;
    if (this.openIndex !== -1) {
      this.open(ni);
      this.focusFirstItem(ni);
    } else {
      this.focusTrigger(ni);
    }
  },

  focusTrigger(i) {
    this.roll(i);
    this.menus[i].trigger.focus();
  },

  onPopupKey(e, i) {
    const items = this.items(i);
    const cur = items.indexOf(document.activeElement);

    if (e.key === "ArrowDown") {
      e.preventDefault();
      this.moveItem(i, items, cur, +1);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      this.moveItem(i, items, cur, -1);
    } else if (e.key === "Home") {
      e.preventDefault();
      this.focusInItem(i, items[0]);
    } else if (e.key === "End") {
      e.preventDefault();
      this.focusInItem(i, items[items.length - 1]);
    } else if (e.key === "Escape") {
      e.preventDefault();
      this.close(i, true);
    } else if (e.key === "Tab") {
      this.closeAll();
    } else if (!this.vertical && (e.key === "ArrowRight" || e.key === "ArrowLeft")) {
      // hop to the adjacent top-level menu from inside a popup
      e.preventDefault();
      this.step(i, e.key === "ArrowRight" ? +1 : -1);
    }
  },

  moveItem(i, items, cur, dir) {
    if (!items.length) return;
    let n = cur + dir;
    if (n < 0) n = items.length - 1;
    if (n >= items.length) n = 0;
    this.focusInItem(i, items[n]);
  },
};

export default Menubar;

// FloatingWindow — a draggable panel positioned inside its nearest positioned ancestor (Mantine
// FloatingWindow parity).
//
// Drag the `handle` to move the window — or focus it and use the arrow keys (10px, 1px with
// Shift), the WCAG 2.5.7 alternative to dragging. The window is clamped to stay inside its offset
// parent. Position is mirrored into `data-x` / `data-y` and, if `data-on-move` names an event,
// pushed to the server on release / key move. Clicks on interactive controls inside the handle
// (buttons, links, inputs) do not start a drag, so a close button in the title bar keeps working.
//
// Element contract:
//   root [data-part="window"] — carries the hook; must be positioned (absolute/fixed); data-x/data-y
//   [data-part="handle"]      — the drag handle (defaults to the whole window if omitted)

const INTERACTIVE = "button, a, input, textarea, select, [data-no-drag]";

const FloatingWindow = {
  mounted() {
    this.x = parseFloat(this.el.getAttribute("data-x")) || 0;
    this.y = parseFloat(this.el.getAttribute("data-y")) || 0;
    this.on = this.el.getAttribute("data-on-move");
    this.handle = this.el.querySelector('[data-part="handle"]') || this.el;
    this.handle.style.touchAction = "none";
    this.apply();

    this._onDown = (e) => {
      if (e.button !== 0) return;
      if (e.target.closest(INTERACTIVE)) return;
      e.preventDefault();
      this.startX = e.clientX;
      this.startY = e.clientY;
      this.origX = this.x;
      this.origY = this.y;
      this.dragging = true;
      this.el.setAttribute("data-dragging", "");
      try {
        this.handle.setPointerCapture(e.pointerId);
      } catch (_e) {}
      window.addEventListener("pointermove", this._onMove);
      window.addEventListener("pointerup", this._onUp);
    };
    this._onMove = (e) => {
      if (!this.dragging) return;
      this.x = this.origX + (e.clientX - this.startX);
      this.y = this.origY + (e.clientY - this.startY);
      this.clamp();
      this.apply();
    };
    this._onUp = () => {
      if (!this.dragging) return;
      this.dragging = false;
      this.el.removeAttribute("data-dragging");
      window.removeEventListener("pointermove", this._onMove);
      window.removeEventListener("pointerup", this._onUp);
      if (this.on) this.pushEventTo(this.el, this.on, { x: Math.round(this.x), y: Math.round(this.y) });
    };

    this._onKey = (e) => {
      const step = e.shiftKey ? 1 : 10;
      let dx = 0;
      let dy = 0;
      if (e.key === "ArrowLeft") dx = -step;
      else if (e.key === "ArrowRight") dx = step;
      else if (e.key === "ArrowUp") dy = -step;
      else if (e.key === "ArrowDown") dy = step;
      else return;
      e.preventDefault();
      this.x += dx;
      this.y += dy;
      this.clamp();
      this.apply();
      if (this.on) this.pushEventTo(this.el, this.on, { x: Math.round(this.x), y: Math.round(this.y) });
    };

    this.handle.addEventListener("pointerdown", this._onDown);
    this.handle.addEventListener("keydown", this._onKey);
  },

  parent() {
    return this.el.offsetParent || this.el.parentElement;
  },

  clamp() {
    const p = this.parent();
    if (!p) return;
    const maxX = Math.max(0, p.clientWidth - this.el.offsetWidth);
    const maxY = Math.max(0, p.clientHeight - this.el.offsetHeight);
    this.x = Math.min(Math.max(0, this.x), maxX);
    this.y = Math.min(Math.max(0, this.y), maxY);
  },

  apply() {
    this.el.style.left = `${this.x}px`;
    this.el.style.top = `${this.y}px`;
    this.el.setAttribute("data-x", String(Math.round(this.x)));
    this.el.setAttribute("data-y", String(Math.round(this.y)));
  },

  updated() {
    if (this.dragging) return;
    this.x = parseFloat(this.el.getAttribute("data-x")) || 0;
    this.y = parseFloat(this.el.getAttribute("data-y")) || 0;
    this.apply();
  },

  destroyed() {
    this.handle.removeEventListener("pointerdown", this._onDown);
    this.handle.removeEventListener("keydown", this._onKey);
    window.removeEventListener("pointermove", this._onMove);
    window.removeEventListener("pointerup", this._onUp);
  },
};

export default FloatingWindow;

// Avatar — image loading-status engine (Base UI parity).
//
// Tracks the `[data-part="image"]`'s loading status — `idle | loading | loaded | error` — on the root
// as `data-status`, and shows the right child: the image is revealed ONLY once it has loaded, and the
// `[data-part="fallback"]` (initials) shows whenever the image isn't loaded. A `data-delay` (ms) on
// the fallback makes it wait that long before appearing, so a fast-loading image never flashes the
// fallback. `data-on-loading-status-change` pushes `{status}` to LiveView on every change.
//
// The image is toggled via the `hidden` attribute; the fallback via inline `display` (so it still
// hides even when the consumer styles it `display:flex`).

const Avatar = {
  mounted() {
    const el = this.el;
    this.image = el.querySelector('[data-part="image"]');
    this.fallback = el.querySelector('[data-part="fallback"]');
    this.onChange = el.getAttribute("data-on-loading-status-change");

    const d = this.fallback && this.fallback.getAttribute("data-delay");
    this.delay = d ? parseInt(d, 10) : undefined;
    this.delayPassed = !this.delay;

    const src = this.image && this.image.getAttribute("src");
    if (!src) {
      this.set("idle");
    } else if (this.image.complete) {
      // already settled (e.g. cached) — naturalWidth is 0 on a broken image
      this.set(this.image.naturalWidth > 0 ? "loaded" : "error");
    } else {
      this.set("loading");
      this._onLoad = () => this.set(this.image.naturalWidth > 0 ? "loaded" : "error");
      this._onError = () => this.set("error");
      this.image.addEventListener("load", this._onLoad);
      this.image.addEventListener("error", this._onError);
    }

    if (!this.delayPassed && this.status !== "loaded") {
      this._timer = setTimeout(() => {
        this.delayPassed = true;
        this.apply();
      }, this.delay);
    }
    this.apply();
  },

  destroyed() {
    if (this._timer) clearTimeout(this._timer);
    if (this.image && this._onLoad) {
      this.image.removeEventListener("load", this._onLoad);
      this.image.removeEventListener("error", this._onError);
    }
  },

  set(status) {
    if (this.status === status) return;
    this.status = status;
    this.el.setAttribute("data-status", status);
    if (this.onChange) this.pushEventTo(this.el, this.onChange, { status });
    this.apply();
  },

  apply() {
    const loaded = this.status === "loaded";
    if (this.image) this.image.hidden = !loaded;
    // fallback shows when the image isn't loaded AND the (optional) delay has elapsed
    if (this.fallback) {
      this.fallback.style.display = !loaded && this.delayPassed ? "" : "none";
    }
  },
};

export default Avatar;

// Menu — headless menu-button engine (Base UI parity).
//
// A `[data-part="trigger"]` button opens a `[data-part="popup"]` menu anchored to it
// (side/align/offset, with edge-flip + clamp), optionally on hover. Full menu semantics:
// roving highlight + typeahead, Enter/Space activation, checkbox/radio item state, nested
// submenus (hover + ArrowRight / ArrowLeft), Escape + outside-press dismissal, focus
// management. Motion and color are 100% CSS — the hook toggles data-* state and positions.
//
// Parts (data-part): trigger, popup, submenu, submenu-trigger, submenu-popup, item,
// checkbox-item, radio-item, link-item, separator. Highlightable rows:
// item | checkbox-item | radio-item | link-item | submenu-trigger.

const HIGHLIGHTABLE =
  '[data-part="item"],[data-part="checkbox-item"],[data-part="radio-item"],[data-part="link-item"],[data-part="submenu-trigger"]';
const MENU = '[data-part="popup"],[data-part="submenu-popup"]';
const PAD = 8;

const Menu = {
  mounted() {
    this.trigger = this.el.querySelector('[data-part="trigger"]');
    this.popup = this.el.querySelector('[data-part="popup"]');
    this.disabled = this.el.getAttribute("data-disabled") === "true";
    this.side = this.el.getAttribute("data-side") || "bottom";
    this.align = this.el.getAttribute("data-align") || "start";
    this.sideOffset = parseFloat(this.el.getAttribute("data-side-offset")) || 0;
    this.alignOffset = parseFloat(this.el.getAttribute("data-align-offset")) || 0;
    this.openOnHover = this.el.getAttribute("data-open-on-hover") === "true";
    this.delay = parseFloat(this.el.getAttribute("data-delay"));
    this.closeDelay = parseFloat(this.el.getAttribute("data-close-delay"));
    if (Number.isNaN(this.delay)) this.delay = 100;
    if (Number.isNaN(this.closeDelay)) this.closeDelay = 0;
    this.loop = this.el.getAttribute("data-loop") !== "false";
    this.onOpenChange = this.el.getAttribute("data-on-open-change");
    this.onOpenChangeTarget = this.el.getAttribute("data-on-open-change-target");

    this.stack = [];
    this.typeahead = "";
    this.typeaheadAt = 0;
    this.submenuTimers = new Map();

    this.boundKeydown = (e) => this.handleKeydown(e);
    this.boundOutside = (e) => this.handleOutside(e);
    this.boundReposition = () => this.reposition();

    if (this.trigger && this.popup && this.popup.id) {
      this.trigger.setAttribute("aria-haspopup", "menu");
      this.trigger.setAttribute("aria-controls", this.popup.id);
      this.trigger.setAttribute("aria-expanded", "false");
      this.trigger.addEventListener("click", () => {
        if (this.disabled || this.trigger.hasAttribute("data-disabled")) return;
        this.isOpen() ? this.closeAll() : this.open();
      });
      this.trigger.addEventListener("keydown", (e) => this.onTriggerKeydown(e));
      if (this.openOnHover) {
        this.trigger.addEventListener("pointerenter", () => this.scheduleHoverOpen());
        this.trigger.addEventListener("pointerleave", () => this.scheduleHoverClose());
      }
    }

    this.el.addEventListener("click", (e) => this.onRowClick(e));
    this.el.addEventListener("pointermove", (e) => this.onRowHover(e));
    if (this.openOnHover && this.popup) {
      this.popup.addEventListener("pointerenter", () => this.cancelHoverClose());
      this.popup.addEventListener("pointerleave", () => this.scheduleHoverClose());
    }
  },

  destroyed() {
    this.teardownOpenListeners();
    if (this.hoverTimer) clearTimeout(this.hoverTimer);
  },

  isOpen() {
    return this.stack.length > 0;
  },

  // ---- open / close ------------------------------------------------------
  open() {
    if (this.isOpen()) return;
    this.opener = document.activeElement;
    this.positionPopup(this.popup, this.trigger.getBoundingClientRect(), this.side, this.align, this.sideOffset, this.alignOffset);
    this.openMenu(this.popup);
    this.trigger.setAttribute("aria-expanded", "true");
    this.trigger.toggleAttribute("data-popup-open", true);
    this.trigger.toggleAttribute("data-pressed", true);
    document.addEventListener("keydown", this.boundKeydown, true);
    window.addEventListener("scroll", this.boundReposition, true);
    window.addEventListener("resize", this.boundReposition);
    this.allowOutside = false;
    setTimeout(() => {
      this.allowOutside = true;
      document.addEventListener("pointerdown", this.boundOutside, true);
    }, 60);
    this.emitOpenChange(true);
    requestAnimationFrame(() => this.popup.focus({ preventScroll: true }));
  },

  closeAll(restoreFocus = true) {
    [...this.stack].reverse().forEach((m) => this.closeMenu(m));
    this.stack = [];
    if (this.trigger) {
      this.trigger.setAttribute("aria-expanded", "false");
      this.trigger.toggleAttribute("data-popup-open", false);
      this.trigger.toggleAttribute("data-pressed", false);
    }
    this.teardownOpenListeners();
    this.emitOpenChange(false);
    if (restoreFocus && this.trigger) this.trigger.focus({ preventScroll: true });
  },

  teardownOpenListeners() {
    document.removeEventListener("keydown", this.boundKeydown, true);
    document.removeEventListener("pointerdown", this.boundOutside, true);
    window.removeEventListener("scroll", this.boundReposition, true);
    window.removeEventListener("resize", this.boundReposition);
    this.submenuTimers.forEach((t) => clearTimeout(t));
    this.submenuTimers.clear();
  },

  reposition() {
    if (!this.isOpen()) return;
    this.positionPopup(this.popup, this.trigger.getBoundingClientRect(), this.side, this.align, this.sideOffset, this.alignOffset);
    // reposition open submenus against their triggers
    this.stack.slice(1).forEach((p) => {
      const sub = p.closest('[data-part="submenu"]');
      const t = sub && sub.querySelector('[data-part="submenu-trigger"]');
      if (t) this.positionPopup(p, t.getBoundingClientRect(), "right", "start", 0, 0);
    });
  },

  openMenu(menu) {
    menu.hidden = false;
    menu.toggleAttribute("data-open", true);
    menu.removeAttribute("data-closed");
    menu.setAttribute("data-starting-style", "");
    requestAnimationFrame(() =>
      requestAnimationFrame(() => menu && menu.removeAttribute("data-starting-style")),
    );
    if (this.stack.indexOf(menu) === -1) this.stack.push(menu);
    this.setHighlight(menu, null);
  },

  closeMenu(menu) {
    menu.toggleAttribute("data-open", false);
    menu.setAttribute("data-closed", "");
    menu.hidden = true;
    const i = this.stack.indexOf(menu);
    if (i >= 0) this.stack.splice(i, 1);
    const sub = menu.closest('[data-part="submenu"]');
    if (sub) {
      const t = sub.querySelector('[data-part="submenu-trigger"]');
      if (t) {
        t.setAttribute("aria-expanded", "false");
        t.toggleAttribute("data-popup-open", false);
      }
    }
  },

  emitOpenChange(open) {
    if (!this.onOpenChange) return;
    if (this.onOpenChangeTarget) this.pushEventTo(this.onOpenChangeTarget, this.onOpenChange, { open });
    else this.pushEventTo(this.el, this.onOpenChange, { open });
  },

  // ---- anchored positioning (fixed; flip on the main axis + clamp) --------
  positionPopup(popup, anchor, side, align, sideOffset, alignOffset) {
    popup.style.position = "fixed";
    popup.style.left = "0px";
    popup.style.top = "0px";
    popup.style.visibility = "hidden";
    popup.hidden = false;
    popup.removeAttribute("data-closed");
    const p = popup.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    let resolved = side;

    // flip on the main axis if it would overflow
    if (side === "bottom" && anchor.bottom + sideOffset + p.height > vh - PAD && anchor.top - sideOffset - p.height > PAD) resolved = "top";
    else if (side === "top" && anchor.top - sideOffset - p.height < PAD && anchor.bottom + sideOffset + p.height < vh - PAD) resolved = "bottom";
    else if (side === "right" && anchor.right + sideOffset + p.width > vw - PAD && anchor.left - sideOffset - p.width > PAD) resolved = "left";
    else if (side === "left" && anchor.left - sideOffset - p.width < PAD && anchor.right + sideOffset + p.width < vw - PAD) resolved = "right";

    let left;
    let top;
    if (resolved === "bottom" || resolved === "top") {
      top = resolved === "bottom" ? anchor.bottom + sideOffset : anchor.top - p.height - sideOffset;
      if (align === "start") left = anchor.left + alignOffset;
      else if (align === "end") left = anchor.right - p.width - alignOffset;
      else left = anchor.left + (anchor.width - p.width) / 2 + alignOffset;
    } else {
      left = resolved === "right" ? anchor.right + sideOffset : anchor.left - p.width - sideOffset;
      if (align === "start") top = anchor.top + alignOffset;
      else if (align === "end") top = anchor.bottom - p.height - alignOffset;
      else top = anchor.top + (anchor.height - p.height) / 2 + alignOffset;
    }

    left = Math.min(Math.max(left, PAD), Math.max(PAD, vw - p.width - PAD));
    top = Math.min(Math.max(top, PAD), Math.max(PAD, vh - p.height - PAD));
    popup.style.left = `${left}px`;
    popup.style.top = `${top}px`;
    popup.setAttribute("data-side", resolved);
    popup.setAttribute("data-align", align);
    popup.style.visibility = "";
  },

  // ---- hover open/close ---------------------------------------------------
  scheduleHoverOpen() {
    this.cancelHoverClose();
    if (this.isOpen()) return;
    this.hoverTimer = setTimeout(() => this.open(), this.delay);
  },

  scheduleHoverClose() {
    if (this.hoverTimer) clearTimeout(this.hoverTimer);
    this.hoverTimer = setTimeout(() => this.closeAll(false), this.closeDelay);
  },

  cancelHoverClose() {
    if (this.hoverTimer) clearTimeout(this.hoverTimer);
    this.hoverTimer = null;
  },

  handleOutside(e) {
    if (!this.allowOutside) return;
    if (this.stack.some((m) => m.contains(e.target))) return;
    if (this.trigger && this.trigger.contains(e.target)) return;
    this.closeAll(false);
  },

  // ---- rows: hover / click -----------------------------------------------
  itemsOf(menu) {
    return Array.from(menu.querySelectorAll(HIGHLIGHTABLE)).filter(
      (el) => el.closest(MENU) === menu && !el.hasAttribute("data-disabled"),
    );
  },

  activeMenu() {
    return this.stack[this.stack.length - 1] || null;
  },

  setHighlight(menu, el) {
    this.itemsOf(menu).forEach((it) => {
      const on = it === el;
      it.toggleAttribute("data-highlighted", on);
      it.tabIndex = on ? 0 : -1;
    });
    if (el && el.focus) el.focus({ preventScroll: true });
  },

  onRowHover(e) {
    const row = e.target.closest(HIGHLIGHTABLE);
    if (!row) return;
    const menu = row.closest(MENU);
    if (!menu || this.stack.indexOf(menu) === -1) return;
    if (row.hasAttribute("data-disabled")) return;
    if (this.activeMenu() === menu) this.setHighlight(menu, row);
    if (row.getAttribute("data-part") === "submenu-trigger") this.scheduleSubmenuOpen(row);
    else this.closeSiblingSubmenus(menu, null);
  },

  scheduleSubmenuOpen(trigger) {
    const sub = trigger.closest('[data-part="submenu"]');
    const popup = sub && sub.querySelector('[data-part="submenu-popup"]');
    if (!popup || this.stack.indexOf(popup) !== -1) return;
    const parentMenu = trigger.closest(MENU);
    this.closeSiblingSubmenus(parentMenu, sub);
    if (this.submenuTimers.has(trigger)) return;
    const t = setTimeout(() => {
      this.submenuTimers.delete(trigger);
      this.openSubmenu(trigger);
    }, 100);
    this.submenuTimers.set(trigger, t);
  },

  closeSiblingSubmenus(parentMenu, keepSub) {
    parentMenu.querySelectorAll('[data-part="submenu"]').forEach((s) => {
      if (s === keepSub || s.closest(MENU) !== parentMenu) return;
      const p = s.querySelector('[data-part="submenu-popup"]');
      if (p && this.stack.indexOf(p) !== -1) this.closeMenu(p);
    });
  },

  openSubmenu(trigger) {
    const sub = trigger.closest('[data-part="submenu"]');
    const popup = sub && sub.querySelector('[data-part="submenu-popup"]');
    if (!popup || this.stack.indexOf(popup) !== -1) return null;
    this.positionPopup(popup, trigger.getBoundingClientRect(), "right", "start", 0, 0);
    this.openMenu(popup);
    trigger.setAttribute("aria-expanded", "true");
    trigger.toggleAttribute("data-popup-open", true);
    return popup;
  },

  activateSubmenu(trigger, focusFirst) {
    const popup = this.openSubmenu(trigger);
    if (popup && focusFirst) {
      const first = this.itemsOf(popup)[0];
      if (first) this.setHighlight(popup, first);
      else popup.focus({ preventScroll: true });
    }
  },

  onRowClick(e) {
    const row = e.target.closest(HIGHLIGHTABLE);
    if (!row || row.hasAttribute("data-disabled")) return;
    const part = row.getAttribute("data-part");
    if (part === "submenu-trigger") {
      e.preventDefault();
      const sub = row.closest('[data-part="submenu"]');
      const p = sub && sub.querySelector('[data-part="submenu-popup"]');
      if (p && this.stack.indexOf(p) !== -1) this.closeMenu(p);
      else this.activateSubmenu(row, true);
      return;
    }
    if (part === "checkbox-item") return this.toggleCheckbox(row);
    if (part === "radio-item") return this.selectRadio(row);
    if (row.getAttribute("data-keep-open") !== "true") setTimeout(() => this.closeAll(), 0);
  },

  toggleCheckbox(item) {
    const checked = !item.hasAttribute("data-checked");
    item.toggleAttribute("data-checked", checked);
    item.toggleAttribute("data-unchecked", !checked);
    item.setAttribute("aria-checked", String(checked));
    const ind = item.querySelector('[data-part="checkbox-item-indicator"]');
    if (ind) {
      ind.toggleAttribute("data-checked", checked);
      ind.toggleAttribute("data-unchecked", !checked);
    }
    this.emitItemEvent(item, { checked });
  },

  selectRadio(item) {
    const name = item.getAttribute("data-radio-group");
    const menu = item.closest(MENU);
    let radios;
    if (name && menu) {
      radios = menu.querySelectorAll(`[data-part="radio-item"][data-radio-group="${name}"]`);
    } else {
      const group = item.closest('[data-part="radio-group"]');
      if (!group) return;
      radios = group.querySelectorAll('[data-part="radio-item"]');
    }
    radios.forEach((r) => {
      const on = r === item;
      r.toggleAttribute("data-checked", on);
      r.toggleAttribute("data-unchecked", !on);
      r.setAttribute("aria-checked", String(on));
      const ind = r.querySelector('[data-part="radio-item-indicator"]');
      if (ind) {
        ind.toggleAttribute("data-checked", on);
        ind.toggleAttribute("data-unchecked", !on);
      }
    });
    this.emitItemEvent(item, { value: item.getAttribute("data-value") });
  },

  emitItemEvent(item, payload) {
    const ev = item.getAttribute("data-on-change");
    if (!ev) return;
    const target = item.getAttribute("data-on-change-target");
    if (target) this.pushEventTo(target, ev, payload);
    else this.pushEventTo(this.el, ev, payload);
  },

  // ---- keyboard ----------------------------------------------------------
  onTriggerKeydown(e) {
    if (this.disabled) return;
    if (e.key === "ArrowDown" || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (!this.isOpen()) this.open();
      requestAnimationFrame(() => {
        const items = this.itemsOf(this.popup);
        if (items[0]) this.setHighlight(this.popup, items[0]);
      });
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      if (!this.isOpen()) this.open();
      requestAnimationFrame(() => {
        const items = this.itemsOf(this.popup);
        if (items.length) this.setHighlight(this.popup, items[items.length - 1]);
      });
    }
  },

  handleKeydown(e) {
    if (!this.isOpen()) return;
    const menu = this.activeMenu();
    const items = this.itemsOf(menu);
    const current = items.find((it) => it.hasAttribute("data-highlighted"));
    const idx = current ? items.indexOf(current) : -1;
    const last = items.length - 1;
    const next = (i) => (this.loop ? (i + 1) % items.length : Math.min(i + 1, last));
    const prev = (i) => (this.loop ? (i - 1 + items.length) % items.length : Math.max(i - 1, 0));

    switch (e.key) {
      case "Escape":
        e.preventDefault();
        if (this.stack.length > 1) {
          this.closeMenu(menu);
          const owner = menu.closest('[data-part="submenu"]')?.querySelector('[data-part="submenu-trigger"]');
          if (owner) this.setHighlight(this.activeMenu(), owner);
        } else {
          this.closeAll();
        }
        return;
      case "ArrowDown":
        e.preventDefault();
        this.setHighlight(menu, items[idx === -1 ? 0 : next(idx)]);
        return;
      case "ArrowUp":
        e.preventDefault();
        this.setHighlight(menu, items[idx === -1 ? last : prev(idx)]);
        return;
      case "Home":
        e.preventDefault();
        this.setHighlight(menu, items[0]);
        return;
      case "End":
        e.preventDefault();
        this.setHighlight(menu, items[last]);
        return;
      case "ArrowRight":
        if (current && current.getAttribute("data-part") === "submenu-trigger") {
          e.preventDefault();
          this.activateSubmenu(current, true);
        }
        return;
      case "ArrowLeft":
        if (this.stack.length > 1) {
          e.preventDefault();
          this.closeMenu(menu);
          const owner = menu.closest('[data-part="submenu"]')?.querySelector('[data-part="submenu-trigger"]');
          if (owner) this.setHighlight(this.activeMenu(), owner);
        }
        return;
      case "Enter":
      case " ":
        if (current) {
          e.preventDefault();
          current.click();
        }
        return;
      case "Tab":
        this.closeAll(false);
        return;
      default:
        if (e.key.length === 1 && !e.metaKey && !e.ctrlKey && !e.altKey) this.onType(menu, items, e.key);
    }
  },

  onType(menu, items, ch) {
    this.typeahead = (performance.now() - this.typeaheadAt > 700 ? "" : this.typeahead) + ch.toLowerCase();
    this.typeaheadAt = performance.now();
    const match = items.find((it) =>
      (it.getAttribute("data-label") || it.textContent || "").trim().toLowerCase().startsWith(this.typeahead),
    );
    if (match) this.setHighlight(menu, match);
  },
};

export default Menu;

// ToggleGroup — coordinated group of toggle buttons (Base UI parity).
//
// One hook on the root `role="group"` owns everything: roving tabindex (arrow keys along the
// orientation + Home/End, looping when `data-loop`), and the pressed state of every
// `[data-part="item"]`. `data-multiple` allows several pressed at once (toggle in/out); without it the
// group is single-select — pressing an item presses ONLY it, and pressing the already-pressed item
// deselects it (the group may be empty), matching Base UI. Each item reflects `aria-pressed` +
// `data-pressed`; the pressed values mirror into hidden inputs under `[data-part="value-inputs"]`
// (single → `name`, multiple → `name[]`) with a bubbling `input` (so `<.form>` reacts), and
// `data-on-change` pushes `{value: [...]}` to LiveView.

const ToggleGroup = {
  mounted() {
    const el = this.el;
    this.multiple = el.hasAttribute("data-multiple");
    this.disabled = el.hasAttribute("data-disabled");
    this.vertical = el.getAttribute("data-orientation") === "vertical";
    this.loop = el.hasAttribute("data-loop");
    this.name = el.getAttribute("data-name");
    this.onChange = el.getAttribute("data-on-change");
    this.inputs = el.querySelector('[data-part="value-inputs"]');

    this.pressed = new Set(
      this.items().filter((i) => i.hasAttribute("data-pressed")).map((i) => this.val(i))
    );

    this.bindItems();
    this.boundKey = (e) => this.onKey(e);
    el.addEventListener("keydown", this.boundKey);
    this.roll();
  },

  updated() {
    // A server re-render (e.g. form submit/reset) re-renders the items from @value; re-read the
    // pressed set from the server, re-bind any new items, and restore the roving tabindex.
    this.pressed = new Set(
      this.items().filter((i) => i.getAttribute("aria-pressed") === "true").map((i) => this.val(i))
    );
    this.bindItems();
    this.roll();
  },

  destroyed() {
    this.el.removeEventListener("keydown", this.boundKey);
  },

  items() {
    return Array.from(this.el.querySelectorAll('[data-part="item"]'));
  },

  enabledItems() {
    return this.items().filter((i) => !i.hasAttribute("data-disabled"));
  },

  val(item) {
    return item.getAttribute("data-value");
  },

  bindItems() {
    this.items().forEach((item) => {
      if (item._tgBound) return;
      item._tgBound = true;
      item.addEventListener("click", () => this.commit(item));
    });
  },

  // ---- press logic ----------------------------------------------------------

  commit(item) {
    if (this.disabled || item.hasAttribute("data-disabled")) return;
    const v = this.val(item);
    const nextPressed = !this.pressed.has(v);

    if (this.multiple) {
      if (nextPressed) this.pressed.add(v);
      else this.pressed.delete(v);
    } else {
      // single: press → only this; press the pressed one → empty (Base UI deselect).
      this.pressed = nextPressed ? new Set([v]) : new Set();
    }

    this.render();
    this.focusItem(item);
    if (this.onChange) this.pushEventTo(this.el, this.onChange, { value: Array.from(this.pressed) });
  },

  render() {
    this.items().forEach((item) => {
      const on = this.pressed.has(this.val(item));
      item.setAttribute("aria-pressed", String(on));
      item.toggleAttribute("data-pressed", on);
    });
    this.roll();
    this.syncInputs();
  },

  // Mirror the pressed values into the hidden form input(s) and notify any enclosing <.form>.
  syncInputs() {
    if (!this.inputs || !this.name) return;
    const name = this.multiple ? `${this.name}[]` : this.name;
    const vals = Array.from(this.pressed);
    const html = (this.multiple ? vals : vals.slice(0, 1))
      .map((v) => `<input type="hidden" name="${name}" value="${this.escape(v)}">`)
      .join("");
    // single with no selection still submits an empty field (so the param is present)
    this.inputs.innerHTML =
      html || (this.multiple ? "" : `<input type="hidden" name="${name}" value="">`);
    this.inputs.dispatchEvent(new Event("input", { bubbles: true }));
  },

  // ---- roving tabindex / keyboard -------------------------------------------

  // The tabbable item is the first pressed-and-enabled one, else the first enabled one.
  roll() {
    const items = this.items();
    const tabbable =
      items.find((i) => i.hasAttribute("data-pressed") && !i.hasAttribute("data-disabled")) ||
      this.enabledItems()[0];
    items.forEach((i) => i.setAttribute("tabindex", i === tabbable ? "0" : "-1"));
  },

  focusItem(item) {
    this.items().forEach((i) => i.setAttribute("tabindex", i === item ? "0" : "-1"));
    item.focus();
  },

  onKey(e) {
    if (this.disabled) return;
    const items = this.enabledItems();
    const idx = items.indexOf(e.target.closest('[data-part="item"]'));
    if (idx < 0) return;
    const next = this.vertical ? "ArrowDown" : "ArrowRight";
    const prev = this.vertical ? "ArrowUp" : "ArrowLeft";
    let target = null;
    if (e.key === next) {
      target = items[this.loop ? (idx + 1) % items.length : Math.min(items.length - 1, idx + 1)];
    } else if (e.key === prev) {
      target = items[this.loop ? (idx - 1 + items.length) % items.length : Math.max(0, idx - 1)];
    } else if (e.key === "Home") {
      target = items[0];
    } else if (e.key === "End") {
      target = items[items.length - 1];
    } else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      this.commit(items[idx]);
      return;
    } else {
      return;
    }
    e.preventDefault();
    if (target) this.focusItem(target);
  },

  escape(s) {
    return String(s).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
  },
};

export default ToggleGroup;

// OverflowList — show as many items as fit on one row and collapse the rest into a "+N" counter.
//
// A `ResizeObserver` re-runs the layout when the container's width changes. Items that don't fit
// get `data-hidden` + `inert` (hide them with CSS; inert already removes them from the tab order
// and the accessibility tree, so fading them out is safe); the counter element is revealed and its
// `[data-part="counter-value"]` is set to the number hidden. At least `data-min-visible` items are
// always kept. If `data-on-change` names an event, the hidden count is pushed (debounced, so a
// drag-resize doesn't flood the server) when it changes.
//
// Why the hook applies state through `this.js()` and not plain setAttribute: attributes written
// via the JS-command engine are sticky — LiveView re-applies them after every DOM patch — so a
// server round-trip can never strip the hidden state and re-reveal the row mid-drag.
//
// Measuring happens once per content change (mount, changed items after a patch, font load),
// never on the resize path: natural widths are cached as fractions (getBoundingClientRect, not
// the rounded offsetWidth) and the counter is measured at its widest possible text ("+<total>"),
// so the layout decision can never feed back through its own output.
//
// Element contract:
//   root                          — carries the hook; data-min-visible, data-on-change
//   [data-part="item"]            — each list item (order = priority)
//   [data-part="counter"]         — the "+N" element (gets data-hidden when nothing overflows)
//   [data-part="counter-value"]   — optional; receives the hidden count as text

// How many items fit on one row of `avail` width, always reserving room for the counter when
// anything overflows. Pure — exercised directly by overflow_list.test.mjs.
export function fit({ widths, counterW, gap, avail, min }) {
  const n = widths.length;

  let sumAll = 0;
  widths.forEach((w, i) => (sumAll += w + (i ? gap : 0)));
  if (sumAll <= avail) return n;

  const reserve = counterW > 0 ? gap + counterW : 0;
  let used = 0;
  let visible = 0;
  for (let i = 0; i < n; i++) {
    const next = used + (visible ? gap : 0) + widths[i];
    if (next + reserve > avail) break;
    used = next;
    visible++;
  }

  return Math.max(Math.min(min, n), visible);
}

const OverflowList = {
  mounted() {
    this.min = parseInt(this.el.getAttribute("data-min-visible") || "1", 10);
    this.on = this.el.getAttribute("data-on-change");
    this.counter = this.el.querySelector('[data-part="counter"]');
    this.counterValue = this.el.querySelector('[data-part="counter-value"]');

    this.refresh();

    this._ro = new ResizeObserver(() => {
      if (this.el.clientWidth !== this._lastWidth) this.layout();
    });
    this._ro.observe(this.el);

    if (document.fonts && document.fonts.status !== "loaded") {
      document.fonts.ready.then(() => {
        if (!this._destroyed) this.refresh();
      });
    }
  },

  items() {
    return Array.from(this.el.querySelectorAll('[data-part="item"]'));
  },

  gap() {
    const s = getComputedStyle(this.el);
    return parseFloat(s.columnGap || s.gap || "0") || 0;
  },

  avail() {
    const s = getComputedStyle(this.el);
    return (
      this.el.clientWidth -
      (parseFloat(s.paddingLeft) || 0) -
      (parseFloat(s.paddingRight) || 0)
    );
  },

  signature() {
    return this.items()
      .map((it) => it.textContent)
      .join("\u0001");
  },

  refresh() {
    this._sig = this.signature();
    this.measure();
    this.layout();
  },

  // Reveal everything (synchronously — nothing paints mid-function) and cache natural widths,
  // with the counter at its widest text. Must be followed by layout(), which applies real state.
  measure() {
    const items = this.items();
    items.forEach((it) => {
      it.removeAttribute("data-hidden");
      it.removeAttribute("inert");
    });
    if (this.counter) {
      this.counter.removeAttribute("data-hidden");
      if (this.counterValue) this.counterValue.textContent = String(items.length);
    }
    this._widths = items.map((it) => it.getBoundingClientRect().width);
    const counterW = this.counter ? this.counter.getBoundingClientRect().width : 0;
    this._counterW = counterW > 0 ? counterW : this._counterW || 0;
  },

  layout() {
    const items = this.items();
    if (!items.length) return;
    this._lastWidth = this.el.clientWidth;
    const js = this.js();

    const visible = fit({
      widths: this._widths || [],
      counterW: this._counterW || 0,
      gap: this.gap(),
      avail: this.avail(),
      min: this.min,
    });

    const hidden = items.length - visible;
    items.forEach((it, i) => {
      if (i < visible) {
        js.removeAttribute(it, "data-hidden");
        js.removeAttribute(it, "inert");
      } else {
        js.setAttribute(it, "data-hidden", "");
        js.setAttribute(it, "inert", "");
      }
    });

    if (this.counter) {
      if (hidden > 0) js.removeAttribute(this.counter, "data-hidden");
      else js.setAttribute(this.counter, "data-hidden", "");
    }
    if (this.counterValue) this.counterValue.textContent = String(hidden);
    this.report(hidden);
  },

  report(hidden) {
    if (this._last === hidden) return;
    this._last = hidden;
    if (!this.on) return;
    clearTimeout(this._reportTimer);
    this._reportTimer = setTimeout(() => {
      if (!this._destroyed) this.pushEventTo(this.el, this.on, { hidden: this._last });
    }, 120);
  },

  updated() {
    // Sticky attributes already survived the patch; only the counter text (server renders "0")
    // needs restoring — and a full re-measure only when the items themselves changed.
    if (this.counterValue) this.counterValue.textContent = String(this._last || 0);
    if (this.signature() !== this._sig) this.refresh();
  },

  destroyed() {
    this._destroyed = true;
    clearTimeout(this._reportTimer);
    if (this._ro) this._ro.disconnect();
  },
};

export default OverflowList;

// RadioGroup — headless single-select radio group (Base UI parity).
//
// Roving-tabindex composite of `[data-part="item"]` `<button role="radio">`s with selection that
// FOLLOWS FOCUS (APG radio pattern): Arrow Down/Right → next, Arrow Up/Left → previous (wrapping),
// Home/End → first/last; focusing or clicking an item selects it. On selection the hook updates every
// item's `aria-checked` + `data-checked`/`data-unchecked` (mutually exclusive) + roving `tabindex`,
// writes the chosen `data-value` into the group's hidden `<input>` and dispatches a bubbling `input`
// event (so an enclosing `<.form phx-change>` reacts), and pushes `data-on-change` (`{value}`) to
// LiveView when set. `data-disabled` (group) blocks everything; `aria-readonly` blocks changing the
// selection (focus still moves); disabled items (`data-disabled`) are skipped.

const RadioGroup = {
  mounted() {
    this.hidden = this.el.querySelector('input[type="hidden"]');
    this.onChange = this.el.getAttribute("data-on-change");
    this.vertical = this.el.getAttribute("data-orientation") !== "horizontal";
    this.boundKeydown = (e) => this.onKey(e);
    this.el.addEventListener("keydown", this.boundKeydown);
    this.bindItems();
  },

  updated() {
    this.bindItems();
  },

  destroyed() {
    this.el.removeEventListener("keydown", this.boundKeydown);
  },

  disabledGroup() {
    return this.el.hasAttribute("data-disabled");
  },

  readonly() {
    return this.el.getAttribute("aria-readonly") === "true";
  },

  // All radio items, and the navigable subset (enabled only).
  allItems() {
    return Array.from(this.el.querySelectorAll('[data-part="item"]'));
  },

  items() {
    return this.allItems().filter((i) => !i.hasAttribute("data-disabled"));
  },

  bindItems() {
    this.allItems().forEach((item) => {
      if (item._rgBound) return;
      item._rgBound = true;
      item.addEventListener("click", () => this.select(item));
      item.addEventListener("focus", () => {
        this.allItems().forEach((i) => i.toggleAttribute("data-highlighted", i === item));
        if (!this.readonly() && !this.disabledGroup() && !item.hasAttribute("data-disabled")) {
          this.select(item);
        }
      });
      item.addEventListener("blur", () => item.removeAttribute("data-highlighted"));
    });
  },

  onKey(e) {
    if (this.disabledGroup()) return;
    const items = this.items();
    if (!items.length) return;
    const idx = items.indexOf(document.activeElement);

    let target = null;
    if (e.key === "ArrowDown" || e.key === "ArrowRight") {
      target = items[(Math.max(idx, 0) + 1) % items.length];
    } else if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
      target = items[(Math.max(idx, 0) - 1 + items.length) % items.length];
    } else if (e.key === "Home") {
      target = items[0];
    } else if (e.key === "End") {
      target = items[items.length - 1];
    } else if ((e.key === " " || e.key === "Enter") && idx >= 0) {
      e.preventDefault();
      this.select(items[idx]);
      return;
    } else {
      return;
    }

    e.preventDefault();
    if (target) {
      this.roll(target);
      target.focus(); // focus handler selects (unless readonly)
    }
  },

  roll(target) {
    this.allItems().forEach((i) => i.setAttribute("tabindex", i === target ? "0" : "-1"));
  },

  select(item) {
    if (this.disabledGroup() || this.readonly() || item.hasAttribute("data-disabled")) return;
    const value = item.getAttribute("data-value");

    this.allItems().forEach((i) => {
      const on = i === item;
      i.setAttribute("aria-checked", String(on));
      i.toggleAttribute("data-checked", on);
      i.toggleAttribute("data-unchecked", !on);
      i.setAttribute("tabindex", on ? "0" : "-1");
    });

    if (this.hidden && this.hidden.value !== value) {
      this.hidden.value = value;
      // Notify any enclosing <.form phx-change> — the hidden input is set programmatically.
      this.hidden.dispatchEvent(new Event("input", { bubbles: true }));
    }
    if (this.onChange) this.pushEventTo(this.el, this.onChange, { value });
  },
};

export default RadioGroup;

// Toggle — headless pressed/checked state engine (toggle, toggle_group item, switch, checkbox).
//
// Clicking (or Enter/Space on a button) flips the control's state. Which ARIA attribute is
// toggled depends on the element's role: `role="switch"`/`checkbox` → `aria-checked` (with
// `data-checked`/`data-unchecked`), otherwise `aria-pressed` (with `data-pressed`, present only
// when on — Base UI Toggle parity). A hidden input (if present, `[data-part="input"]`) is kept in
// sync for form submission.
//
// Checkbox opt-in extras (switch/toggle set none of these, so they no-op):
//   `data-readonly`     → toggling is blocked, but the control stays focusable
//   `aria-checked="mixed"` (indeterminate) → the next toggle resolves to checked, clearing mixed
//   `data-on-change="event"` → pushes the LiveView event `{checked}` on every toggle
//   a `[data-part="indicator"]` child mirrors `data-checked`/`data-unchecked`/`data-indeterminate`.

const Toggle = {
  mounted() {
    this.input = this.el.querySelector('[data-part="input"]');
    // Children that mirror the checked state for CSS: a checkbox `indicator` and/or a switch
    // `track`/`thumb` — so each part can be styled off its own `data-checked`/`data-unchecked`.
    this.mirrors = [
      this.el.querySelector('[data-part="indicator"]'),
      this.el.querySelector('[data-part="track"]'),
      this.el.querySelector('[data-part="thumb"]'),
    ].filter(Boolean);
    this.role = this.el.getAttribute("role");
    this.attr =
      this.role === "switch" || this.role === "checkbox" ? "aria-checked" : "aria-pressed";

    // Reflect an initial indeterminate state onto the native input (HTML has no such attribute).
    if (this.input && this.el.hasAttribute("data-indeterminate")) this.input.indeterminate = true;

    this.boundClick = this.toggle.bind(this);
    this.boundKey = (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        this.toggle();
      }
    };

    this.el.addEventListener("click", this.boundClick);
    this.el.addEventListener("keydown", this.boundKey);
  },

  destroyed() {
    this.el.removeEventListener("click", this.boundClick);
    this.el.removeEventListener("keydown", this.boundKey);
  },

  toggle() {
    if (this.el.hasAttribute("data-disabled") || this.el.hasAttribute("data-readonly")) return;

    // From an indeterminate (mixed) state the next toggle resolves to checked.
    const prev = this.el.getAttribute(this.attr) === "true";
    const on = this.el.getAttribute(this.attr) === "mixed" ? true : !prev;
    this.set(on);

    // Notify any enclosing <.form phx-change> — setting `.checked` programmatically doesn't fire it.
    if (this.input) this.input.dispatchEvent(new Event("change", { bubbles: true }));

    // Fire the server event only on a real change; read data-on-change live (survives re-renders).
    // Payload is semantic: {checked} for switch/checkbox, {pressed} for toggle buttons.
    const onChange = this.el.getAttribute("data-on-change");
    if (onChange && on !== prev) {
      this.pushEventTo(this.el, onChange, this.attr === "aria-checked" ? { checked: on } : { pressed: on });
    }

    // Notify any group coordinator (CheckboxGroup) — covers BOTH click and keyboard toggles.
    this.el.dispatchEvent(new CustomEvent("chelekom:toggle", { bubbles: true }));
  },

  // Set the resolved (non-mixed) state on the control, indicator and hidden input.
  set(on) {
    this.el.setAttribute(this.attr, String(on));
    this.el.removeAttribute("data-indeterminate");

    if (this.attr === "aria-checked") {
      this.el.toggleAttribute("data-checked", on);
      this.el.toggleAttribute("data-unchecked", !on);
    } else {
      // Pressed buttons (toggle / toggle_group item): Base UI exposes only `data-pressed` (present
      // when on, absent when off).
      this.el.toggleAttribute("data-pressed", on);
    }

    this.mirrors.forEach((m) => {
      m.toggleAttribute("data-checked", on);
      m.toggleAttribute("data-unchecked", !on);
      m.removeAttribute("data-indeterminate");
    });

    if (this.input) {
      this.input.checked = on;
      this.input.indeterminate = false;
    }
  },
};

export default Toggle;

// CheckboxGroup — coordinates a checkbox group/tree: tristate "select all" parents + group on_change.
//
// Put `phx-hook="CheckboxGroup"` on a wrapper containing child checkboxes (`[role="checkbox"]`) and,
// optionally, parent checkboxes (`[data-parent]`). A parent owns the checkboxes in the
// `[data-part="children"]` container that immediately follows it; that container may itself hold more
// parents, so groups NEST to any depth (e.g. a permissions tree). Each checkbox drives its own state
// via the `Toggle` hook; this hook only coordinates the group:
//   • toggling a parent checks/unchecks every (enabled) leaf in its subtree
//   • toggling any checkbox re-derives every parent bottom-up → checked (all direct children checked)
//     / unchecked (none) / mixed (some, or any child mixed)
//   • if the wrapper has `data-on-change`, pushes that event with the selected leaf values ({value:[...]})
//
// A parent with NO `[data-part="children"]` container is treated flat (its children are the wrapper's
// other checkboxes) — so a simple one-level "select all" works without any nesting markup.
//
// It listens for the bubbling `chelekom:toggle` event each checkbox's `Toggle` fires after it flips
// (so it works for BOTH click and keyboard). To sync a subtree it dispatches a real click on the
// leaves that must change.

const CheckboxGroup = {
  mounted() {
    this.onToggle = (e) => this.handle(e);
    this.el.addEventListener("chelekom:toggle", this.onToggle);
    this.deriveAll();
  },

  updated() {
    this.deriveAll();
  },

  destroyed() {
    this.el.removeEventListener("chelekom:toggle", this.onToggle);
  },

  isChecked(el) {
    return el.getAttribute("aria-checked") === "true";
  },

  isMixed(el) {
    return el.hasAttribute("data-indeterminate");
  },

  enabled(el) {
    return !el.hasAttribute("data-disabled") && !el.hasAttribute("data-readonly");
  },

  // The children container a parent owns (its next sibling [data-part="children"]), or null (flat).
  container(parent) {
    const n = parent.nextElementSibling;
    return n && n.matches('[data-part="children"]') ? n : null;
  },

  // A parent's DIRECT child checkboxes (not grandchildren nested in a deeper container).
  directChildren(parent) {
    const c = this.container(parent);
    const scope = c || this.el;
    return Array.from(scope.querySelectorAll('[role="checkbox"]')).filter(
      (cb) => cb !== parent && cb.closest('[data-part="children"]') === c,
    );
  },

  // Every leaf (non-parent) checkbox under a parent — the ones a "select all" actually toggles.
  leaves(parent) {
    const c = this.container(parent);
    const scope = c || this.el;
    return Array.from(scope.querySelectorAll('[role="checkbox"]')).filter(
      (cb) => cb !== parent && !cb.hasAttribute("data-parent"),
    );
  },

  // All parents, deepest first, so a parent re-derives only after its sub-parents have settled.
  parents() {
    return Array.from(this.el.querySelectorAll('[role="checkbox"][data-parent]')).sort(
      (a, b) => this.depth(b) - this.depth(a),
    );
  },

  depth(el) {
    let d = 0;
    let n = el.parentElement;
    while (n && n !== this.el) {
      if (n.matches('[data-part="children"]')) d += 1;
      n = n.parentElement;
    }
    return d;
  },

  handle(e) {
    if (this.syncing) return;
    const target = e.target.closest('[role="checkbox"]');
    if (!target || !this.el.contains(target)) return;

    if (target.hasAttribute("data-parent")) {
      // the parent's own Toggle has flipped it — mirror its new state onto every leaf in its subtree
      const want = this.isChecked(target);
      this.syncing = true;
      this.leaves(target).forEach((leaf) => {
        if (this.enabled(leaf) && this.isChecked(leaf) !== want) leaf.click();
      });
      this.syncing = false;
    }
    this.deriveAll();
    this.emit();
  },

  deriveAll() {
    this.parents().forEach((p) => this.derive(p));
  },

  // A parent reflects its TOGGLABLE direct children: all checked → checked · none → unchecked ·
  // otherwise (some checked, or any child itself mixed) → mixed.
  derive(parent) {
    const kids = this.directChildren(parent).filter((c) => this.enabled(c));
    let state;
    if (kids.length === 0 || kids.every((c) => !this.isChecked(c) && !this.isMixed(c)))
      state = "unchecked";
    else if (kids.every((c) => this.isChecked(c) && !this.isMixed(c))) state = "checked";
    else state = "mixed";
    this.setState(parent, state);
  },

  setState(el, state) {
    el.setAttribute("aria-checked", state === "mixed" ? "mixed" : String(state === "checked"));
    el.toggleAttribute("data-checked", state === "checked");
    el.toggleAttribute("data-unchecked", state === "unchecked");
    el.toggleAttribute("data-indeterminate", state === "mixed");

    const ind = el.querySelector('[data-part="indicator"]');
    if (ind) {
      ind.toggleAttribute("data-checked", state === "checked");
      ind.toggleAttribute("data-unchecked", state === "unchecked");
      ind.toggleAttribute("data-indeterminate", state === "mixed");
    }
    const input = el.querySelector('[data-part="input"]');
    if (input) {
      input.checked = state === "checked";
      input.indeterminate = state === "mixed";
    }
  },

  // Push the selected LEAF values to LiveView (parents carry no submittable value). The value comes
  // from the checkbox's `data-value` (always present, so on_change works even without a form name),
  // falling back to the hidden input's value.
  emit() {
    const onChange = this.el.getAttribute("data-on-change");
    if (!onChange) return;
    const value = Array.from(this.el.querySelectorAll('[role="checkbox"]'))
      .filter((c) => !c.hasAttribute("data-parent") && this.isChecked(c))
      .map((c) => {
        const v = c.getAttribute("data-value");
        if (v != null) return v;
        const input = c.querySelector('[data-part="input"]');
        return input ? input.value : null;
      })
      .filter((v) => v != null);
    this.pushEventTo(this.el, onChange, { value });
  },
};

export default CheckboxGroup;

// Tree — client engine for the headless `<.tree>` component.
//
// The server renders the complete nested `<ul role="tree">` / `<li role="treeitem">`
// structure; this hook owns every interaction Mantine's Tree exposes:
// expand/collapse, single & multiple selection, shift-range selection, cascading
// checkboxes (with indeterminate) or strict per-node checks, full WAI-ARIA keyboard
// navigation, drag & drop with before/after/inside drop zones, and async child
// loading driven by the server.
//
// The server renders expanded/selected/checked as INITIAL state only and publishes each as a
// `data-*-values` attribute; from mount on, the hook owns them and re-asserts them after every
// patch. Without that, morphdom strips the attributes the hook wrote (the server never rendered
// them) and the tree silently collapses and loses its selection on any unrelated re-render.

const SELECT = {
  root: "[data-tree-root]",
  item: "[role=treeitem]",
  label: "[data-part=label]",
  subtree: "[data-part=subtree]",
  checkbox: "[data-part=checkbox]",
  handle: "[data-part=drag-handle]",
  expandIcon: "[data-part=expand-icon]",
};

const bool = (el, name) => el.getAttribute(name) === "true";

export default {
  mounted() {
    this.anchor = null;
    this.loaded = new Set();
    this.loading = new Set();
    // Expanded / selected / checked are all hook-owned after mount: the
    // server renders them only as an INITIAL value, so a later patch would re-render each node
    // without them and morphdom would strip whatever the user had done. Each is published by the
    // server as one `data-*-values` attribute the hook diffs, so the server can still take
    // control back deliberately (a "collapse all" button) without clobbering the user by accident.
    this.expanded = new Set();
    this.selected = new Set();
    this.checked = new Set();
    this.published = {};
    this.readPublished();

    this.opts = {
      expandOnClick: bool(this.el, "data-expand-on-click"),
      expandOnSpace: bool(this.el, "data-expand-on-space"),
      checkOnSpace: bool(this.el, "data-check-on-space"),
      selectOnClick: bool(this.el, "data-select-on-click"),
      allowRangeSelection: bool(this.el, "data-allow-range-selection"),
      clearOnOutsideClick: bool(this.el, "data-clear-selection-on-outside-click"),
      checkStrictly: bool(this.el, "data-check-strictly"),
      withCheckboxes: bool(this.el, "data-with-checkboxes"),
      multiple: bool(this.el, "data-multiple"),
      draggable: bool(this.el, "data-draggable"),
      withDragHandle: bool(this.el, "data-with-drag-handle"),
    };

    this.onClick = this.handleClick.bind(this);
    this.onKeyDown = this.handleKeyDown.bind(this);
    this.onFocusOut = this.handleFocusOut.bind(this);
    this.onOutside = this.handleOutside.bind(this);

    this.el.addEventListener("click", this.onClick);
    this.el.addEventListener("keydown", this.onKeyDown);
    this.el.addEventListener("focusout", this.onFocusOut);

    if (this.opts.clearOnOutsideClick) {
      document.addEventListener("click", this.onOutside);
    }

    if (this.opts.draggable) this.bindDragAndDrop();

    this.handleEvent(`tree:${this.el.id}:children`, ({ value }) => {
      this.loading.delete(value);
      this.loaded.add(value);
      const item = this.node(value);
      item && item.removeAttribute("data-loading");
      this.syncAll();
    });

    this.syncAll();
    this.setRovingTabindex();
  },

  updated() {
    this.readPublished();
    this.syncAll();
    this.setRovingTabindex();
  },

  // Adopt a set only when the SERVER's published value changed — per-node `data-*` attributes
  // cannot tell us that, because when the server re-renders an unchanged value LiveView sends no
  // diff and the DOM still holds whatever the hook last wrote.
  readPublished() {
    [
      ["data-expanded-values", "expanded"],
      ["data-selected-values", "selected"],
      ["data-checked-values", "checked"],
    ].forEach(([attr, key]) => {
      const raw = this.el.getAttribute(attr);
      if (raw === this.published[attr]) return;

      this.published[attr] = raw;

      try {
        this[key] = new Set(JSON.parse(raw || "[]"));
      } catch (_e) {
        this[key] = new Set();
      }
    });
  },

  destroyed() {
    this.el.removeEventListener("click", this.onClick);
    this.el.removeEventListener("keydown", this.onKeyDown);
    this.el.removeEventListener("focusout", this.onFocusOut);
    document.removeEventListener("click", this.onOutside);
  },

  // ── queries ───────────────────────────────────────────────────────────────

  items() {
    return Array.from(this.el.querySelectorAll(SELECT.item));
  },

  // Only nodes whose every ancestor subtree is open — this is the sequence
  // ArrowUp/ArrowDown walks, and it must ignore anything inside a collapsed
  // subtree even when `keepMounted` leaves it in the DOM.
  visibleItems() {
    return this.items().filter((item) => {
      for (let el = item.parentElement; el && el !== this.el; el = el.parentElement) {
        if (el.matches(SELECT.subtree) && el.hidden) return false;
      }
      return true;
    });
  },

  node(value) {
    return this.el.querySelector(`${SELECT.item}[data-value="${CSS.escape(value)}"]`);
  },

  valueOf(item) {
    return item.getAttribute("data-value");
  },

  subtreeOf(item) {
    const sub = item.querySelector(SELECT.subtree);
    return sub && sub.closest(SELECT.item) === item ? sub : null;
  },

  childItems(item) {
    const sub = this.subtreeOf(item);
    if (!sub) return [];
    return Array.from(sub.children).filter((el) => el.matches(SELECT.item));
  },

  // Every leaf under `item` (or itself when it is a leaf). Cascading checks operate
  // on leaves only — a parent is "checked" iff all of its leaves are.
  leaves(item) {
    const kids = this.childItems(item);
    if (kids.length === 0) return [item];
    return kids.flatMap((kid) => this.leaves(kid));
  },

  isExpanded(item) {
    return item.getAttribute("data-expanded") === "true";
  },

  hasChildren(item) {
    return this.childItems(item).length > 0 || item.getAttribute("data-has-children") === "true";
  },

  // ── expand / collapse ─────────────────────────────────────────────────────

  setExpanded(item, expanded) {
    if (!this.hasChildren(item)) return;
    const value = this.valueOf(item);
    expanded ? this.expanded.add(value) : this.expanded.delete(value);
    this.applyExpanded(item, expanded);
    this.pushOpt(expanded ? "expand" : "collapse", { value });

    // Async children: ask the server once, on first expand.
    if (
      expanded &&
      item.getAttribute("data-has-children") === "true" &&
      this.childItems(item).length === 0 &&
      !this.loaded.has(value) &&
      !this.loading.has(value)
    ) {
      this.loading.add(value);
      item.setAttribute("data-loading", "true");
      this.pushOpt("load_children", { value });
    }
  },

  applyExpanded(item, expanded) {
    item.setAttribute("data-expanded", String(expanded));
    item.setAttribute("aria-expanded", String(expanded));
    const sub = this.subtreeOf(item);
    if (sub) sub.hidden = !expanded;
  },

  toggleExpanded(item) {
    this.setExpanded(item, !this.isExpanded(item));
  },

  // ── selection ─────────────────────────────────────────────────────────────

  selectedValues() {
    return Array.from(this.selected);
  },

  applySelection(values) {
    this.selected = new Set(values);
    this.paintSelection();
    this.pushOpt("select", { values: Array.from(this.selected) });
  },

  // Painting is separate from pushing so `syncAll` can restore the selection after a patch
  // without firing a spurious `select` event back at the server.
  paintSelection() {
    const set = this.selected;
    this.items().forEach((item) => {
      if (!this.selectable(item)) {
        item.removeAttribute("aria-selected");
        return;
      }
      const on = set.has(this.valueOf(item));
      item.setAttribute("aria-selected", String(on));
      if (on) {
        item.setAttribute("data-selected", "true");
      } else {
        item.removeAttribute("data-selected");
      }
      const label = this.labelOf(item);
      if (label) {
        on
          ? label.setAttribute("data-selected", "true")
          : label.removeAttribute("data-selected");
      }
    });
  },

  labelOf(item) {
    const label = item.querySelector(SELECT.label);
    return label && label.closest(SELECT.item) === item ? label : null;
  },

  select(item) {
    if (!this.selectable(item)) return;
    const value = this.valueOf(item);
    this.anchor = value;
    this.applySelection(
      this.opts.multiple ? [...new Set([...this.selectedValues(), value])] : [value]
    );
  },

  // Shift-click / shift-arrow selects the inclusive slice between the anchor and the
  // target, in the tree's flattened visible order — matching Mantine's getValuesRange.
  // Non-selectable nodes inside the range are skipped.
  selectRange(target) {
    const items = this.visibleItems();
    const order = items.map((i) => this.valueOf(i));
    const a = order.indexOf(this.anchor);
    const b = order.indexOf(this.valueOf(target));
    if (a === -1 || b === -1) return this.select(target);
    this.applySelection(
      items
        .slice(Math.min(a, b), Math.max(a, b) + 1)
        .filter((i) => this.selectable(i))
        .map((i) => this.valueOf(i))
    );
  },

  // ── checkboxes ────────────────────────────────────────────────────────────

  checkedValues() {
    return this.items()
      .filter((i) => i.getAttribute("data-checked") === "true")
      .map((i) => this.valueOf(i));
  },

  // Re-apply the hook's checked set after a patch, then let refreshAncestors derive the parents.
  paintChecked() {
    if (!this.opts.withCheckboxes) return;
    this.items().forEach((item) => this.markChecked(item, this.checked.has(this.valueOf(item))));
  },

  setChecked(item, checked) {
    if (this.opts.checkStrictly) {
      if (!this.disabled(item)) this.markChecked(item, checked);
    } else {
      // A disabled leaf must not ride along on a parent's cascade: the browser omits disabled
      // inputs from a form POST, so `on_check` would otherwise report a value the form never
      // sends — two sources of truth disagreeing about a node the UI paints as forbidden.
      this.leaves(item)
        .filter((leaf) => !this.disabled(leaf))
        .forEach((leaf) => this.markChecked(leaf, checked));

      this.refreshAncestors();
    }
    this.checked = new Set(this.checkedValues());
    this.pushOpt("check", { values: Array.from(this.checked) });
  },

  disabled(item) {
    return item.getAttribute("data-disabled") === "true";
  },

  selectable(item) {
    return item.getAttribute("data-selectable") !== "false";
  },

  markChecked(item, checked) {
    item.setAttribute("data-checked", String(checked));
    item.removeAttribute("data-indeterminate");
    const box = this.checkboxOf(item);
    if (box) {
      box.checked = checked;
      box.indeterminate = false;
      box.setAttribute("aria-checked", String(checked));
    }
  },

  checkboxOf(item) {
    const box = item.querySelector(SELECT.checkbox);
    return box && box.closest(SELECT.item) === item ? box : null;
  },

  // A parent is checked when every leaf under it is checked, indeterminate when only some are.
  // Skipped entirely without checkboxes: it is the expensive half of `syncAll` (a descendant
  // query per node, per patch) and it would otherwise write `data-checked` onto nodes the
  // server never rendered it on — which morphdom then strips on the next patch, leaving the
  // hook and the DOM fighting each other forever.
  refreshAncestors() {
    if (this.opts.checkStrictly || !this.opts.withCheckboxes) return;

    this.items().forEach((item) => {
      const kids = this.childItems(item);
      if (kids.length === 0) return;

      const leaves = this.leaves(item);
      const checked = leaves.filter((l) => l.getAttribute("data-checked") === "true").length;
      const all = checked === leaves.length;
      const some = checked > 0 && !all;

      item.setAttribute("data-checked", String(all));
      some
        ? item.setAttribute("data-indeterminate", "true")
        : item.removeAttribute("data-indeterminate");

      const box = this.checkboxOf(item);
      if (box) {
        box.checked = all;
        box.indeterminate = some;
        box.setAttribute("aria-checked", some ? "mixed" : String(all));
      }
    });
  },

  // ── events ────────────────────────────────────────────────────────────────

  handleClick(event) {
    const box = event.target.closest(SELECT.checkbox);
    if (box) {
      const item = box.closest(SELECT.item);
      // The native input has already flipped itself; drive state from its new value.
      this.setChecked(item, box.checked);
      // The box is tabindex=-1, so the tree item owns the tab stop — keep it in sync.
      this.focus(item);
      return;
    }

    const label = event.target.closest(SELECT.label);
    if (!label) return;

    const item = label.closest(SELECT.item);
    if (!item || item.getAttribute("data-disabled") === "true") return;

    // The expand icon toggles the branch and nothing else. Mantine runs expand AND select from
    // one click on the row, which makes `select_on_click` + `multiple` unusable on a tree with
    // folders: every navigation click silently joins the selection, and there is no way to
    // collapse a branch without selecting it. Giving the chevron its own target is what every
    // real file tree does, and it leaves the row click meaning exactly one thing.
    const icon = event.target.closest(SELECT.expandIcon);

    if (icon && icon.closest(SELECT.item) === item && this.hasChildren(item)) {
      event.stopPropagation();
      this.toggleExpanded(item);
      this.focus(item);
      return;
    }

    // A non-selectable node (a category header) treats the whole row like its chevron:
    // the click toggles the branch and can never join the selection.
    if (!this.selectable(item)) {
      if (this.hasChildren(item)) this.toggleExpanded(item);
      this.focus(item);
      return;
    }

    if (this.opts.allowRangeSelection && event.shiftKey && this.anchor) {
      event.preventDefault();
      this.selectRange(item);
      this.focus(item);
      return;
    }

    if (this.opts.expandOnClick) this.toggleExpanded(item);
    if (this.opts.selectOnClick) this.select(item);
    this.focus(item);
  },

  handleKeyDown(event) {
    const item = event.target.closest(SELECT.item);
    if (!item || !this.el.contains(item)) return;

    // Navigation is always allowed — a disabled node must still be reachable and announced.
    // Only the ACTIONS below are gated, and the guard has to live here: `pointer-events-none`
    // blocks the mouse but does nothing for a keypress.
    const disabled = item.getAttribute("data-disabled") === "true";

    switch (event.key) {
      case "ArrowRight": {
        event.preventDefault();
        event.stopPropagation();
        if (this.hasChildren(item) && !this.isExpanded(item)) {
          this.setExpanded(item, true);
        } else {
          const first = this.childItems(item)[0];
          first && this.focus(first);
        }
        break;
      }

      case "ArrowLeft": {
        event.preventDefault();
        event.stopPropagation();
        if (this.hasChildren(item) && this.isExpanded(item)) {
          this.setExpanded(item, false);
        } else {
          const parent = item.parentElement.closest(SELECT.item);
          parent && this.focus(parent);
        }
        break;
      }

      case "ArrowDown":
      case "ArrowUp": {
        event.preventDefault();
        event.stopPropagation();
        const order = this.visibleItems();
        const next = order[order.indexOf(item) + (event.key === "ArrowDown" ? 1 : -1)];
        if (!next) break;
        this.focus(next);
        if (event.shiftKey && this.opts.allowRangeSelection && this.anchor) {
          this.selectRange(next);
        }
        break;
      }

      case "Home": {
        event.preventDefault();
        const first = this.visibleItems()[0];
        first && this.focus(first);
        break;
      }

      case "End": {
        event.preventDefault();
        const all = this.visibleItems();
        all.length && this.focus(all[all.length - 1]);
        break;
      }

      case " ":
      case "Space": {
        if (this.opts.expandOnSpace) {
          event.preventDefault();
          event.stopPropagation();
          this.toggleExpanded(item);
        }
        if (this.opts.checkOnSpace && !disabled) {
          event.preventDefault();
          event.stopPropagation();
          this.setChecked(item, item.getAttribute("data-checked") !== "true");
        }
        break;
      }

      case "Enter": {
        event.preventDefault();
        if (disabled) break;
        if (!this.selectable(item)) {
          if (this.hasChildren(item)) this.toggleExpanded(item);
          break;
        }
        this.select(item);
        break;
      }

      default:
        return;
    }
  },

  handleFocusOut(event) {
    const item = event.target.closest && event.target.closest(SELECT.item);
    if (item && !item.contains(event.relatedTarget)) {
      item.removeAttribute("data-focus-ring");
    }
  },

  // Guarded: without the length check this fires an O(n) sweep and a websocket event on every
  // click anywhere on the page, forever.
  handleOutside(event) {
    if (this.el.contains(event.target)) return;
    if (this.selectedValues().length === 0) return;
    this.applySelection([]);
  },

  // The focus ring only appears for keyboard-driven focus, mirroring Mantine's
  // data-focus-ring: clicking a node focuses it silently.
  focus(item) {
    this.focusedValue = this.valueOf(item);
    this.items().forEach((i) => i.setAttribute("tabindex", i === item ? "0" : "-1"));
    item.setAttribute("data-focus-ring", "true");
    item.focus();
  },

  // Restore from our OWN record, not from the DOM: `tabindex` is a dynamic in the server's
  // render, so a patch resets it and reading it back would silently send the tab stop to the
  // first root mid-interaction.
  setRovingTabindex() {
    const items = this.items();
    if (!items.length) return;

    const current =
      (this.focusedValue && items.find((i) => this.valueOf(i) === this.focusedValue)) || items[0];

    items.forEach((i) => i.setAttribute("tabindex", i === current ? "0" : "-1"));
  },

  // ── drag & drop ───────────────────────────────────────────────────────────

  bindDragAndDrop() {
    this.dragged = null;

    this.el.addEventListener("dragstart", (event) => {
      const origin = this.opts.withDragHandle
        ? event.target.closest(SELECT.handle)
        : event.target.closest(SELECT.label);
      if (!origin) {
        event.preventDefault();
        return;
      }
      const item = origin.closest(SELECT.item);
      this.dragged = item;
      this.labelOf(item)?.setAttribute("data-dragging", "true");
      event.dataTransfer.effectAllowed = "move";
      event.dataTransfer.setData("text/plain", this.valueOf(item));
    });

    this.el.addEventListener("dragover", (event) => {
      const label = event.target.closest(SELECT.label);
      if (!label || !this.dragged) return;
      const item = label.closest(SELECT.item);
      if (item === this.dragged || this.dragged.contains(item)) return;

      const position = this.dropPosition(event, label, item);
      if (!position) return;

      event.preventDefault();
      this.clearDropMarkers();
      label.setAttribute("data-drag-over", position);
    });

    // `dragleave` also fires when the pointer crosses into a CHILD of the label, so clearing
    // unconditionally would drop the marker mid-hover and swallow the drop that follows.
    this.el.addEventListener("dragleave", (event) => {
      const label = event.target.closest(SELECT.label);
      if (label && !label.contains(event.relatedTarget)) {
        label.removeAttribute("data-drag-over");
      }
    });

    this.el.addEventListener("drop", (event) => {
      const label = event.target.closest(SELECT.label);
      if (!label || !this.dragged) return;
      event.preventDefault();

      const position = label.getAttribute("data-drag-over");
      const item = label.closest(SELECT.item);
      this.clearDropMarkers();

      if (position) {
        this.pushOpt("drag_drop", {
          dragged: this.valueOf(this.dragged),
          target: this.valueOf(item),
          position,
        });
      }
    });

    this.el.addEventListener("dragend", () => {
      this.labelOf(this.dragged)?.removeAttribute("data-dragging");
      this.clearDropMarkers();
      this.dragged = null;
    });
  },

  // Mirrors Mantine's zone geometry: a collapsed folder gets three zones
  // (before / inside / after at 25%-75%), an EXPANDED folder only two — an 'after'
  // drop on its label would render the indicator between the folder and its first
  // child, which reads as "first child" rather than "next sibling".
  dropPosition(event, label, item) {
    const rect = label.getBoundingClientRect();
    const y = event.clientY - rect.top;
    const h = rect.height;
    const folder = this.hasChildren(item);

    let position;
    if (folder && this.isExpanded(item)) {
      position = y < h * 0.5 ? "before" : "inside";
    } else if (folder) {
      position = y < h * 0.25 ? "before" : y > h * 0.75 ? "after" : "inside";
    } else {
      position = y < h * 0.5 ? "before" : "after";
    }

    const allow = this.el.getAttribute("data-allow-drop");
    if (allow === "inside-only" && position !== "inside") return null;
    if (allow === "reorder-only" && position === "inside") return null;
    return position;
  },

  clearDropMarkers() {
    this.el
      .querySelectorAll("[data-drag-over]")
      .forEach((el) => el.removeAttribute("data-drag-over"));
  },

  // ── sync ──────────────────────────────────────────────────────────────────

  syncAll() {
    this.items().forEach((item) => {
      if (this.hasChildren(item)) {
        this.applyExpanded(item, this.expanded.has(this.valueOf(item)));
      }

      const level = Number(item.getAttribute("data-level") || 1);
      item.style.setProperty("--label-offset", `calc(var(--level-offset) * ${level - 1})`);
    });

    this.paintSelection();
    this.paintChecked();
    this.refreshAncestors();
  },

  pushOpt(name, payload) {
    const event = this.el.getAttribute(`data-on-${name.replace(/_/g, "-")}`);
    if (!event) return;
    const target = this.el.getAttribute("data-on-target");
    target ? this.pushEventTo(target, event, payload) : this.pushEventTo(this.el, event, payload);
  },
};

// Select — headless listbox select engine (Base UI parity).
//
// One hook on the root drives the whole component: a `[data-part="trigger"]` (role=combobox) opens a
// `[data-part="popup"]` listbox of `[data-part="item"]` options. Single-select commits + closes;
// `data-multiple` toggles items and keeps the popup open. Keyboard: trigger Enter/Space/Arrow open;
// inside, Arrow Up/Down + Home/End move a roving highlight, Enter/Space commit, Escape/Tab close,
// and typeahead (typing letters) jumps to a matching option (when closed it selects directly).
//
// Reflects Base UI's data-attributes: trigger `data-popup-open`/`data-placeholder` (+ server-rendered
// `data-disabled`/`data-readonly`/`data-required`); `[data-part="value"]` `data-placeholder`;
// `[data-part="icon"]` `data-popup-open`; items `data-selected`/`data-highlighted`/`data-disabled`;
// popup `data-open`/`data-closed`/`data-side`. The selected value(s) are mirrored into hidden inputs
// under `[data-part="value-inputs"]` (single → `name`, multiple → `name[]`) and a bubbling `input`
// event is dispatched so an enclosing `<.form phx-change>` reacts. `data-on-change` (`{value}`) and
// `data-on-open-change` (`{open}`) are pushed to LiveView when set.

const Select = {
  mounted() {
    const el = this.el;
    this.trigger = el.querySelector('[data-part="trigger"]');
    this.popup = el.querySelector('[data-part="popup"]');
    this.valueEl = el.querySelector('[data-part="value"]');
    this.icon = el.querySelector('[data-part="icon"]');
    this.inputs = el.querySelector('[data-part="value-inputs"]');

    this.multiple = el.hasAttribute("data-multiple");
    this.disabled = el.hasAttribute("data-disabled");
    this.readonly = el.hasAttribute("data-readonly");
    this.name = el.getAttribute("data-name");
    this.placeholder = el.getAttribute("data-placeholder") || "";
    this.onChange = el.getAttribute("data-on-change");
    this.onOpenChange = el.getAttribute("data-on-open-change");
    this.side = el.getAttribute("data-side") || "bottom";
    this.hover = !el.hasAttribute("data-no-hover");
    this.typeBuf = "";

    if (!this.popup) return;

    this.selected = new Set(
      this.all().filter((i) => i.hasAttribute("data-selected")).map((i) => this.val(i))
    );

    this.boundOutside = (e) => {
      if (!el.contains(e.target)) this.close();
    };

    if (this.trigger) {
      this.trigger.addEventListener("click", (e) => {
        e.stopPropagation();
        if (!this.disabled) this.toggle();
      });
      this.trigger.addEventListener("keydown", (e) => this.onTriggerKey(e));
    }
    this.popup.addEventListener("keydown", (e) => this.onPopupKey(e));
    this.bindItems();

    this.syncValue();
  },

  destroyed() {
    document.removeEventListener("click", this.boundOutside, true);
  },

  // ---- item helpers ---------------------------------------------------------

  all() {
    return Array.from(this.popup.querySelectorAll('[data-part="item"]'));
  },

  items() {
    return this.all().filter((i) => !i.hasAttribute("data-disabled"));
  },

  val(item) {
    return item.getAttribute("data-value");
  },

  label(item) {
    const t = item.querySelector('[data-part="item-text"]');
    return (t ? t.textContent : item.textContent).trim();
  },

  bindItems() {
    this.all().forEach((item) => {
      if (item._selBound) return;
      item._selBound = true;
      item.addEventListener("click", () => this.commit(item));
      item.addEventListener("pointermove", () => {
        if (this.hover && !item.hasAttribute("data-disabled")) this.highlight(item);
      });
    });
  },

  // ---- open / close ---------------------------------------------------------

  isOpen() {
    return this.popup.hasAttribute("data-open");
  },

  toggle() {
    this.isOpen() ? this.close() : this.open();
  },

  open() {
    if (this.disabled || this.isOpen()) return;
    this.popup.toggleAttribute("data-open", true);
    this.popup.toggleAttribute("data-closed", false);
    this.popup.setAttribute("data-side", this.side);
    this.position();
    if (this.trigger) {
      this.trigger.setAttribute("aria-expanded", "true");
      this.trigger.toggleAttribute("data-popup-open", true);
    }
    if (this.icon) this.icon.toggleAttribute("data-popup-open", true);
    document.addEventListener("click", this.boundOutside, true);

    const start = this.all().find((i) => i.hasAttribute("data-selected")) || this.items()[0];
    if (start) {
      requestAnimationFrame(() => {
        this.highlight(start);
        start.focus();
        start.scrollIntoView({ block: "nearest" });
      });
    }
    if (this.onOpenChange) this.pushEventTo(this.el, this.onOpenChange, { open: true });
  },

  close(focusTrigger = false) {
    if (!this.isOpen()) return;
    this.popup.toggleAttribute("data-open", false);
    this.popup.toggleAttribute("data-closed", true);
    if (this.trigger) {
      this.trigger.setAttribute("aria-expanded", "false");
      this.trigger.removeAttribute("data-popup-open");
    }
    if (this.icon) this.icon.removeAttribute("data-popup-open");
    document.removeEventListener("click", this.boundOutside, true);
    if (focusTrigger && this.trigger) this.trigger.focus();
    if (this.onOpenChange) this.pushEventTo(this.el, this.onOpenChange, { open: false });
  },

  position() {
    const sides = {
      bottom: { top: "100%", bottom: "auto" },
      top: { bottom: "100%", top: "auto" },
      right: { left: "100%", right: "auto", top: "0" },
      left: { right: "100%", left: "auto", top: "0" },
    };
    Object.assign(this.popup.style, sides[this.side] || sides.bottom);
    // Expose the trigger width (Base UI's `--anchor-width`) so consumers can size the popup to it.
    if (this.trigger)
      this.popup.style.setProperty("--anchor-width", `${this.trigger.offsetWidth}px`);
  },

  // ---- highlight / keyboard -------------------------------------------------

  highlight(item) {
    this.all().forEach((i) => {
      const on = i === item;
      i.toggleAttribute("data-highlighted", on);
      i.setAttribute("tabindex", on ? "0" : "-1");
    });
    this.active = item;
  },

  onTriggerKey(e) {
    if (this.disabled) return;
    if (["ArrowDown", "ArrowUp", "Enter", " "].includes(e.key)) {
      e.preventDefault();
      this.open();
    } else if (e.key.length === 1 && !e.metaKey && !e.ctrlKey) {
      // typeahead while closed selects directly (native <select> behavior)
      this.typeahead(e.key, true);
    }
  },

  onPopupKey(e) {
    if (e.key === "Escape") {
      e.preventDefault();
      this.close(true);
      return;
    }
    if (e.key === "Tab") {
      this.close();
      return;
    }
    const items = this.items();
    const idx = items.indexOf(this.active);
    let target = null;
    if (e.key === "ArrowDown") target = items[Math.min(items.length - 1, idx + 1)];
    else if (e.key === "ArrowUp") target = items[Math.max(0, idx - 1)];
    else if (e.key === "Home") target = items[0];
    else if (e.key === "End") target = items[items.length - 1];
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      if (this.active) this.commit(this.active);
      return;
    } else if (e.key.length === 1 && !e.metaKey && !e.ctrlKey) {
      this.typeahead(e.key, false);
      return;
    } else {
      return;
    }
    e.preventDefault();
    if (target) {
      this.highlight(target);
      target.focus();
      target.scrollIntoView({ block: "nearest" });
    }
  },

  typeahead(ch, commitWhenClosed) {
    clearTimeout(this._typeTimer);
    this.typeBuf += ch.toLowerCase();
    this._typeTimer = setTimeout(() => (this.typeBuf = ""), 500);
    const match = this.items().find((i) => this.label(i).toLowerCase().startsWith(this.typeBuf));
    if (!match) return;
    if (commitWhenClosed && !this.multiple) {
      this.commit(match);
    } else {
      this.highlight(match);
      match.focus();
      match.scrollIntoView({ block: "nearest" });
    }
  },

  // ---- selection ------------------------------------------------------------

  commit(item) {
    if (this.disabled || this.readonly || item.hasAttribute("data-disabled")) return;
    const value = this.val(item);

    if (this.multiple) {
      const on = !item.hasAttribute("data-selected");
      item.toggleAttribute("data-selected", on);
      item.setAttribute("aria-selected", String(on));
      if (on) this.selected.add(value);
      else this.selected.delete(value);
    } else {
      this.all().forEach((i) => {
        const on = i === item;
        i.toggleAttribute("data-selected", on);
        i.setAttribute("aria-selected", String(on));
      });
      this.selected = new Set([value]);
      this.close(true);
    }

    this.syncValue();
    if (this.onChange) {
      this.pushEventTo(this.el, this.onChange, { value: this.multiple ? Array.from(this.selected) : value });
    }
  },

  // Reflect the current selection into the trigger value text, data-placeholder, and the hidden
  // form input(s) — then notify any enclosing <.form phx-change>.
  syncValue() {
    const labels = this.all()
      .filter((i) => this.selected.has(this.val(i)))
      .map((i) => this.label(i));
    const empty = labels.length === 0;

    if (this.valueEl) {
      this.valueEl.textContent = empty ? this.placeholder : labels.join(", ");
      this.valueEl.toggleAttribute("data-placeholder", empty);
    }
    if (this.trigger) this.trigger.toggleAttribute("data-placeholder", empty);

    if (this.inputs && this.name) {
      const values = Array.from(this.selected);
      const name = this.multiple ? `${this.name}[]` : this.name;
      const html = (this.multiple ? values : values.slice(0, 1))
        .map((v) => `<input type="hidden" name="${name}" value="${this.escape(v)}">`)
        .join("");
      // single with no value still submits an empty field
      this.inputs.innerHTML =
        html || (this.multiple ? "" : `<input type="hidden" name="${name}" value="">`);
      this.inputs.dispatchEvent(new Event("input", { bubbles: true }));
    }
  },

  escape(s) {
    return String(s).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
  },
};

export default Select;

// Scroller — horizontal scroll container with prev/next controls (Mantine Scroller parity).
//
// The `[data-part="prev"]`/`[data-part="next"]` buttons scroll the `[data-part="viewport"]` by ~80%
// of its width (or `data-scroll-by` px), smoothly. On scroll/resize the buttons get `data-disabled`
// (+ the native `disabled`) at the two ends so you can dim them. Uses a ResizeObserver so it stays
// correct when the container or its content changes size.

const Scroller = {
  mounted() {
    const root = this.el;
    this.viewport = root.querySelector('[data-part="viewport"]');
    this.prev = root.querySelector('[data-part="prev"]');
    this.next = root.querySelector('[data-part="next"]');
    if (!this.viewport) return;

    const amount = () =>
      Number(root.getAttribute("data-scroll-by")) || this.viewport.clientWidth * 0.8;

    this._prevClick = () => this.viewport.scrollBy({ left: -amount(), behavior: "smooth" });
    this._nextClick = () => this.viewport.scrollBy({ left: amount(), behavior: "smooth" });

    this._update = () => {
      const { scrollLeft, scrollWidth, clientWidth } = this.viewport;
      const atStart = scrollLeft <= 1;
      const atEnd = scrollLeft + clientWidth >= scrollWidth - 1;
      if (this.prev) {
        this.prev.toggleAttribute("data-disabled", atStart);
        this.prev.disabled = atStart;
      }
      if (this.next) {
        this.next.toggleAttribute("data-disabled", atEnd);
        this.next.disabled = atEnd;
      }
    };

    if (this.prev) this.prev.addEventListener("click", this._prevClick);
    if (this.next) this.next.addEventListener("click", this._nextClick);
    this.viewport.addEventListener("scroll", this._update, { passive: true });
    this._ro = new ResizeObserver(this._update);
    this._ro.observe(this.viewport);
    this._update();
  },

  destroyed() {
    if (this.prev) this.prev.removeEventListener("click", this._prevClick);
    if (this.next) this.next.removeEventListener("click", this._nextClick);
    if (this.viewport) this.viewport.removeEventListener("scroll", this._update);
    if (this._ro) this._ro.disconnect();
  },
};

export default Scroller;

// NumberField — headless number-field engine (Base UI parity).
//
// A text input flanked by stepper buttons, with an optional drag "scrub area". Reads its config
// from data-* attributes on the root and drives a visible (formatted) input plus a visually hidden
// `type="number"` input for form submission.
//
// Options (root data-*): data-min, data-max, data-step ("any" allowed), data-small-step (Alt),
// data-large-step (Shift), data-snap-on-step, data-allow-out-of-range, data-allow-wheel-scrub,
// data-locale, data-format (JSON Intl.NumberFormatOptions), data-value, data-disabled,
// data-readonly, data-on-change (LiveView event {value}), data-on-commit (LiveView event {value},
// fired on blur / pointer release / keyboard).
//
// Behavior: Arrow Up/Down (±step; Shift ⇒ largeStep, Alt ⇒ smallStep), PageUp/PageDown (±largeStep),
// Home/End (min/max), press-and-hold on the buttons (400ms ⇒ 60ms ticks), wheel scrub when focused
// (opt-in), and pointer scrubbing in the scrub area (data-direction / data-pixel-sensitivity /
// data-teleport-distance, with an optional [data-part="scrub-area-cursor"] virtual cursor that wraps).
// Locale-aware formatting + parsing (currency/percent/unit via Intl). Sets data-scrubbing on the root.

const START_AUTO_CHANGE_DELAY = 400;
const CHANGE_VALUE_TICK_DELAY = 60;

const ARABIC = ["٠", "١", "٢", "٣", "٤", "٥", "٦", "٧", "٨", "٩"];
const PERSIAN = ["۰", "۱", "۲", "۳", "۴", "۵", "۶", "۷", "۸", "۹"];
const FULLWIDTH = ["０", "１", "２", "３", "４", "５", "６", "７", "８", "９"];
const HAN = { 零: "0", "〇": "0", 一: "1", 二: "2", 三: "3", 四: "4", 五: "5", 六: "6", 七: "7", 八: "8", 九: "9" };
const MINUS = ["-", "−", "－", "‒", "–", "—", "﹣"];
const PLUS = ["+", "＋", "﹢"];
const PERCENT = ["%", "٪", "％", "﹪"];
const PERMILLE = ["‰", "؉"];

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const replaceAll = (s, find, rep) => (find ? s.split(find).join(rep) : s);

const NumberField = {
  mounted() {
    const el = this.el;
    this.input = el.querySelector('[data-part="input"]');
    this.hidden = el.querySelector('[data-part="hidden-input"]');
    this.inc = el.querySelector('[data-part="increment"]');
    this.dec = el.querySelector('[data-part="decrement"]');
    this.scrubArea = el.querySelector('[data-part="scrub-area"]');
    this.scrubCursor = el.querySelector('[data-part="scrub-area-cursor"]');
    if (!this.input) return;

    const num = (a) => (el.getAttribute(a) != null && el.getAttribute(a) !== "" ? parseFloat(el.getAttribute(a)) : undefined);
    this.stepRaw = el.getAttribute("data-step") || "1";
    this.step = this.stepRaw === "any" ? 1 : parseFloat(this.stepRaw) || 1;
    this.smallStep = num("data-small-step") ?? 0.1;
    this.largeStep = num("data-large-step") ?? 10;
    this.min = num("data-min");
    this.max = num("data-max");
    this.minD = this.min ?? -Number.MAX_SAFE_INTEGER;
    this.maxD = this.max ?? Number.MAX_SAFE_INTEGER;
    this.minZero = this.min ?? 0;
    this.snapOnStep = el.hasAttribute("data-snap-on-step");
    this.allowOutOfRange = el.hasAttribute("data-allow-out-of-range");
    this.allowWheelScrub = el.hasAttribute("data-allow-wheel-scrub");
    this.disabled = el.hasAttribute("data-disabled");
    this.readonly = el.hasAttribute("data-readonly");
    this.locale = el.getAttribute("data-locale") || undefined;
    try {
      this.format = el.getAttribute("data-format") ? JSON.parse(el.getAttribute("data-format")) : undefined;
    } catch {
      this.format = undefined;
    }
    this.onChange = el.getAttribute("data-on-change");
    this.onCommit = el.getAttribute("data-on-commit");

    const initial = el.getAttribute("data-value");
    this.value = initial != null && initial !== "" ? parseFloat(initial) : null;
    if (Number.isNaN(this.value)) this.value = null;
    this.allowInputSync = true;

    this.setDisplay(this.fmt(this.value));
    this.syncHidden();

    // input
    this.input.addEventListener("keydown", (e) => this.onKeyDown(e));
    this.input.addEventListener("input", (e) => this.onInput(e));
    this.input.addEventListener("blur", (e) => this.onBlur(e));
    this.input.addEventListener("focus", (e) => this.onFocus(e));
    this.input.addEventListener("paste", (e) => this.onPaste(e));
    this.onWheel = (e) => this.handleWheel(e);
    this.input.addEventListener("wheel", this.onWheel, { passive: false });

    // buttons (pointer-only; tabindex=-1)
    if (this.inc) this.bindButton(this.inc, 1);
    if (this.dec) this.bindButton(this.dec, -1);

    // scrub area
    if (this.scrubArea) this.bindScrub();
  },

  destroyed() {
    this.clearHold();
    this.endScrub();
  },

  // ---- formatting / parsing -------------------------------------------------

  formatter(opts) {
    return new Intl.NumberFormat(this.locale, opts || this.format || { maximumFractionDigits: 20 });
  },

  localeDetails() {
    const det = {};
    this.formatter().formatToParts(11111.1).forEach((p) => (det[p.type] = p.value));
    new Intl.NumberFormat(this.locale).formatToParts(0.1).forEach((p) => {
      if (p.type === "decimal") det.decimal = p.value;
    });
    return det;
  },

  fmt(v) {
    if (v == null || !Number.isFinite(v)) return "";
    return this.formatter().format(v);
  },

  parse(str) {
    if (str == null) return null;
    let input = String(str).replace(/\p{Cf}/gu, "").trim();
    if (input === "") return null;

    MINUS.forEach((s) => (input = replaceAll(input, s, "-")));
    PLUS.forEach((s) => (input = replaceAll(input, s, "+")));
    let neg = false;
    let m = input.match(/([+-])\s*$/);
    if (m) {
      if (m[1] === "-") neg = true;
      input = input.replace(/([+-])\s*$/, "");
    }
    m = input.match(/^\s*([+-])/);
    if (m) {
      if (m[1] === "-") neg = true;
      input = input.replace(/^\s*[+-]/, "");
    }

    const det = this.localeDetails();
    if (det.group) input = /\p{Zs}/u.test(det.group) ? input.replace(/\p{Zs}/gu, "") : replaceAll(input, det.group, "");
    if (det.currency) input = replaceAll(input, det.currency, "");
    if (det.decimal && det.decimal !== ".") input = replaceAll(input, det.decimal, ".");
    input = replaceAll(replaceAll(input, "．", "."), "，", "");
    input = replaceAll(replaceAll(input, "٫", "."), "٬", "");

    ARABIC.forEach((ch, i) => (input = replaceAll(input, ch, String(i))));
    PERSIAN.forEach((ch, i) => (input = replaceAll(input, ch, String(i))));
    FULLWIDTH.forEach((ch, i) => (input = replaceAll(input, ch, String(i))));
    Object.keys(HAN).forEach((ch) => (input = replaceAll(input, ch, HAN[ch])));

    const isUnitPercent = this.format && this.format.style === "unit" && this.format.unit === "percent";
    const hasPercent = PERCENT.some((s) => String(str).includes(s)) || (this.format && this.format.style === "percent");
    const hasPermille = PERMILLE.some((s) => String(str).includes(s));
    PERCENT.concat(PERMILLE).forEach((s) => (input = replaceAll(input, s, "")));

    input = input.replace(/[^0-9.]/g, "");
    const lastDot = input.lastIndexOf(".");
    if (lastDot !== -1) {
      input = input.slice(0, lastDot).replace(/\./g, "") + "." + input.slice(lastDot + 1).replace(/\./g, "");
    }

    let n = parseFloat((neg ? "-" : "") + input);
    if (!Number.isFinite(n)) return null;
    if (hasPermille) n /= 1000;
    else if (!isUnitPercent && hasPercent) n /= 100;
    return Number.isFinite(n) ? n : null;
  },

  // ---- validation (snap / clamp / float cleanup) ----------------------------

  snapToStep(value, base, step, nearest) {
    const stepSize = Math.abs(step);
    const dir = Math.sign(step) || 1;
    const raw = value - base + stepSize * 1e-10 * dir;
    if (nearest) return base + Math.round(raw / step) * step;
    const snapped = dir > 0 ? Math.floor(raw / stepSize) : Math.ceil(raw / stepSize);
    return base + snapped * stepSize;
  },

  cleanFP(v) {
    return Number.isFinite(v) ? parseFloat(v.toPrecision(12)) : v;
  },

  validate(value, { step, small, doClamp }) {
    if (value == null) return value;
    let n = value;
    if (step != null && this.snapOnStep && step !== 0) {
      const base = small || this.minD === -Number.MAX_SAFE_INTEGER ? this.minZero : this.minD;
      n = this.snapToStep(n, base, step, small);
    }
    if (doClamp) n = clamp(n, this.minD, this.maxD);
    n = this.cleanFP(n);
    return doClamp ? clamp(n, this.minD, this.maxD) : n;
  },

  // ---- value mutation -------------------------------------------------------

  stepAmount(e) {
    if (e && e.altKey) return this.smallStep;
    if (e && e.shiftKey) return this.largeStep;
    return this.step;
  },

  isStepReason(reason) {
    return !["input-change", "input-blur", "input-paste", "input-clear", "none"].includes(reason);
  },

  setValue(raw, { reason = "none", dir = 0, e } = {}) {
    const doClamp = !this.allowOutOfRange || this.isStepReason(reason);
    const small = !!(e && e.altKey);
    const stepForSnap = dir ? this.stepAmount(e) * dir : null;
    const validated = this.validate(raw, { step: stepForSnap, small, doClamp });

    const changed = validated !== this.value;
    this.value = validated;
    this.syncHidden();
    if (this.allowInputSync) this.setDisplay(this.fmt(validated));

    // Notify any enclosing <.form phx-change> — the hidden input is set programmatically.
    if (changed && this.hidden) this.hidden.dispatchEvent(new Event("input", { bubbles: true }));
    if (changed && this.onChange) this.pushEventTo(this.el, this.onChange, { value: validated });
    return validated;
  },

  increment(dir, e, reason) {
    const amount = this.stepAmount(e);
    const next = typeof this.value === "number" ? this.value + amount * dir : Math.max(0, this.min ?? 0);
    return this.setValue(next, { reason: reason || "keyboard", dir, e });
  },

  // Fired when an interaction finalizes a value (blur / keyboard / pointer release).
  commit() {
    if (this.onCommit) this.pushEventTo(this.el, this.onCommit, { value: this.value });
  },

  setDisplay(text) {
    this.input.value = text;
  },

  syncHidden() {
    if (this.hidden) this.hidden.value = this.value == null ? "" : String(this.value);
  },

  // ---- input events ---------------------------------------------------------

  onFocus() {
    if (this.disabled || this.readonly) return;
    if (this._touched) return;
    this._touched = true;
    const len = this.input.value.length;
    this.input.setSelectionRange(len, len);
  },

  onInput(e) {
    if (this.disabled || this.readonly) return;
    this.allowInputSync = false;
    const text = this.input.value;
    if (text.trim() === "") {
      this.setValue(null, { reason: "input-clear", e });
      return;
    }
    const parsed = this.parse(text);
    if (parsed !== null) {
      // update value but DON'T reformat the text the user is typing
      this.allowInputSync = false;
      this.setValue(parsed, { reason: "input-change", e });
    }
  },

  onBlur(e) {
    if (this.disabled || this.readonly) return;
    this.allowInputSync = true;
    const text = this.input.value;
    if (text.trim() === "") {
      this.setValue(null, { reason: "input-clear", e });
      this.setDisplay("");
      this.commit();
      return;
    }
    const parsed = this.parse(text);
    if (parsed === null) {
      // revert to last good value
      this.setDisplay(this.fmt(this.value));
      return;
    }
    const v = this.setValue(parsed, { reason: "input-blur", e });
    this.setDisplay(this.fmt(v));
    this.commit();
  },

  onPaste(e) {
    if (this.disabled || this.readonly) return;
    let data = "";
    try {
      data = (e.clipboardData || window.clipboardData).getData("text") || "";
    } catch {
      return;
    }
    const parsed = this.parse(data);
    if (parsed !== null) {
      e.preventDefault();
      this.allowInputSync = false;
      this.setValue(parsed, { reason: "input-paste", e });
      this.input.value = data;
    }
  },

  onKeyDown(e) {
    if (this.disabled || this.readonly) return;
    this.allowInputSync = true;
    const k = e.key;
    let handled = true;
    if (k === "ArrowUp") {
      e.preventDefault();
      this.increment(1, e);
    } else if (k === "ArrowDown") {
      e.preventDefault();
      this.increment(-1, e);
    } else if (k === "PageUp") {
      e.preventDefault();
      this.setValue((this.value ?? 0) + this.largeStep, { reason: "keyboard", dir: 1, e });
    } else if (k === "PageDown") {
      e.preventDefault();
      this.setValue((this.value ?? 0) - this.largeStep, { reason: "keyboard", dir: -1, e });
    } else if (k === "Home" && this.min != null) {
      e.preventDefault();
      this.setValue(this.min, { reason: "keyboard", e });
      this.setDisplay(this.fmt(this.value));
    } else if (k === "End" && this.max != null) {
      e.preventDefault();
      this.setValue(this.max, { reason: "keyboard", e });
      this.setDisplay(this.fmt(this.value));
    } else {
      handled = false;
    }
    if (handled) this.commit();
  },

  handleWheel(e) {
    if (!this.allowWheelScrub || this.disabled || this.readonly) return;
    if (e.ctrlKey || document.activeElement !== this.input) return;
    e.preventDefault();
    this.allowInputSync = true;
    this.increment(e.deltaY > 0 ? -1 : 1, e, "wheel");
    this.commit();
  },

  // ---- stepper buttons (press-and-hold) -------------------------------------

  bindButton(btn, dir) {
    btn.addEventListener("pointerdown", (e) => {
      if (this.disabled || this.readonly || (e.button && e.button !== 0)) return;
      e.preventDefault();
      if (e.pointerType !== "touch" && e.pointerType !== "pen") this.input.focus();
      this._held = false;
      this.allowInputSync = true;
      const reason = dir > 0 ? "increment-press" : "decrement-press";
      const startTick = () => {
        this._held = true;
        this.increment(dir, e, reason);
        this.holdInterval = setInterval(() => this.increment(dir, e, reason), CHANGE_VALUE_TICK_DELAY);
      };
      this.holdTimer = setTimeout(startTick, START_AUTO_CHANGE_DELAY);
      const up = () => {
        this.clearHold();
        if (!this._held) this.increment(dir, e, reason);
        this.commit();
        window.removeEventListener("pointerup", up);
        window.removeEventListener("pointercancel", up);
      };
      window.addEventListener("pointerup", up);
      window.addEventListener("pointercancel", up);
    });
  },

  clearHold() {
    clearTimeout(this.holdTimer);
    clearInterval(this.holdInterval);
    this.holdTimer = this.holdInterval = null;
  },

  // ---- scrub area -----------------------------------------------------------

  bindScrub() {
    const area = this.scrubArea;
    this.scrubDir = area.getAttribute("data-direction") || "horizontal";
    this.pixelSensitivity = parseFloat(area.getAttribute("data-pixel-sensitivity")) || 2;
    this.teleport = parseFloat(area.getAttribute("data-teleport-distance")) || undefined;
    area.style.touchAction = "none";
    area.addEventListener("pointerdown", (e) => this.startScrub(e));
  },

  startScrub(e) {
    if (this.disabled || this.readonly || (e.button && e.button !== 0)) return;
    e.preventDefault();
    this.input.focus();
    this.allowInputSync = true;
    this._scrubAccum = 0;
    this.el.toggleAttribute("data-scrubbing", true);

    if (this.scrubCursor) {
      this.scrubCursor.toggleAttribute("data-scrubbing", true);
      const cw = this.scrubCursor.offsetWidth;
      const ch = this.scrubCursor.offsetHeight;
      this._vx = e.clientX - cw / 2;
      this._vy = e.clientY - ch / 2;
      this.scrubCursor.style.position = "fixed";
      this.scrubCursor.style.left = "0px";
      this.scrubCursor.style.top = "0px";
      this.scrubCursor.style.pointerEvents = "none";
      this.scrubCursor.style.transform = `translate3d(${this._vx}px,${this._vy}px,0)`;
      if (this.scrubArea.requestPointerLock) {
        try {
          this.scrubArea.requestPointerLock();
        } catch {
          /* ignore */
        }
      }
    }

    this.onScrubMove = (ev) => this.scrubMove(ev);
    this.onScrubUp = () => this.endScrub();
    window.addEventListener("pointermove", this.onScrubMove);
    window.addEventListener("pointerup", this.onScrubUp);
    window.addEventListener("pointercancel", this.onScrubUp);
  },

  scrubMove(e) {
    // value change
    const move = this.scrubDir === "vertical" ? -e.movementY : e.movementX;
    this._scrubAccum += move;
    const sens = this.pixelSensitivity || 2;
    while (Math.abs(this._scrubAccum) >= sens) {
      const dir = this._scrubAccum > 0 ? 1 : -1;
      this._scrubAccum -= dir * sens;
      this.increment(dir, e, "scrub");
    }

    // virtual cursor (wraps within the teleport box, else the viewport)
    if (this.scrubCursor && this._vx != null) {
      const cw = this.scrubCursor.offsetWidth;
      const ch = this.scrubCursor.offsetHeight;
      let x = this._vx + e.movementX;
      let y = this._vy + e.movementY;
      let minX = 0;
      let minY = 0;
      let maxX = window.innerWidth;
      let maxY = window.innerHeight;
      if (this.teleport) {
        const r = this.scrubArea.getBoundingClientRect();
        const cx = r.left + r.width / 2;
        const cy = r.top + r.height / 2;
        minX = cx - this.teleport;
        maxX = cx + this.teleport;
        minY = cy - this.teleport;
        maxY = cy + this.teleport;
      }
      if (x + cw / 2 < minX) x = maxX - cw / 2;
      else if (x + cw / 2 > maxX) x = minX - cw / 2;
      if (y + ch / 2 < minY) y = maxY - ch / 2;
      else if (y + ch / 2 > maxY) y = minY - ch / 2;
      this._vx = x;
      this._vy = y;
      this.scrubCursor.style.transform = `translate3d(${x}px,${y}px,0)`;
    }
  },

  endScrub() {
    if (!this.onScrubMove) return;
    window.removeEventListener("pointermove", this.onScrubMove);
    window.removeEventListener("pointerup", this.onScrubUp);
    window.removeEventListener("pointercancel", this.onScrubUp);
    this.onScrubMove = this.onScrubUp = null;
    this.el.removeAttribute("data-scrubbing");
    if (this.scrubCursor) {
      this.scrubCursor.removeAttribute("data-scrubbing");
      this.scrubCursor.style.transform = "";
      this._vx = this._vy = null;
    }
    if (document.exitPointerLock && document.pointerLockElement) {
      try {
        document.exitPointerLock();
      } catch {
        /* ignore */
      }
    }
    this.commit();
  },
};

export default NumberField;

// Otp — headless one-time-code (OTP) field engine (Base UI parity).
//
// A row of single-character `[data-part="input"]` boxes backed by one logical value string.
// Reads config from the root's data-*: data-length, data-validation-type
// (numeric|alpha|alphanumeric|none), data-transform (none|uppercase|lowercase), data-mask,
// data-auto-submit, data-disabled, data-readonly, data-value (initial), data-on-change /
// data-on-complete / data-on-invalid (LiveView events, {value}).
//
// Behavior: typing replaces + auto-advances; paste distributes & normalizes; Backspace clears
// (Ctrl/Meta+Backspace clears all); Delete removes-and-shifts; Arrows + Home/End/ArrowUp/Down
// navigate (roving tabindex — only the active slot is tabbable). Rejected characters fire
// on-invalid. The combined value mirrors into the hidden `[data-part="value"]` input; when every
// slot is filled the root gets `data-complete`, on-complete fires, and the owning form is submitted
// if data-auto-submit is set. Each box reflects `data-filled`; the root reflects
// `data-filled`/`data-complete`/`data-focused`.

const DISALLOWED = {
  numeric: /[^\d]/g,
  alpha: /[^a-zA-Z]/g,
  alphanumeric: /[^a-zA-Z0-9]/g,
};

const Otp = {
  mounted() {
    const el = this.el;
    this.boxes = Array.from(el.querySelectorAll('[data-part="input"]'));
    this.hidden = el.querySelector('[data-part="value"]');
    if (!this.boxes.length) return;

    this.length = parseInt(el.getAttribute("data-length"), 10) || this.boxes.length;
    this.validationType = el.getAttribute("data-validation-type") || "numeric";
    this.disallowed = DISALLOWED[this.validationType] || null;
    this.transform = el.getAttribute("data-transform") || "none";
    this.autoSubmit = el.hasAttribute("data-auto-submit");
    this.disabled = el.hasAttribute("data-disabled");
    this.readonly = el.hasAttribute("data-readonly");
    this.onChange = el.getAttribute("data-on-change");
    this.onComplete = el.getAttribute("data-on-complete");
    this.onInvalid = el.getAttribute("data-on-invalid");

    this.value = this.normalize(el.getAttribute("data-value") || (this.hidden && this.hidden.value) || "")[0];
    this.activeIndex = Math.min(this.value.length, this.length - 1);
    this.render();

    this.boxes.forEach((box, i) => {
      box.addEventListener("input", (e) => this.onInput(e, i));
      box.addEventListener("keydown", (e) => this.onKeyDown(e, i));
      box.addEventListener("paste", (e) => this.onPaste(e, i));
      box.addEventListener("focus", () => this.onBoxFocus(i));
      box.addEventListener("mousedown", (e) => {
        if (this.disabled) return;
        e.preventDefault();
        this.focusBox(i);
      });
    });

    this.onFocusIn = () => this.setFocused(true);
    this.onFocusOut = (e) => {
      if (e.relatedTarget && el.contains(e.relatedTarget)) return;
      this.setFocused(false);
    };
    el.addEventListener("focusin", this.onFocusIn);
    el.addEventListener("focusout", this.onFocusOut);

    // Server can set/clear the value: push_event("chelekom:otp", %{id: dom_id, value: "..."}).
    // Needed because the root is phx-update="ignore" (the slots are client-owned), so a server
    // re-render can't reset them — this is the channel for programmatic set/clear.
    this.setRef = this.handleEvent("chelekom:otp", (p) => {
      if (!p || (p.id && p.id !== el.id)) return;
      this.value = this.normalize(p.value ?? "")[0];
      this.activeIndex = Math.min(Array.from(this.value).length, this.length - 1);
      this.render();
      if (p.focus !== false) this.focusBox(this.activeIndex);
    });
  },

  destroyed() {
    this.el.removeEventListener("focusin", this.onFocusIn);
    this.el.removeEventListener("focusout", this.onFocusOut);
    if (this.setRef) this.removeHandleEvent(this.setRef);
  },

  // ---- normalization --------------------------------------------------------

  normalize(str) {
    let s = (str ?? "").replace(/\s/g, "");
    const before = Array.from(s).length;
    if (this.disallowed) s = s.replace(this.disallowed, "");
    if (this.transform === "uppercase") s = s.toUpperCase();
    else if (this.transform === "lowercase") s = s.toLowerCase();
    if (this.disallowed) s = s.replace(this.disallowed, "");
    const chars = Array.from(s);
    const rejected = before > chars.length || chars.length > this.length;
    return [chars.slice(0, this.length).join(""), rejected];
  },

  replaceAt(current, index, chunk) {
    const norm = this.normalize(chunk)[0];
    const prefix = current.slice(0, index);
    const suffix = current.slice(index + Array.from(norm).length);
    return this.normalize(prefix + norm + suffix)[0];
  },

  removeAt(current, index) {
    const chars = Array.from(current);
    if (index < 0 || index >= chars.length) return current;
    chars.splice(index, 1);
    return chars.join("");
  },

  isComplete() {
    return Array.from(this.value).length === this.length;
  },

  // ---- rendering / state ----------------------------------------------------

  render() {
    const chars = Array.from(this.value);
    const complete = this.isComplete();
    this.boxes.forEach((b, i) => {
      const c = chars[i] || "";
      if (b.value !== c) b.value = c;
      b.toggleAttribute("data-filled", c !== "");
      b.toggleAttribute("data-complete", complete);
      b.tabIndex = i === this.activeIndex ? 0 : -1;
    });
    this.el.toggleAttribute("data-complete", complete);
    this.el.toggleAttribute("data-filled", chars.length > 0);
    if (this.hidden && this.hidden.value !== this.value) this.hidden.value = this.value;
  },

  setFocused(on) {
    this.el.toggleAttribute("data-focused", on);
    this.boxes.forEach((b) => b.toggleAttribute("data-focused", on));
  },

  fire(event, value) {
    if (event) this.pushEventTo(this.el, event, { value });
  },

  setValue(next, reason) {
    const [norm] = this.normalize(next);
    const wasComplete = this.isComplete();
    const changed = norm !== this.value;
    this.value = norm;
    this.render();
    // Notify any enclosing <.form> (phx-change): the hidden input is set programmatically, so it
    // would not fire input events on its own.
    if (changed && this.hidden) this.hidden.dispatchEvent(new Event("input", { bubbles: true }));
    if (changed) this.fire(this.onChange, norm);
    if (this.isComplete() && (changed || !wasComplete)) {
      this.fire(this.onComplete, norm);
      if (this.autoSubmit) this.submitForm();
    }
    return norm;
  },

  focusBox(i) {
    const idx = Math.max(0, Math.min(this.length - 1, i));
    this.activeIndex = idx;
    this.boxes.forEach((b, j) => (b.tabIndex = j === idx ? 0 : -1));
    const box = this.boxes[idx];
    if (box) {
      box.focus();
      box.select();
    }
  },

  onBoxFocus(i) {
    this.activeIndex = i;
    this.boxes.forEach((b, j) => (b.tabIndex = j === i ? 0 : -1));
    this.boxes[i].select();
  },

  submitForm() {
    const form = (this.hidden && this.hidden.form) || this.el.closest("form");
    if (form && typeof form.requestSubmit === "function") form.requestSubmit();
  },

  // ---- events ---------------------------------------------------------------

  onInput(e, i) {
    if (this.disabled || this.readonly) return;
    const raw = e.target.value;
    const [norm, rejected] = this.normalize(raw);
    if (rejected) this.fire(this.onInvalid, raw);

    if (norm === "") {
      if (raw === "") {
        this.setValue(this.removeAt(this.value, i), "input-clear");
      } else {
        // reject — restore the slot's character
        e.target.value = Array.from(this.value)[i] || "";
        e.target.select();
      }
      return;
    }

    this.setValue(this.replaceAt(this.value, i, norm), "input-change");
    this.focusBox(Math.min(i + Array.from(norm).length, this.length - 1));
  },

  onKeyDown(e, i) {
    if (this.disabled) return;
    const last = this.length - 1;
    const endTarget = Math.min(Array.from(this.value).length, last);
    const boundary = (e.ctrlKey || e.metaKey) && !e.altKey;
    const k = e.key;

    if (k === "ArrowLeft") {
      e.preventDefault();
      this.focusBox(boundary ? 0 : i - 1);
      return;
    }
    if (k === "ArrowRight") {
      e.preventDefault();
      this.focusBox(boundary ? endTarget : i + 1);
      return;
    }
    if (k === "Home" || k === "ArrowUp") {
      e.preventDefault();
      this.focusBox(0);
      return;
    }
    if (k === "End" || k === "ArrowDown") {
      e.preventDefault();
      this.focusBox(endTarget);
      return;
    }

    if (this.readonly) return;

    if (k === "Backspace" && boundary) {
      e.preventDefault();
      this.setValue("", "keyboard");
      this.focusBox(0);
      return;
    }
    if (k === "Delete") {
      e.preventDefault();
      this.setValue(this.removeAt(this.value, i), "keyboard");
      this.focusBox(i);
      return;
    }

    const inputEl = e.currentTarget;
    const fullSelection = inputEl.selectionStart === 0 && inputEl.selectionEnd === inputEl.value.length;
    const slot = Array.from(this.value)[i] || "";
    if (k.length === 1 && fullSelection && slot === k) {
      e.preventDefault();
      if (i < last) this.focusBox(i + 1);
      return;
    }

    if (k === "Backspace") {
      e.preventDefault();
      const target = Math.max(0, i - 1);
      const deleteIndex = slot === "" ? target : i;
      this.setValue(this.removeAt(this.value, deleteIndex), "keyboard");
      this.focusBox(target);
    }
  },

  onPaste(e, i) {
    if (this.disabled || this.readonly) return;
    e.preventDefault();
    let raw = "";
    try {
      raw = (e.clipboardData || window.clipboardData).getData("text") || "";
    } catch {
      return;
    }
    const [norm, rejected] = this.normalize(raw);
    if (rejected) this.fire(this.onInvalid, raw);
    if (norm === "") return;
    this.setValue(this.replaceAt(this.value, i, norm), "input-paste");
    this.focusBox(Math.min(i + Array.from(norm).length, this.length - 1));
  },
};

export default Otp;

// NavigationMenu — a site nav with a single SHARED morphing popup (Base UI parity).
//
// All trigger items share ONE positioner/popup/viewport/arrow. Activating an item moves its stored
// `[data-part="content"]` into the viewport and MORPHS the popup's size (`--popup-width/height`) from
// the old size to the new one, while the positioner moves under the active trigger. Switching between
// already-open items is instant (no open delay) and sets `data-activation-direction` (left/right/up/down,
// from the prev-vs-next trigger rects) so the consumer can slide the content. Hover opens after `delay`,
// closes after `close-delay`; a "patient click" right after a hover-open is ignored.
//
// State: positioner/popup `data-open`/`data-closed` + `data-side`/`data-align`; active trigger
// `data-popup-open` + `aria-expanded` + its `[data-part="icon"]` `data-open`; active content
// `data-activation-direction`. CSS vars: popup `--popup-width/height`, positioner
// `--positioner-width/height`. (Simplified vs Base UI: inline positioning — no Portal/Backdrop/nested/
// transition-status; close-grace = "pointer over the list or popup".)

const OPEN_DELAY = 50;
const CLOSE_DELAY = 50;
const PATIENT_CLICK = 500;
const SIDE_OFFSET = 8;

const NavigationMenu = {
  mounted() {
    const el = this.el;
    this.list = el.querySelector('[data-part="list"]');
    this.positioner = el.querySelector('[data-part="positioner"]');
    this.popup = el.querySelector('[data-part="popup"]');
    this.viewport = el.querySelector('[data-part="viewport"]');
    this.arrow = el.querySelector('[data-part="arrow"]');

    this.orientation = el.getAttribute("data-orientation") || "horizontal";
    this.vertical = this.orientation === "vertical";
    this.side = el.getAttribute("data-side") || "bottom";
    this.align = el.getAttribute("data-align") || "center";
    this.delay = Number(el.getAttribute("data-delay")) || OPEN_DELAY;
    this.closeDelay = Number(el.getAttribute("data-close-delay")) || CLOSE_DELAY;

    this.items = Array.from(el.querySelectorAll('[data-part="item"]')).map((li) => ({
      value: li.getAttribute("data-value"),
      li,
      trigger: li.querySelector('[data-part="trigger"]'),
      content: li.querySelector('[data-part="content"]'),
    }));
    this.triggers = this.items.filter((it) => it.trigger);

    this.value = null;
    this.prevTrigger = null;
    this.activeContent = null;
    this.stick = false;
    this.overList = false;
    this.overPopup = false;

    // prevSize fallback (popup reads 0 mid-transition)
    this.prevSize = { w: 0, h: 0 };
    this.ro = new ResizeObserver(() => {
      if (this.popup.offsetWidth > 0) this.prevSize = { w: this.popup.offsetWidth, h: this.popup.offsetHeight };
    });
    this.ro.observe(this.popup);

    this.boundOutside = (e) => {
      if (el.contains(e.target)) return;
      if (e.target.closest("[data-base-ui-navigation-menu-trigger]")) return;
      this.close("outside-press");
    };

    this.triggers.forEach(({ trigger, value }) => {
      trigger.addEventListener("pointerenter", (e) => this.onTriggerEnter(value, e));
      trigger.addEventListener("pointerleave", () => this.scheduleClose());
      trigger.addEventListener("click", () => this.onTriggerClick(value));
      trigger.addEventListener("keydown", (e) => this.onTriggerKey(e, value));
      trigger.addEventListener("blur", () => this.onBlur());
    });
    this.list.addEventListener("pointerenter", () => { this.overList = true; this.cancelClose(); });
    this.list.addEventListener("pointerleave", () => { this.overList = false; this.scheduleClose(); });
    this.popup.addEventListener("pointerenter", () => { this.overPopup = true; this.cancelClose(); });
    this.popup.addEventListener("pointerleave", () => { this.overPopup = false; this.scheduleClose(); });
    this.popup.addEventListener("keydown", (e) => this.onPopupKey(e));

    this.boundResize = () => { if (this.value != null) this.syncSize(); };
    window.addEventListener("resize", this.boundResize);

    // controlled / open-by-default
    const initial = el.getAttribute("data-value");
    if (initial) requestAnimationFrame(() => this.activate(initial, { reason: "none", instant: true }));
  },

  destroyed() {
    document.removeEventListener("click", this.boundOutside, true);
    window.removeEventListener("resize", this.boundResize);
    this.ro?.disconnect();
    this.mo?.disconnect();
    clearTimeout(this._open);
    clearTimeout(this._close);
    clearTimeout(this._stick);
  },

  find(value) {
    return this.triggers.find((it) => it.value === value);
  },

  // ---- core: activate / morph -----------------------------------------------

  activate(value, opts = {}) {
    const reason = opts.reason || "none";
    const it = this.find(value);
    if (!it || !it.content) return;
    if (value === this.value) return;

    const firstOpen = this.value == null;
    const instant = opts.instant || firstOpen;

    // 1. activation direction from prev-vs-next trigger rects (only when already open)
    let dir = null;
    if (!firstOpen && this.prevTrigger) {
      const p = this.prevTrigger.getBoundingClientRect();
      const n = it.trigger.getBoundingClientRect();
      if (this.vertical) dir = n.top === p.top ? null : n.top > p.top ? "down" : "up";
      else dir = n.left === p.left ? null : n.left > p.left ? "right" : "left";
    }

    // 2. OLD size = what the popup currently shows (the last committed positioner size)
    const curW = parseFloat(this.positioner.style.getPropertyValue("--positioner-width")) || this.popup.offsetWidth || this.prevSize.w;
    const curH = parseFloat(this.positioner.style.getPropertyValue("--positioner-height")) || this.popup.offsetHeight || this.prevSize.h;

    // 3. swap content: previous back to its <li>, next into the viewport
    if (this.activeContent) {
      this.activeContent.setAttribute("hidden", "");
      this.prevLi.appendChild(this.activeContent);
    }
    it.content.removeAttribute("hidden");
    this.viewport.appendChild(it.content);
    this.activeContent = it.content;
    this.prevLi = it.li;
    this.mo?.disconnect();
    this.mo = new MutationObserver(() => { if (this.value != null) this.syncSize(); });
    this.mo.observe(it.content, { childList: true, subtree: true, characterData: true });

    // 4. mark OPEN first — the positioner is `display:none` while `data-closed`, so it must be visible
    // before we can measure (otherwise the first open reads 0).
    this.positioner.toggleAttribute("data-open", true);
    this.positioner.toggleAttribute("data-closed", false);
    this.popup.toggleAttribute("data-open", true);
    this.popup.toggleAttribute("data-closed", false);
    [this.positioner, this.popup, this.arrow].forEach((n) => {
      if (!n) return;
      n.setAttribute("data-side", this.side);
      n.setAttribute("data-align", this.align);
    });
    document.addEventListener("click", this.boundOutside, true);

    // 5. clear fixed sizes, then measure the NEW content's natural size. The viewport is normally
    // width/height:100% of the (auto) popup — circular — so un-constrain it to `max-content` just for
    // the measurement, read the content box, and restore.
    this.clearVars();
    this.viewport.style.width = "max-content";
    this.viewport.style.height = "max-content";
    const measuredW = it.content.offsetWidth || this.prevSize.w;
    const measuredH = it.content.offsetHeight || this.prevSize.h;
    this.viewport.style.width = "";
    this.viewport.style.height = "";

    // 6. position under the trigger (needs the measured width for align=center/end)
    this.position(it.trigger, measuredW);

    // 6/8. write sizes — morph from OLD→NEW unless first open / instant
    this.positioner.style.setProperty("--positioner-width", `${measuredW}px`);
    this.positioner.style.setProperty("--positioner-height", `${measuredH}px`);
    if (instant) {
      this.popup.style.setProperty("--popup-width", `${measuredW}px`);
      this.popup.style.setProperty("--popup-height", `${measuredH}px`);
      this.positioner.toggleAttribute("data-instant", true);
      requestAnimationFrame(() => this.positioner.removeAttribute("data-instant"));
    } else {
      this.popup.style.setProperty("--popup-width", `${curW}px`);
      this.popup.style.setProperty("--popup-height", `${curH}px`);
      requestAnimationFrame(() => {
        if (this.value !== value) return;
        this.popup.style.setProperty("--popup-width", `${measuredW}px`);
        this.popup.style.setProperty("--popup-height", `${measuredH}px`);
      });
    }

    // 10. activation direction on the active content
    if (dir) it.content.setAttribute("data-activation-direction", dir);
    else it.content.removeAttribute("data-activation-direction");

    // 11. arrow + 12. per-trigger state + roving
    this.positionArrow(it.trigger);
    this.triggers.forEach(({ trigger, value: v }) => {
      const on = v === value;
      trigger.setAttribute("aria-expanded", String(on));
      trigger.toggleAttribute("data-popup-open", on);
      trigger.setAttribute("tabindex", on ? "0" : "-1");
      const icon = trigger.querySelector('[data-part="icon"]');
      if (icon) icon.toggleAttribute("data-open", on);
    });

    // 13. after the morph settles, release the popup size back to auto (positioner keeps px)
    this.scheduleAutoSize(value);

    // 14. bookkeeping + optional focus
    this.value = value;
    this.prevTrigger = it.trigger;
    if (reason === "trigger-press" || reason === "list-navigation") {
      requestAnimationFrame(() => {
        const f = this.viewport.querySelector('a,button,[tabindex]:not([tabindex="-1"]),input,select,textarea');
        if (f) f.focus();
      });
    }
  },

  scheduleAutoSize(value) {
    clearTimeout(this._auto);
    const done = () => {
      if (this.value !== value) return;
      this.popup.style.setProperty("--popup-width", "auto");
      this.popup.style.setProperty("--popup-height", "auto");
    };
    // settle after the transition; fall back to a timer if no transition runs
    const anims = this.popup.getAnimations ? this.popup.getAnimations() : [];
    if (anims.length) Promise.allSettled(anims.map((a) => a.finished)).then(done);
    this._auto = setTimeout(done, 300);
  },

  syncSize() {
    this.clearVars();
    const w = this.popup.offsetWidth || this.prevSize.w;
    const h = this.popup.offsetHeight || this.prevSize.h;
    this.positioner.style.setProperty("--positioner-width", `${w}px`);
    this.positioner.style.setProperty("--positioner-height", `${h}px`);
    if (this.prevTrigger) this.position(this.prevTrigger, w);
  },

  clearVars() {
    ["--popup-width", "--popup-height"].forEach((v) => this.popup.style.removeProperty(v));
    ["--positioner-width", "--positioner-height"].forEach((v) => this.positioner.style.removeProperty(v));
  },

  close(reason) {
    if (this.value == null) return;
    const trigger = this.prevTrigger;

    // seed exit size from the positioner's current px (not a fresh measure)
    const w = this.positioner.style.getPropertyValue("--positioner-width");
    const h = this.positioner.style.getPropertyValue("--positioner-height");
    if (w) {
      this.popup.style.setProperty("--popup-width", w);
      this.popup.style.setProperty("--popup-height", h);
    }

    this.positioner.toggleAttribute("data-open", false);
    this.positioner.toggleAttribute("data-closed", true);
    this.popup.toggleAttribute("data-open", false);
    this.popup.toggleAttribute("data-closed", true);

    if (this.activeContent) {
      this.activeContent.removeAttribute("data-activation-direction");
      this.activeContent.setAttribute("hidden", "");
      this.prevLi.appendChild(this.activeContent);
      this.activeContent = null;
    }
    this.mo?.disconnect();

    this.triggers.forEach(({ trigger: t }) => {
      t.setAttribute("aria-expanded", "false");
      t.removeAttribute("data-popup-open");
      const icon = t.querySelector('[data-part="icon"]');
      if (icon) icon.removeAttribute("data-open");
    });

    this.value = null;
    document.removeEventListener("click", this.boundOutside, true);
    requestAnimationFrame(() => this.clearVars());

    if (trigger && !["trigger-hover", "outside-press", "focus-out"].includes(reason)) {
      const ae = document.activeElement;
      if (ae === document.body || this.popup.contains(ae)) trigger.focus({ preventScroll: true });
    }
  },

  // ---- positioning ----------------------------------------------------------

  position(trigger, width) {
    const r = this.el.getBoundingClientRect();
    const t = trigger.getBoundingClientRect();
    const s = this.positioner.style;
    s.position = "absolute";
    s.top = s.left = s.right = s.bottom = "";
    if (this.side === "bottom") s.top = `${t.bottom - r.top + SIDE_OFFSET}px`;
    else if (this.side === "top") s.bottom = `${r.bottom - t.top + SIDE_OFFSET}px`;
    else s.top = `${t.top - r.top}px`;

    if (this.side === "left" || this.side === "right") {
      if (this.side === "right") s.left = `${t.right - r.left + SIDE_OFFSET}px`;
      else s.right = `${r.right - t.left + SIDE_OFFSET}px`;
    } else {
      // horizontal align of the panel under the trigger
      let left = t.left - r.left;
      if (this.align === "center") left = t.left - r.left + t.width / 2 - width / 2;
      else if (this.align === "end") left = t.right - r.left - width;
      s.left = `${Math.max(0, left)}px`;
    }
  },

  positionArrow(trigger) {
    if (!this.arrow) return;
    const pr = this.positioner.getBoundingClientRect();
    const t = trigger.getBoundingClientRect();
    if (this.side === "bottom" || this.side === "top") {
      const center = t.left + t.width / 2 - pr.left;
      this.arrow.style.left = `${center}px`;
      this.arrow.style.removeProperty("top");
    }
  },

  // ---- hover / click timing -------------------------------------------------

  onTriggerEnter(value, e) {
    if (e.pointerType === "touch") return;
    this.cancelClose();
    if (this.value != null) {
      // already open → instant switch
      clearTimeout(this._open);
      this.activate(value, { reason: "trigger-hover" });
    } else {
      clearTimeout(this._open);
      this._open = setTimeout(() => {
        this.activate(value, { reason: "trigger-hover" });
        this.stick = true;
        clearTimeout(this._stick);
        this._stick = setTimeout(() => (this.stick = false), PATIENT_CLICK);
      }, this.delay);
    }
  },

  scheduleClose() {
    clearTimeout(this._close);
    this._close = setTimeout(() => {
      if (!this.overList && !this.overPopup) this.close("trigger-hover");
    }, this.closeDelay);
  },

  cancelClose() {
    clearTimeout(this._close);
  },

  onTriggerClick(value) {
    clearTimeout(this._open);
    this.cancelClose();
    if (this.stick) return; // patient click: ignore the click that follows a hover-open
    if (this.value === value) this.close("trigger-press");
    else this.activate(value, { reason: "trigger-press" });
  },

  onBlur() {
    // close if focus left the whole component
    requestAnimationFrame(() => {
      if (!this.el.contains(document.activeElement)) this.close("focus-out");
    });
  },

  // ---- keyboard -------------------------------------------------------------

  onTriggerKey(e, value) {
    const openKey = this.vertical ? "ArrowRight" : "ArrowDown";
    const triggers = this.triggers;
    const idx = triggers.findIndex((t) => t.value === value);

    if (e.key === openKey || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      this.activate(value, { reason: "list-navigation" });
    } else if (e.key === (this.vertical ? "ArrowDown" : "ArrowRight")) {
      e.preventDefault();
      this.focusTrigger(triggers[(idx + 1) % triggers.length]);
    } else if (e.key === (this.vertical ? "ArrowUp" : "ArrowLeft")) {
      e.preventDefault();
      this.focusTrigger(triggers[(idx - 1 + triggers.length) % triggers.length]);
    } else if (e.key === "Home") {
      e.preventDefault();
      this.focusTrigger(triggers[0]);
    } else if (e.key === "End") {
      e.preventDefault();
      this.focusTrigger(triggers[triggers.length - 1]);
    } else if (e.key === "Escape") {
      this.close("escape-key");
    }
  },

  focusTrigger(it) {
    if (!it) return;
    this.triggers.forEach((t) => t.trigger.setAttribute("tabindex", t === it ? "0" : "-1"));
    it.trigger.focus();
    if (this.value != null) this.activate(it.value, { reason: "list-navigation" });
  },

  onPopupKey(e) {
    if (e.key === "Escape") {
      e.preventDefault();
      this.close("escape-key");
    } else if (e.key === "Tab" && !e.shiftKey) {
      // leaving the popup forward closes the menu (focus proceeds naturally)
      const f = this.viewport.querySelectorAll('a,button,[tabindex]:not([tabindex="-1"]),input,select,textarea');
      if (f.length && document.activeElement === f[f.length - 1]) this.close("focus-out");
    }
  },
};

