/**
 * ScrollArea Hook for Phoenix LiveView — custom scrollbar engine (Base UI parity).
 *
 * Hides the native scrollbar and drives a custom `[data-part="thumb"]` inside a
 * `[data-part="scrollbar"]`: the thumb is sized PROPORTIONALLY to the content (exposed as the
 * `--scroll-area-thumb-height/width` CSS vars), positioned by transform as the viewport scrolls, and
 * draggable. A scrollbar is hidden when its axis doesn't overflow.
 *
 * Mirrors Base UI's state on the root + viewport + scrollbar(s) + content:
 *   data-scrolling                       — set briefly while scrolling
 *   data-hovering   (scrollbar)          — while the pointer is over the root
 *   data-has-overflow-x / -y             — when that axis overflows
 *   data-overflow-{x,y}-{start,end}      — when scrolled away from that edge
 * and exposes the distance from each edge as `--scroll-area-overflow-{x,y}-{start,end}` (px) so a
 * consumer can fade the edges (the Base UI "scroll fade" demo).
 *
 * Element lookup prefers `data-part` (headless); it falls back to the styled component's class names
 * (`.scroll-viewport`, `.thumb-y/x`, `.scrollbar-y/x`) so the existing styled scroll area keeps working.
 */

let ScrollArea = {
  mounted() {
    const { el } = this;
    this.viewport = q(el, '[data-part="viewport"]', ".scroll-viewport");
    this.content = this.viewport && this.viewport.querySelector('[data-part="content"]');
    this.scrollbarY = q(el, '[data-part="scrollbar"][data-orientation="vertical"]', ".scrollbar-y");
    this.scrollbarX = q(el, '[data-part="scrollbar"][data-orientation="horizontal"]', ".scrollbar-x");
    this.thumbY = (this.scrollbarY && this.scrollbarY.querySelector('[data-part="thumb"]')) || el.querySelector(".thumb-y");
    this.thumbX = (this.scrollbarX && this.scrollbarX.querySelector('[data-part="thumb"]')) || el.querySelector(".thumb-x");

    if (!this.viewport) {
      if (this.scrollbarY) this.scrollbarY.style.display = "none";
      if (this.scrollbarX) this.scrollbarX.style.display = "none";
      return;
    }

    this.boundUpdate = () => this.updateThumb();
    this.boundScroll = () => {
      this.markScrolling();
      this.updateThumb();
    };
    this.viewport.addEventListener("scroll", this.boundScroll, { passive: true });
    window.addEventListener("resize", this.boundUpdate);

    // hover state for auto-hiding scrollbars
    this.boundEnter = () => this.setHovering(true);
    this.boundLeave = () => this.setHovering(false);
    el.addEventListener("pointerenter", this.boundEnter);
    el.addEventListener("pointerleave", this.boundLeave);

    if (this.thumbY) {
      this.onThumbYPointerDownBound = (e) => this.onThumbYPointerDown(e);
      this.thumbY.addEventListener("pointerdown", this.onThumbYPointerDownBound);
    }
    if (this.thumbX) {
      this.onThumbXPointerDownBound = (e) => this.onThumbXPointerDown(e);
      this.thumbX.addEventListener("pointerdown", this.onThumbXPointerDownBound);
    }

    this.resizeObserver = new ResizeObserver(() => this.updateThumb());
    this.resizeObserver.observe(this.viewport);
    if (this.content) this.resizeObserver.observe(this.content);

    this.updateThumb();
  },

  updateAxis({ contentSize, clientSize, scrollPos, thumb, scrollbar, axis }) {
    const has = contentSize > clientSize + 1;
    if (!has) {
      if (scrollbar) scrollbar.style.display = "none";
      return;
    }
    if (scrollbar) scrollbar.style.display = "";
    if (thumb && scrollbar) {
      // PROPORTIONAL thumb size (Base UI): track * (viewport / content), min 20px. Exposed as a CSS
      // var so the consumer's thumb opts in with `height/width: var(--scroll-area-thumb-*)`.
      const trackSize = axis === "vertical" ? scrollbar.clientHeight : scrollbar.clientWidth;
      const thumbSize = Math.max(20, (clientSize / contentSize) * trackSize);
      this.el.style.setProperty(
        axis === "vertical" ? "--scroll-area-thumb-height" : "--scroll-area-thumb-width",
        `${thumbSize}px`,
      );
      const actual = (axis === "vertical" ? thumb.offsetHeight : thumb.offsetWidth) || thumbSize;
      const maxScroll = contentSize - clientSize;
      const maxThumb = trackSize - actual;
      const pos = maxScroll > 0 ? (scrollPos / maxScroll) * maxThumb : 0;
      thumb.style.transform = axis === "vertical" ? `translateY(${pos}px)` : `translateX(${pos}px)`;
    }
  },

  updateThumb() {
    if (!this.viewport) return;
    const v = this.viewport;

    const hasY = v.scrollHeight > v.clientHeight + 1;
    const hasX = v.scrollWidth > v.clientWidth + 1;

    this.updateAxis({ contentSize: v.scrollHeight, clientSize: v.clientHeight, scrollPos: v.scrollTop, thumb: this.thumbY, scrollbar: this.scrollbarY, axis: "vertical" });
    this.updateAxis({ contentSize: v.scrollWidth, clientSize: v.clientWidth, scrollPos: v.scrollLeft, thumb: this.thumbX, scrollbar: this.scrollbarX, axis: "horizontal" });

    // overflow presence
    this.flag("data-has-overflow-y", hasY, [this.el, this.viewport, this.scrollbarY, this.scrollbarX, this.content]);
    this.flag("data-has-overflow-x", hasX, [this.el, this.viewport, this.scrollbarX, this.scrollbarY, this.content]);

    // per-edge overflow distance (for the scroll-fade mask) + data flags
    const yStart = v.scrollTop;
    const yEnd = v.scrollHeight - v.clientHeight - v.scrollTop;
    const xStart = v.scrollLeft;
    const xEnd = v.scrollWidth - v.clientWidth - v.scrollLeft;
    const set = (name, px) => this.el.style.setProperty(name, `${Math.max(0, Math.round(px))}px`);
    set("--scroll-area-overflow-y-start", hasY ? yStart : 0);
    set("--scroll-area-overflow-y-end", hasY ? yEnd : 0);
    set("--scroll-area-overflow-x-start", hasX ? xStart : 0);
    set("--scroll-area-overflow-x-end", hasX ? xEnd : 0);
    this.flag("data-overflow-y-start", hasY && yStart > 0, [this.el, this.viewport, this.content]);
    this.flag("data-overflow-y-end", hasY && yEnd > 1, [this.el, this.viewport, this.content]);
    this.flag("data-overflow-x-start", hasX && xStart > 0, [this.el, this.viewport, this.content]);
    this.flag("data-overflow-x-end", hasX && xEnd > 1, [this.el, this.viewport, this.content]);
  },

  flag(attr, on, nodes) {
    nodes.forEach((n) => n && n.toggleAttribute(attr, on));
  },

  setHovering(on) {
    [this.scrollbarY, this.scrollbarX].forEach((s) => s && s.toggleAttribute("data-hovering", on));
  },

  markScrolling() {
    this.flag("data-scrolling", true, [this.el, this.viewport, this.scrollbarY, this.scrollbarX, this.content]);
    clearTimeout(this._scrollTimer);
    this._scrollTimer = setTimeout(
      () => this.flag("data-scrolling", false, [this.el, this.viewport, this.scrollbarY, this.scrollbarX, this.content]),
      500,
    );
  },

  // ---- thumb dragging (unchanged logic; thumb size read from offset*) --------

  onThumbYPointerDown(e) {
    e.preventDefault();
    this.isDraggingY = true;
    this.startY = e.clientY;
    this.startScrollTop = this.viewport.scrollTop;
    this.boundThumbYPointerMove = (ev) => this.onThumbYPointerMove(ev);
    this.boundThumbYPointerUp = () => this.onThumbYPointerUp();
    document.addEventListener("pointermove", this.boundThumbYPointerMove);
    document.addEventListener("pointerup", this.boundThumbYPointerUp);
  },

  onThumbYPointerMove(e) {
    e.preventDefault();
    const dy = e.clientY - this.startY;
    const { scrollHeight, clientHeight } = this.viewport;
    const thumbHeight = (this.thumbY && this.thumbY.offsetHeight) || 20;
    const maxScroll = scrollHeight - clientHeight;
    const maxThumb = clientHeight - thumbHeight;
    this.viewport.scrollTop = Math.max(0, Math.min(this.startScrollTop + dy * (maxScroll / maxThumb), maxScroll));
  },

  onThumbYPointerUp() {
    this.isDraggingY = false;
    document.removeEventListener("pointermove", this.boundThumbYPointerMove);
    document.removeEventListener("pointerup", this.boundThumbYPointerUp);
  },

  onThumbXPointerDown(e) {
    e.preventDefault();
    this.isDraggingX = true;
    this.startX = e.clientX;
    this.startScrollLeft = this.viewport.scrollLeft;
    this.boundThumbXPointerMove = (ev) => this.onThumbXPointerMove(ev);
    this.boundThumbXPointerUp = () => this.onThumbXPointerUp();
    document.addEventListener("pointermove", this.boundThumbXPointerMove);
    document.addEventListener("pointerup", this.boundThumbXPointerUp);
  },

  onThumbXPointerMove(e) {
    e.preventDefault();
    const dx = e.clientX - this.startX;
    const { scrollWidth, clientWidth } = this.viewport;
    const thumbWidth = (this.thumbX && this.thumbX.offsetWidth) || 20;
    const maxScroll = scrollWidth - clientWidth;
    const maxThumb = clientWidth - thumbWidth;
    this.viewport.scrollLeft = Math.max(0, Math.min(this.startScrollLeft + dx * (maxScroll / maxThumb), maxScroll));
  },

  onThumbXPointerUp() {
    this.isDraggingX = false;
    document.removeEventListener("pointermove", this.boundThumbXPointerMove);
    document.removeEventListener("pointerup", this.boundThumbXPointerUp);
  },

  destroyed() {
    this.viewport?.removeEventListener("scroll", this.boundScroll);
    window.removeEventListener("resize", this.boundUpdate);
    this.el.removeEventListener("pointerenter", this.boundEnter);
    this.el.removeEventListener("pointerleave", this.boundLeave);
    this.thumbY?.removeEventListener("pointerdown", this.onThumbYPointerDownBound);
    this.thumbX?.removeEventListener("pointerdown", this.onThumbXPointerDownBound);
    this.resizeObserver?.disconnect();
    clearTimeout(this._scrollTimer);
  },
};

function q(el, primary, fallback) {
  return el.querySelector(primary) || el.querySelector(fallback);
}

export default ScrollArea;

// PreviewCard — headless hover-card engine (Base UI parity).
//
// A `[data-part="trigger"]` (usually a link) reveals a `[data-part="popup"]` preview on
// hover or focus, anchored to it by side/align/offset (edge-flip + viewport clamp,
// repositioned on scroll/resize). Unlike the popover, it is NON-modal and never steals
// focus: pointer-leave (with a close delay) / blur / Escape dismiss it, and moving the
// pointer INTO the popup keeps it open. Motion + color are 100% CSS.

const PAD = 8;

const PreviewCard = {
  mounted() {
    this.trigger = this.el.querySelector('[data-part="trigger"]');
    this.popup = this.el.querySelector('[data-part="popup"]');

    this.side = this.el.getAttribute("data-side") || "bottom";
    this.align = this.el.getAttribute("data-align") || "center";
    this.sideOffset = parseFloat(this.el.getAttribute("data-side-offset")) || 0;
    this.alignOffset = parseFloat(this.el.getAttribute("data-align-offset")) || 0;
    this.delay = parseFloat(this.el.getAttribute("data-delay"));
    this.closeDelay = parseFloat(this.el.getAttribute("data-close-delay"));
    if (Number.isNaN(this.delay)) this.delay = 600;
    if (Number.isNaN(this.closeDelay)) this.closeDelay = 300;
    this.closeOnEscape = this.el.getAttribute("data-close-on-escape") !== "false";
    this.onOpenChange = this.el.getAttribute("data-on-open-change");
    this.onOpenChangeTarget = this.el.getAttribute("data-on-open-change-target");

    this.active = false;
    this.boundKeydown = (e) => this.handleKeydown(e);
    this.boundReposition = () => this.reposition();

    if (this.trigger && this.popup && this.popup.id) {
      this.trigger.setAttribute("aria-expanded", "false");
      this.trigger.addEventListener("pointerenter", () => this.scheduleOpen());
      this.trigger.addEventListener("pointerleave", () => this.scheduleClose());
      this.trigger.addEventListener("focusin", () => this.open());
      this.trigger.addEventListener("focusout", (e) => this.onFocusOut(e));
    }
    if (this.popup) {
      this.popup.addEventListener("pointerenter", () => this.cancelClose());
      this.popup.addEventListener("pointerleave", () => this.scheduleClose());
    }

    if (this.el.hasAttribute("data-open")) this.open(true);
  },

  updated() {
    const wantsOpen = this.el.hasAttribute("data-open");
    if (wantsOpen && !this.active) this.open(true);
    else if (!wantsOpen && this.active) this.close(true);
  },

  destroyed() {
    this.teardown();
    if (this.openTimer) clearTimeout(this.openTimer);
    if (this.closeTimer) clearTimeout(this.closeTimer);
  },

  // ---- scheduling --------------------------------------------------------
  scheduleOpen() {
    this.cancelClose();
    if (this.active) return;
    this.openTimer = setTimeout(() => this.open(), this.delay);
  },
  scheduleClose() {
    if (this.openTimer) clearTimeout(this.openTimer);
    this.closeTimer = setTimeout(() => this.close(), this.closeDelay);
  },
  cancelClose() {
    if (this.closeTimer) clearTimeout(this.closeTimer);
    this.closeTimer = null;
  },
  onFocusOut(e) {
    // close only when focus leaves both the trigger and the popup
    const to = e.relatedTarget;
    if (to && (this.trigger.contains(to) || (this.popup && this.popup.contains(to)))) return;
    this.scheduleClose();
  },

  // ---- open / close ------------------------------------------------------
  open(serverDriven = false) {
    if (this.openTimer) clearTimeout(this.openTimer);
    this.cancelClose();
    if (this.active) return;
    this.active = true;
    this.positionPopup();
    this.popup.hidden = false;
    this.popup.toggleAttribute("data-open", true);
    this.popup.removeAttribute("data-closed");
    this.popup.setAttribute("data-starting-style", "");
    requestAnimationFrame(() =>
      requestAnimationFrame(() => this.popup && this.popup.removeAttribute("data-starting-style")),
    );
    this.el.toggleAttribute("data-open", true);
    this.el.toggleAttribute("data-closed", false);
    if (this.trigger) {
      this.trigger.setAttribute("aria-expanded", "true");
      this.trigger.toggleAttribute("data-popup-open", true);
    }
    document.addEventListener("keydown", this.boundKeydown, true);
    window.addEventListener("scroll", this.boundReposition, true);
    window.addEventListener("resize", this.boundReposition);
    if (!serverDriven) this.emitOpenChange(true);
  },

  close(serverDriven = false) {
    if (this.closeTimer) clearTimeout(this.closeTimer);
    if (!this.active) return;
    this.active = false;
    this.popup.toggleAttribute("data-open", false);
    this.popup.setAttribute("data-closed", "");
    this.popup.hidden = true;
    this.el.toggleAttribute("data-open", false);
    this.el.toggleAttribute("data-closed", true);
    if (this.trigger) {
      this.trigger.setAttribute("aria-expanded", "false");
      this.trigger.toggleAttribute("data-popup-open", false);
    }
    this.teardown();
    if (!serverDriven) this.emitOpenChange(false);
  },

  teardown() {
    document.removeEventListener("keydown", this.boundKeydown, true);
    window.removeEventListener("scroll", this.boundReposition, true);
    window.removeEventListener("resize", this.boundReposition);
  },

  reposition() {
    if (this.active) this.positionPopup();
  },

  emitOpenChange(open) {
    if (!this.onOpenChange) return;
    if (this.onOpenChangeTarget) this.pushEventTo(this.onOpenChangeTarget, this.onOpenChange, { open });
    else this.pushEventTo(this.el, this.onOpenChange, { open });
  },

  handleKeydown(e) {
    if (this.active && e.key === "Escape" && this.closeOnEscape) {
      e.preventDefault();
      this.close();
    }
  },

  // ---- anchored positioning (fixed; flip on the main axis + clamp) --------
  positionPopup() {
    const popup = this.popup;
    popup.style.position = "fixed";
    popup.style.left = "0px";
    popup.style.top = "0px";
    popup.style.visibility = "hidden";
    popup.hidden = false;
    popup.removeAttribute("data-closed");
    const a = this.trigger.getBoundingClientRect();
    const p = popup.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const off = this.sideOffset;
    let side = this.side;

    if (side === "bottom" && a.bottom + off + p.height > vh - PAD && a.top - off - p.height > PAD) side = "top";
    else if (side === "top" && a.top - off - p.height < PAD && a.bottom + off + p.height < vh - PAD) side = "bottom";
    else if (side === "right" && a.right + off + p.width > vw - PAD && a.left - off - p.width > PAD) side = "left";
    else if (side === "left" && a.left - off - p.width < PAD && a.right + off + p.width < vw - PAD) side = "right";

    let left;
    let top;
    if (side === "bottom" || side === "top") {
      top = side === "bottom" ? a.bottom + off : a.top - p.height - off;
      if (this.align === "start") left = a.left + this.alignOffset;
      else if (this.align === "end") left = a.right - p.width - this.alignOffset;
      else left = a.left + (a.width - p.width) / 2 + this.alignOffset;
    } else {
      left = side === "right" ? a.right + off : a.left - p.width - off;
      if (this.align === "start") top = a.top + this.alignOffset;
      else if (this.align === "end") top = a.bottom - p.height - this.alignOffset;
      else top = a.top + (a.height - p.height) / 2 + this.alignOffset;
    }

    left = Math.min(Math.max(left, PAD), Math.max(PAD, vw - p.width - PAD));
    top = Math.min(Math.max(top, PAD), Math.max(PAD, vh - p.height - PAD));
    popup.style.left = `${left}px`;
    popup.style.top = `${top}px`;
    popup.setAttribute("data-side", side);
    popup.setAttribute("data-align", this.align);
    // Pin the arrow to the popup edge, centered on the trigger (Base UI's Arrow does this inside the
    // component, so the demo's arrow class stays verbatim — no stylesheet needed).
    const arrow = popup.querySelector('[data-part="arrow"]');
    if (arrow) {
      const center = `${-arrow.offsetWidth / 2}px`;
      const vertical = side === "left" || side === "right";
      arrow.setAttribute("data-side", side);
      arrow.style.position = "absolute";
      arrow.style.left = vertical ? "" : "50%";
      arrow.style.marginLeft = vertical ? "" : center;
      arrow.style.top = vertical ? "50%" : "";
      arrow.style.marginTop = vertical ? center : "";
    }
    popup.style.visibility = "";
  },
};

export default PreviewCard;

// RollingNumber — animate a number to a new value (Mantine RollingNumber parity).
//
// On mount it rolls from 0 up to `data-value`; whenever LiveView re-renders with a new `data-value`
// it animates from the current value to the new one (requestAnimationFrame, ease-out). `data-duration`
// (ms, default 800) sets the speed and `data-locale` the thousands grouping. Respects
// `prefers-reduced-motion` by jumping straight to the value.

const RollingNumber = {
  mounted() {
    this.current = 0;
    this.animateTo(this.target());
  },

  updated() {
    this.animateTo(this.target());
  },

  target() {
    return Number(this.el.getAttribute("data-value")) || 0;
  },

  format(n) {
    const locale = this.el.getAttribute("data-locale") || undefined;
    return Math.round(n).toLocaleString(locale);
  },

  animateTo(target) {
    const from = this.current;
    if (from === target) {
      this.el.textContent = this.format(target);
      return;
    }

    const reduce =
      window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const dur = reduce ? 0 : Number(this.el.getAttribute("data-duration")) || 800;

    if (dur <= 0) {
      this.current = target;
      this.el.textContent = this.format(target);
      return;
    }

    const start = performance.now();
    cancelAnimationFrame(this._raf);

    const tick = (now) => {
      const t = Math.min(1, (now - start) / dur);
      const eased = 1 - Math.pow(1 - t, 3);
      const val = from + (target - from) * eased;
      this.el.textContent = this.format(val);
      if (t < 1) {
        this._raf = requestAnimationFrame(tick);
      } else {
        this.current = target;
        this.el.textContent = this.format(target);
      }
    };

    this._raf = requestAnimationFrame(tick);
  },

  destroyed() {
    cancelAnimationFrame(this._raf);
  },
};

export default RollingNumber;

// FloatingIndicator — a single highlight box that measures the active target and slides over it
// (Mantine FloatingIndicator parity).
//
// The active target is the one whose `data-value` matches the root's `data-active`. Clicking a target
// moves the indicator (and pushes `data-on-change` if set); the server can also drive it by changing
// `data-active`. A `ResizeObserver` keeps the indicator aligned when the container resizes.
//
// Element contract:
//   root                      — carries the hook; data-active, data-on-change; position: relative
//   [data-part="indicator"]   — the moving box (engine sets transform + width/height)
//   [data-part="target"]      — each option; must have data-value; gets data-active when selected

const FloatingIndicator = {
  mounted() {
    this.on = this.el.getAttribute("data-on-change");
    this.indicator = this.el.querySelector('[data-part="indicator"]');
    this.active = this.el.getAttribute("data-active");

    this._onClick = (e) => {
      const t = e.target.closest('[data-part="target"]');
      if (t && this.el.contains(t)) this.setActive(t.getAttribute("data-value"), true);
    };
    this.el.addEventListener("click", this._onClick);

    this._ro = new ResizeObserver(() => this.move());
    this._ro.observe(this.el);
    this.targets().forEach((t) => this._ro.observe(t));

    requestAnimationFrame(() => this.sync());
  },

  targets() {
    return Array.from(this.el.querySelectorAll('[data-part="target"]'));
  },

  activeTarget() {
    const ts = this.targets();
    return ts.find((t) => t.getAttribute("data-value") === this.active) || ts[0];
  },

  setActive(value, push) {
    if (value == null || value === this.active) return;
    this.active = value;
    this.sync();
    if (push && this.on) this.pushEventTo(this.el, this.on, { value });
  },

  sync() {
    const at = this.activeTarget();
    this.targets().forEach((t) => {
      const on = t === at;
      t.toggleAttribute("data-active", on);
      t.setAttribute("aria-pressed", on ? "true" : "false");
    });
    if (at) this.el.setAttribute("data-active", at.getAttribute("data-value"));
    this.move();
  },

  move() {
    const at = this.activeTarget();
    if (!at || !this.indicator) return;
    const p = this.el.getBoundingClientRect();
    const r = at.getBoundingClientRect();
    const x = r.left - p.left + this.el.scrollLeft;
    const y = r.top - p.top + this.el.scrollTop;
    this.indicator.style.transform = `translate(${x}px, ${y}px)`;
    this.indicator.style.width = `${r.width}px`;
    this.indicator.style.height = `${r.height}px`;
  },

  updated() {
    const a = this.el.getAttribute("data-active");
    if (a != null) this.active = a;
    this.sync();
  },

  destroyed() {
    this.el.removeEventListener("click", this._onClick);
    if (this._ro) this._ro.disconnect();
  },
};

export default FloatingIndicator;

// ToastRegion — headless toast manager with a collapsible stack (Base UI parity).
//
// The viewport ([data-part="viewport"]) is a polite `aria-live` region that STACKS toasts: newest in
// front, older ones peeking behind; hovering or focusing the viewport EXPANDS them into a full
// list (and pauses auto-dismiss). A [data-part="trigger"] button clones [data-part="template"]'s
// toast on click (filling any [data-toast-count] with a running number). Each toast auto-dismisses
// after its data-duration (default 5000ms; 0 = sticky); a [data-part="close"] button or the timer
// closes it with an exit animation. Static [data-part="toast"] children rendered up-front (or
// streamed by LiveView) are adopted too.
//
// The hook only writes per-toast LAYOUT VARS — the consuming CSS does the transforms:
//   on each toast: --toast-index (0=front) · --toast-offset-y (px of toasts in front) ·
//                  --toast-height (measured natural px) · --toast-swipe-movement-x/y
//   on the viewport: --toast-frontmost-height (the front toast's height)
// State attrs: viewport+toast [data-expanded]; toast [data-open]/[data-closed],
//   [data-starting-style]/[data-ending-style] (enter/exit), [data-limited] (beyond data-limit);
//   content [data-behind] (collapsed and not frontmost).

const EXIT_MS = 500;

const ToastRegion = {
  mounted() {
    this.viewport = this.el.querySelector('[data-part="viewport"]') || this.el;
    this.template = this.el.querySelector('[data-part="template"]');
    this.limit = parseInt(this.el.getAttribute("data-limit") ?? "3", 10);
    this.count = 0;
    this.hovered = false;
    this.focused = false;
    this.expanded = false;
    this.timers = new WeakMap();
    this.exitTimers = new Set();
    this.rafs = new Set();
    this.cleanup = [];

    this.el.querySelectorAll('[data-part="trigger"]').forEach((b) => this.on(b, "click", () => this.add()));
    this.on(this.viewport, "pointerenter", () => this.setHover(true));
    this.on(this.viewport, "pointerleave", () => this.setHover(false));
    this.on(this.viewport, "focusin", () => this.setFocus(true));
    this.on(this.viewport, "focusout", (e) => {
      if (!this.viewport.contains(e.relatedTarget)) this.setFocus(false);
    });

    this.toasts().forEach((t) => this.wire(t));
    this.restack();
  },

  updated() {
    this.toasts().forEach((t) => this.wire(t));
    this.restack();
  },

  destroyed() {
    this.toasts().forEach((t) => this.clearTimer(t));
    this.exitTimers.forEach((id) => clearTimeout(id));
    this.rafs.forEach((id) => cancelAnimationFrame(id));
    this.cleanup.forEach((off) => off());
  },

  on(target, type, fn) {
    target.addEventListener(type, fn);
    this.cleanup.push(() => target.removeEventListener(type, fn));
  },

  toasts() {
    return Array.from(this.viewport.querySelectorAll('[data-part="toast"]'));
  },

  // Clone the template's toast to the front of the stack (newest first), animate it in. If the
  // template carries a data-toast-key, dedup: an existing toast with that key is refreshed (brought
  // to front + timer reset) instead of stacking a duplicate.
  add() {
    const tpl = this.template && (this.template.content || this.template);
    const src = tpl && tpl.querySelector('[data-part="toast"]');
    if (!src) return;
    const key = src.getAttribute("data-toast-key");
    if (key) {
      const existing = this.toasts().find(
        (t) => t.getAttribute("data-toast-key") === key && !t.hasAttribute("data-ending-style"),
      );
      if (existing) {
        this.viewport.prepend(existing);
        this.startTimer(existing);
        this.restack();
        return;
      }
    }
    this.count += 1;
    const toast = src.cloneNode(true);
    toast.querySelectorAll("[data-toast-count]").forEach((el) => (el.textContent = this.count));
    toast.setAttribute("data-open", "");
    toast.setAttribute("data-starting-style", "");
    if (this.expanded) toast.setAttribute("data-expanded", "");
    this.viewport.prepend(toast);
    this.wire(toast);
    this.restack();
    const raf = requestAnimationFrame(() => {
      this.rafs.delete(raf);
      void toast.offsetHeight;
      toast.removeAttribute("data-starting-style");
      this.restack();
    });
    this.rafs.add(raf);
  },

  wire(toast) {
    if (toast._wired) return;
    toast._wired = true;
    toast
      .querySelectorAll('[data-part="close"]')
      .forEach((b) => this.on(b, "click", () => this.dismiss(toast)));
    toast._duration = parseInt(toast.getAttribute("data-duration") ?? "5000", 10);
    this.startTimer(toast);
  },

  startTimer(toast) {
    this.clearTimer(toast);
    if (toast._duration > 0 && !this.expanded && !toast.hasAttribute("data-ending-style")) {
      this.timers.set(
        toast,
        setTimeout(() => this.dismiss(toast), toast._duration),
      );
    }
  },

  clearTimer(toast) {
    const id = this.timers.get(toast);
    if (id) {
      clearTimeout(id);
      this.timers.delete(toast);
    }
  },

  setHover(on) {
    this.hovered = on;
    this.syncExpanded();
  },

  setFocus(on) {
    this.focused = on;
    this.syncExpanded();
  },

  // Expanded = hovered OR focused — so leaving with the mouse never collapses while a toast button
  // is still keyboard-focused (and vice-versa). Pauses/resumes every timer accordingly.
  syncExpanded() {
    const want = this.hovered || this.focused;
    if (want === this.expanded) return;
    this.expanded = want;
    this.viewport.toggleAttribute("data-expanded", want);
    this.toasts().forEach((t) => {
      t.toggleAttribute("data-expanded", want);
      want ? this.clearTimer(t) : this.startTimer(t);
    });
    this.restack();
  },

  // Measure natural heights and publish the stacking vars.
  restack() {
    if (!this.viewport.isConnected) return;
    const active = this.toasts().filter((t) => !t.hasAttribute("data-ending-style"));
    let offset = 0;
    let front = 0;
    active.forEach((toast, i) => {
      const h = this.naturalHeight(toast);
      toast.style.setProperty("--toast-index", i);
      toast.style.setProperty("--toast-offset-y", `${offset}px`);
      toast.style.setProperty("--toast-height", `${h}px`);
      toast.style.setProperty("--toast-swipe-movement-x", "0px");
      toast.style.setProperty("--toast-swipe-movement-y", "0px");
      toast.toggleAttribute("data-limited", i >= this.limit);
      const content = toast.querySelector('[data-part="content"]');
      if (content) content.toggleAttribute("data-behind", i > 0 && !this.expanded);
      if (i === 0) front = h;
      offset += h;
    });
    this.viewport.style.setProperty("--toast-frontmost-height", `${front}px`);
  },

  // The toast's natural height. The CSS otherwise pins it to the front/var height, so we briefly
  // override to `auto` and read offsetHeight (the layout height, unaffected by the scale() transform
  // — unlike getBoundingClientRect), then hand it back to the stylesheet.
  naturalHeight(toast) {
    toast.style.setProperty("height", "auto", "important");
    const h = toast.offsetHeight;
    toast.style.removeProperty("height");
    return h;
  },

  dismiss(toast) {
    if (toast.hasAttribute("data-ending-style")) return;
    this.clearTimer(toast);
    toast.removeAttribute("data-open");
    toast.setAttribute("data-closed", "");
    toast.setAttribute("data-ending-style", "");
    this.restack();
    const id = setTimeout(() => {
      this.exitTimers.delete(id);
      toast.remove();
      this.restack();
    }, EXIT_MS);
    this.exitTimers.add(id);
  },
};

export default ToastRegion;

stylesheets.content:
/* === mishka_chelekom_headless.css === */
/* Mishka Chelekom — headless base styles.
 *
 * FUNCTIONAL ONLY: visibility, positioning and accessibility primitives that make the
 * headless components behave. NO colors, spacing, typography or other opinionated styling —
 * that is the consuming app's job (target the `chelekom-*` classes and `data-*` state).
 *
 * State convention (paired-presence): elements carry `data-open` or `data-closed`.
 */

/* Closed overlays are removed from the layout. */
.chelekom-popover__popup[data-closed],
.chelekom-menu__popup[data-closed],
.chelekom-menu__submenu-popup[data-closed],
.chelekom-tooltip__popup[data-closed],
.chelekom-select__popup[data-closed],
.chelekom-preview_card__popup[data-closed],
.chelekom-context_menu__popup[data-closed],
.chelekom-context_menu__submenu-popup[data-closed],
.chelekom-menubar__popup[data-closed],
.chelekom-navigation_menu__panel[data-closed],
.chelekom-combobox__popup[data-closed],
.chelekom-autocomplete__popup[data-closed] {
    display: none;
}

/* The selected-item check lives in EVERY option (Base UI conditionally renders ItemIndicator);
   reveal it only on the selected option. `visibility` keeps the reserved column so rows don't shift. */
.chelekom-select__option:not([data-selected]) .chelekom-select__indicator {
    visibility: hidden;
}

/* Alert dialog: the root is a passthrough so the trigger stays in normal flow
 * (always visible/clickable). The backdrop + popup are fixed overlays shown only
 * while open; the popup is centered by default. */
.chelekom-alert-dialog {
    display: contents;
}

.chelekom-alert-dialog__backdrop {
    position: fixed;
    inset: 0;
    z-index: 40;
}

.chelekom-alert-dialog__popup {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    z-index: 50;
}

.chelekom-alert-dialog[data-closed] .chelekom-alert-dialog__backdrop,
.chelekom-alert-dialog__popup[data-closed] {
    display: none;
}

/* Drawer: the root is a passthrough so the trigger stays in normal flow (always
 * visible/clickable). The viewport + backdrop are fixed overlays; the popup is pinned to
 * an edge and slides via the --drawer-* vars. Size/colors/padding stay consumer-owned. */
.chelekom-drawer {
    display: contents;
}

.chelekom-drawer__viewport {
    position: fixed;
    inset: 0;
    z-index: 50;
    overflow: hidden;
    pointer-events: none;
}

.chelekom-drawer__backdrop {
    position: fixed;
    inset: 0;
    z-index: 40;
    transition: opacity 450ms cubic-bezier(0.32, 0.72, 0, 1);
}

.chelekom-drawer__backdrop[data-swiping] {
    transition-duration: 0ms;
}

.chelekom-drawer[data-closed] .chelekom-drawer__backdrop {
    opacity: 0;
    pointer-events: none;
}

.chelekom-drawer__popup {
    position: absolute;
    pointer-events: auto;
    transition: transform 450ms cubic-bezier(0.32, 0.72, 0, 1);
}

.chelekom-drawer__popup[data-swiping] {
    transition-duration: 0ms;
    user-select: none;
}

.chelekom-drawer__popup[data-ending-style] {
    transition-duration: calc(450ms * var(--drawer-swipe-strength, 1));
}

.chelekom-drawer__popup[data-side="right"] {
    top: 0;
    right: 0;
    height: 100%;
    transform: translateX(var(--drawer-swipe-movement-x, 0px));
}
.chelekom-drawer__popup[data-side="right"][data-closed],
.chelekom-drawer__popup[data-side="right"][data-starting-style],
.chelekom-drawer__popup[data-side="right"][data-ending-style] {
    transform: translateX(100%);
}

.chelekom-drawer__popup[data-side="left"] {
    top: 0;
    left: 0;
    height: 100%;
    transform: translateX(var(--drawer-swipe-movement-x, 0px));
}
.chelekom-drawer__popup[data-side="left"][data-closed],
.chelekom-drawer__popup[data-side="left"][data-starting-style],
.chelekom-drawer__popup[data-side="left"][data-ending-style] {
    transform: translateX(-100%);
}

.chelekom-drawer__popup[data-side="bottom"] {
    left: 0;
    right: 0;
    bottom: 0;
    width: 100%;
    transform: translateY(calc(var(--drawer-snap-point-offset, 0px) + var(--drawer-swipe-movement-y, 0px)));
}
.chelekom-drawer__popup[data-side="bottom"][data-closed],
.chelekom-drawer__popup[data-side="bottom"][data-starting-style],
.chelekom-drawer__popup[data-side="bottom"][data-ending-style] {
    transform: translateY(100%);
}

.chelekom-drawer__popup[data-side="top"] {
    left: 0;
    right: 0;
    top: 0;
    width: 100%;
    transform: translateY(var(--drawer-swipe-movement-y, 0px));
}
.chelekom-drawer__popup[data-side="top"][data-closed],
.chelekom-drawer__popup[data-side="top"][data-starting-style],
.chelekom-drawer__popup[data-side="top"][data-ending-style] {
    transform: translateY(-100%);
}

.chelekom-drawer__swipe-area {
    pointer-events: auto;
    touch-action: none;
}

/* Page indent (iOS-style): the hook toggles data-active on [data-drawer-content] while a
 * drawer under the same [data-drawer-provider] is open; the scale/radius stay consumer-owned. */
[data-drawer-content] {
    transform-origin: center top;
    transition:
        transform 0.4s cubic-bezier(0.32, 0.72, 0, 1),
        border-radius 0.25s cubic-bezier(0.32, 0.72, 0, 1);
}

/* OTP boxes lay out in a row by default. */
.chelekom-otp_field {
    display: inline-flex;
    gap: 0.5rem;
}

/* Dialog: the root is a passthrough so the trigger stays in normal flow (always visible).
 * The backdrop + viewport are fixed overlays; the viewport centers the popup and scrolls
 * tall dialogs. Colors/size/padding stay consumer-owned. */
.chelekom-dialog {
    display: contents;
}

.chelekom-dialog__backdrop {
    position: fixed;
    inset: 0;
    z-index: 40;
}

.chelekom-dialog__viewport {
    position: fixed;
    inset: 0;
    z-index: 50;
    display: grid;
    place-items: center;
    overflow-y: auto;
    pointer-events: none;
}

.chelekom-dialog__popup {
    position: relative;
    max-height: 90vh;
    overflow: auto;
    pointer-events: auto;
}

.chelekom-dialog[data-closed] .chelekom-dialog__backdrop,
.chelekom-dialog__popup[data-closed] {
    display: none;
}

/* Disclosure: panel hidden when collapsed. */
.chelekom-disclosure__panel[data-closed] {
    display: none;
}

/* Tabs: only the active panel is shown. */
.chelekom-tabs__panel[data-closed] {
    display: none;
}

/* Floating popups position relative to their anchor; the JS engine sets the offsets. */
.chelekom-popover,
.chelekom-menu,
.chelekom-tooltip,
.chelekom-select {
    position: relative;
}

.chelekom-popover,
.chelekom-menu,
.chelekom-tooltip,
.chelekom-select,
.chelekom-preview_card,
.chelekom-context_menu,
.chelekom-combobox,
.chelekom-autocomplete,
.chelekom-navigation_menu__popup-root,
.chelekom-menubar__menu {
    position: relative;
}

.chelekom-popover__popup,
.chelekom-menu__popup,
.chelekom-tooltip__popup,
.chelekom-select__popup,
.chelekom-preview_card__popup,
.chelekom-context_menu__popup,
.chelekom-menubar__popup,
.chelekom-navigation_menu__panel,
.chelekom-combobox__popup,
.chelekom-autocomplete__popup {
    position: absolute;
    z-index: 40;
}

/* Context menu: the engine positions the popups `fixed` at the cursor (inline left/top),
 * so keep them above content and hide the checkbox/radio indicator until checked. */
.chelekom-context_menu__popup,
.chelekom-context_menu__submenu-popup {
    position: fixed;
    z-index: 50;
}

.chelekom-context_menu__indicator[data-unchecked] {
    visibility: hidden;
}

/* Menu: the engine anchors the popups to the trigger via inline fixed left/top. */
.chelekom-menu__popup,
.chelekom-menu__submenu-popup {
    position: fixed;
    z-index: 50;
}

.chelekom-menu__indicator[data-unchecked] {
    visibility: hidden;
}

/* Popover: the engine anchors the popup to the trigger via inline fixed left/top. */
.chelekom-popover__popup {
    position: fixed;
    z-index: 50;
}

.chelekom-popover__backdrop {
    position: fixed;
    inset: 0;
    z-index: 40;
}

.chelekom-popover[data-closed] .chelekom-popover__backdrop {
    display: none;
}

/* Preview card: hover-card popup anchored to the trigger via inline fixed left/top. */
.chelekom-preview_card__popup {
    position: fixed;
    z-index: 50;
}

/* Tooltip: hover popup anchored to the trigger via inline fixed left/top. */
.chelekom-tooltip__popup {
    position: fixed;
    z-index: 50;
}

/* Roving / composite items: the engine moves a single tabindex=0 and marks the active one. */
[data-part="item"][data-disabled] {
    pointer-events: none;
    opacity: 0.5;
}

/* Combobox/autocomplete: non-matching options (and empty groups / the empty-state) are hidden by
   the engine via data-hidden; the empty-state is shown only when nothing matches. */
[data-part="item"][data-hidden],
[data-part="group"][data-hidden],
[data-part="empty"][data-hidden] {
    display: none;
}

/* Navigation-menu panel hidden when collapsed. (The collapsible is NOT listed here: like the
   accordion it carries the `hidden` attribute, which the JS engine times after the exit transition,
   so the panel stays visible while collapsing — a `[data-closed] { display:none }` would snap it shut.) */
.chelekom-navigation_menu__panel[data-closed] {
    display: none;
}

/* Slider: the engine positions the indicator + thumbs inline (Base UI style — left/top/bottom plus
   the `translate` property, so consumers can still add their own `transform`); the track is the
   positioning context. */
.chelekom-slider {
    position: relative;
}
.chelekom-slider__track {
    position: relative;
}
.chelekom-slider__thumb {
    position: absolute;
}

/* Progress / meter: the engine-free indicator width is driven by a CSS var on the element. */
/* progress/meter fill width+height are set inline by the component (see the indicator's
   `style`) so the headless component ships zero styling here — consumers use plain Tailwind. */

/* Toast: positioning + the collapsible stack are entirely consumer CSS — the engine only writes the
   layout vars (--toast-index / --toast-offset-y / --toast-height on each toast, --toast-frontmost-height
   on the viewport) and toggles data-expanded / data-limited / data-behind / data-starting|ending-style.
   Style the viewport (fixed/anchored) and the toasts (absolute), e.g. transform from the vars. */

/* Visually-hidden helper for native inputs backing headless form controls. */
.chelekom-sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}
/* Scroll area: hide the native scrollbar; the ScrollArea hook drives the custom scrollbar/thumb. The
   thumb sizes itself from the hook-set CSS vars; scrollbars overlay the edges per data-orientation. */
.chelekom-scroll_area {
    position: relative;
}
.chelekom-scroll_area__viewport {
    width: 100%;
    height: 100%;
    overflow: auto;
    scrollbar-width: none;
    -ms-overflow-style: none;
}
.chelekom-scroll_area__viewport::-webkit-scrollbar {
    display: none;
}
.chelekom-scroll_area[data-orientation="vertical"] .chelekom-scroll_area__viewport {
    overflow-x: hidden;
}
.chelekom-scroll_area[data-orientation="horizontal"] .chelekom-scroll_area__viewport {
    overflow-y: hidden;
}
.chelekom-scroll_area__scrollbar {
    position: absolute;
}
.chelekom-scroll_area__scrollbar[data-orientation="vertical"] {
    top: 0;
    right: 0;
    bottom: 0;
}
.chelekom-scroll_area__scrollbar[data-orientation="horizontal"] {
    left: 0;
    right: 0;
    bottom: 0;
}
.chelekom-scroll_area__thumb[data-orientation="vertical"] {
    height: var(--scroll-area-thumb-height, 2.5rem);
}
.chelekom-scroll_area__thumb[data-orientation="horizontal"] {
    width: var(--scroll-area-thumb-width, 2.5rem);
}
/* Navigation menu: the engine moves the active item's content into the shared viewport and MORPHS the
   popup size via --popup-width/height (the positioner holds the final --positioner-width/height). */
.chelekom-navigation_menu {
    position: relative;
}
.chelekom-navigation_menu__list { display: flex; }
.chelekom-navigation_menu[data-orientation="vertical"] .chelekom-navigation_menu__list { flex-direction: column; }
.chelekom-navigation_menu__positioner {
    position: absolute;
    z-index: 40;
    width: var(--positioner-width, auto);
    height: var(--positioner-height, auto);
}
.chelekom-navigation_menu__positioner[data-closed] {
    display: none;
}
.chelekom-navigation_menu__popup {
    position: relative;
    width: var(--popup-width, auto);
    height: var(--popup-height, auto);
    overflow: hidden;
    transition: width 0.2s ease, height 0.2s ease;
}
.chelekom-navigation_menu__positioner[data-instant] .chelekom-navigation_menu__popup {
    transition: none;
}
.chelekom-navigation_menu__viewport {
    position: relative;
    width: 100%;
    height: 100%;
    overflow: hidden;
}
.chelekom-navigation_menu__content[hidden] {
    display: none !important;
}
@keyframes chelekom-nm-right { from { transform: translateX(35px); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes chelekom-nm-left  { from { transform: translateX(-35px); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes chelekom-nm-down  { from { transform: translateY(18px); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes chelekom-nm-up    { from { transform: translateY(-18px); opacity: 0; } to { transform: none; opacity: 1; } }
.chelekom-navigation_menu__content[data-activation-direction="right"] { animation: chelekom-nm-right 0.2s ease; }
.chelekom-navigation_menu__content[data-activation-direction="left"]  { animation: chelekom-nm-left 0.2s ease; }
.chelekom-navigation_menu__content[data-activation-direction="down"]  { animation: chelekom-nm-down 0.2s ease; }
.chelekom-navigation_menu__content[data-activation-direction="up"]    { animation: chelekom-nm-up 0.2s ease; }
/* Tabs: the tablist is the positioning context for the indicator; the hook publishes --active-tab-*
   on it (and the indicator). Inactive panels carry `hidden`. */
.chelekom-tabs__list {
    position: relative;
}
.chelekom-tabs__panel[hidden] {
    display: none;
}

/* The scrub-area virtual cursor is shown only while scrubbing (the NumberField hook toggles
 * data-scrubbing on it); hide it otherwise so it never lingers at the viewport origin (top-left)
 * after a scrub ends. */
[data-part="scrub-area-cursor"]:not([data-scrubbing]) {
    display: none;
}

/* Editor: the editing surface. Functional only — the editable area must FILL the surface, the
 * caret must not be boxed in, and an empty document must still show its placeholder.
 *
 * Every engine nests its editable node differently: TipTap renders `.ProseMirror` directly,
 * Milkdown wraps it in `.milkdown`, CodeMirror builds `.cm-editor > .cm-scroller`. Each wrapper
 * has to stretch, or a click below the last line lands on a non-editable box and no caret
 * appears — the user has to aim at the text itself.
 *
 * Deliberately NOT here: typography. Under Tailwind Preflight the editor's headings, lists and
 * blockquotes render flat, and styling them is the consuming app's job — see the showcase demo. */
.chelekom-editor__surface {
    display: flex;
    flex-direction: column;
}

.chelekom-editor__surface > *,
.chelekom-editor__surface .milkdown {
    flex: 1 1 auto;
    min-width: 0;
}

.chelekom-editor__surface .milkdown {
    display: flex;
    flex-direction: column;
}

.chelekom-editor__surface .ProseMirror,
.chelekom-editor__surface .cm-editor {
    flex: 1 1 auto;
    outline: none;
}

.chelekom-editor__surface .ProseMirror {
    white-space: pre-wrap;
    word-break: break-word;
}

/* `attr()` reads from the element the pseudo-element belongs to, so each engine mirrors
 * data-placeholder onto its own editable node. Floating it with zero height overlays it on the
 * first line instead of pushing the caret down. */
.chelekom-editor[data-empty] .chelekom-editor__surface .ProseMirror::before,
.chelekom-editor[data-empty] .chelekom-editor__surface [data-part="lexical-content"]::before {
    content: attr(data-placeholder);
    float: left;
    height: 0;
    pointer-events: none;
}
